terraform {
  required_version = "= 1.16.0" # 예: "= 1.16.0" (도구 저장소 tool-versions 고정값과 동일)

  required_providers {
    aws = {
      source  = "hashicorp/aws" # 예: "hashicorp/aws" (공식 레지스트리 경로)
      version = "= 6.62.0"      # 예: "= 6.62.0" (과정 전체의 provider 고정값)
    }
  }
}

