# variables.tf — modules/edge (dev · prod 루트 모듈이 공유하는 모듈)

variable "enabled" {
  description = "Create CloudFront, WAF, viewer certificate and app DNS records; false keeps the root at zero AWS resources."
  type        = bool  # 예: bool
  default     = false # 기본값: false (기본은 만들지 않음)
  nullable    = false
}

variable "expected_account_id" {
  description = "AWS account that owns the NLB, the public zone and the CloudFront distribution; 12 digits."
  type        = string # 예: "111111111111"
  nullable    = false

  validation {
    condition     = can(regex("^[0-9]{12}$", var.expected_account_id)) # 예: 숫자 12자리만 통과
    error_message = "Use a 12-digit account ID."
  }
}

variable "gateway_contract" {
  description = "Six items of the gateway root output: cluster_name, vpc_id, exposure_mode, nlb_security_group_id, public_zone_id, dns_zone_name."
  type = object({
    cluster_name          = string # 예: "contract2whale-dev-eks"
    vpc_id                = string # 예: "vpc-0123456789abcdef0"
    exposure_mode         = string # 예: "waf" (edge 를 켤 수 있는 유일한 모드)
    nlb_security_group_id = string # 예: "sg-0123456789abcdef0"
    public_zone_id        = string # 예: "Z0123456789ABCDEFGHIJ"
    dns_zone_name         = string # 예: "dev.playdevops.click"
  })
  nullable = false
}

# NLB Service 가 Active 가 된 뒤 aws elbv2 describe-load-balancers 로 확인한 ARN 을 전달합니다.
variable "nlb_arn" {
  description = "ARN of the internal NLB that the controller created for the Gateway Service; empty while disabled."
  type        = string # 예: "arn:aws:elasticloadbalancing:ap-northeast-2:111111111111:loadbalancer/net/k8s-platfor-platform-0123456789/abcdef0123456789"
  default     = ""     # 기본값: "" (비활성 상태에서는 쓰지 않음)
  nullable    = false
}

# 와일드카드 대신 실제 공개 FQDN 목록입니다. Gateway Certificate 와 HTTPRoute 의 이름과 같아야 합니다.
variable "hostnames" {
  description = "Explicit public hostnames served by CloudFront (also the ACM viewer certificate SANs)."
  type        = set(string) # 예: ["dev.playdevops.click"]
  default     = []          # 기본값: [] (비활성 상태의 기본값)
  nullable    = false

  validation {
    condition     = alltrue([for h in var.hostnames : can(regex("^[a-z0-9][a-z0-9.-]*[a-z0-9]$", h))]) # 예: 소문자 이름만 통과 (와일드카드 · 끝의 점 거부)
    error_message = "Use lowercase explicit DNS names without wildcard or trailing dot."
  }
}

# 승인한 hostname의 Gateway 원본 인증서·체인·실제 TLS 응답을 확인한 뒤 운영자가 입력하는 선언입니다. Terraform의 true 검사나 mock 테스트가 인증서 발급·TLS 성공을 실측하지 않습니다.
variable "origin_tls_ready" {
  description = "Operator confirmation that the Envoy origin certificate is issued by the production CA."
  type        = bool  # 예: bool
  default     = false # 기본값: false (원본 인증서를 확인한 뒤 true 로 바꿈)
  nullable    = false
}

variable "rate_limit_per_5min" {
  description = "Per-source-IP WAF rate threshold over a 300-second evaluation window; not an exact request allowance or immediate blocking guarantee."
  type        = number # 예: 2000
  default     = 2000   # 기본값: 2000 (300초 평가 창의 IP별 rate 기준; 정확한 요청 허용량·즉시 차단 보장이 아님)
  nullable    = false

  validation {
    condition     = var.rate_limit_per_5min >= 10 && var.rate_limit_per_5min == floor(var.rate_limit_per_5min) # 예: 10 이상의 정수
    error_message = "Use an integer rate limit of at least 10."
  }
}

terraform/environments/dev/platform/edge.modules/edge/main.tf:
# main.tf — modules/edge (dev · prod 루트 모듈이 공유하는 모듈)
# 모든 data · 리소스가 var.enabled 로 개수를 0 또는 1(hostnames 만큼)로 정하므로 기본값(false)에서는 아무것도 만들지 않습니다.
# 읽기 조회에서 internet-facing NLB · TLS listener · 다른 VPC 의 원본을 거부합니다. 이 모듈의 최종 사용처는 Prod(CloudFront 와 WAF 로 공개 서비스 완성) 이며 Dev 루트 모듈은 비활성 상태로 코드만 검증합니다.

data "aws_lb" "origin" {
  count = var.enabled ? 1 : 0 # 예: 비활성이면 조회하지 않음
  arn   = var.nlb_arn         # 예: controller 가 만든 NLB 의 ARN
}

data "aws_lb_listener" "https_tcp" {
  count             = var.enabled ? 1 : 0 # 예: 비활성이면 조회하지 않음
  load_balancer_arn = var.nlb_arn         # 예: 같은 NLB 의 ARN
  port              = 443                 # 예: 443 (Envoy 로 전달하는 listener)
}

# VPC origin 은 VPC 에 IGW 가 연결돼 있어야 합니다 (private 서브넷에 IGW 기본 route 를 추가하는 것이 아님).
data "aws_internet_gateway" "attached" {
  count = var.enabled ? 1 : 0 # 예: 비활성이면 조회하지 않음

  filter {
    name   = "attachment.vpc-id"           # 예: VPC 에 붙은 IGW 를 찾는 필터
    values = [var.gateway_contract.vpc_id] # 예: ["vpc-0123456789abcdef0"]
  }
}

resource "terraform_data" "contract" {
  count = var.enabled ? 1 : 0 # 예: 비활성이면 검사 리소스도 만들지 않음

  lifecycle {
    precondition {
      condition     = terraform.workspace == "default" && var.gateway_contract.exposure_mode == "waf" # 예: 기본 workspace + Gateway 가 waf 모드일 때만 참
      error_message = "Enable only behind a WAF-mode internal Gateway in the default workspace."
    }

    precondition {
      condition     = var.origin_tls_ready && length(var.hostnames) > 0 # 예: 원본 인증서 확인 선언 + 이름 1개 이상
      error_message = "Enable only after the WAF-mode internal Gateway has a production TLS certificate and explicit hostnames."
    }

    precondition {
      # 예: zone apex 자체 또는 점으로 구분한 하위 도메인만 허용 ("evildev.playdevops.click" 같은 유사 접미사 거부)
      condition     = alltrue([for h in var.hostnames : h == trimsuffix(var.gateway_contract.dns_zone_name, ".") || endswith(h, ".${trimsuffix(var.gateway_contract.dns_zone_name, ".")}")])
      error_message = "Every hostname must equal the delegated zone apex or be its proper subdomain."
    }

    precondition {
      # 예: 조회한 NLB 가 internal · network · 같은 VPC · 계약 SG 를 가질 때만 참
      condition     = data.aws_lb.origin[0].internal && data.aws_lb.origin[0].load_balancer_type == "network" && data.aws_lb.origin[0].vpc_id == var.gateway_contract.vpc_id && contains(data.aws_lb.origin[0].security_groups, var.gateway_contract.nlb_security_group_id)
      error_message = "CloudFront VPC origin must use the same-VPC internal NLB with the contract security group."
    }

    precondition {
      condition     = data.aws_lb_listener.https_tcp[0].protocol == "TCP" # 예: NLB 가 TLS 를 끝내지 않고 Envoy 로 전달할 때만 참
      error_message = "The NLB 443 listener must be TCP; TLS terminates at Envoy."
    }
  }
}

# ACM 공개 인증서는 viewer TLS 만 담당하며 Envoy 원본 인증서는 cert-manager 가 따로 발급합니다.
resource "aws_acm_certificate" "viewer" {
  count                     = var.enabled ? 1 : 0                                          # 예: 비활성이면 0개
  provider                  = aws.global                                                   # 예: aws.global (us-east-1)
  domain_name               = sort(tolist(var.hostnames))[0]                               # 예: "dev.playdevops.click" (정렬된 첫 이름)
  subject_alternative_names = slice(sort(tolist(var.hostnames)), 1, length(var.hostnames)) # 예: 나머지 이름 목록
  validation_method         = "DNS"                                                        # 예: "DNS" (ACM 이 제공한 CNAME 레코드로 소유를 증명)

  lifecycle {
    create_before_destroy = true # 예: true (새 인증서를 먼저 만들고 바꿈)
  }

  depends_on = [terraform_data.contract] # 예: NLB와 도메인 조건 검사를 먼저 지나갑니다
}

# provider 가 domain_validation_options 를 만든 뒤 각 DNS 검증 레코드를 생성합니다. 주소 키는 사용자가 전달한 hostname 으로 확정합니다.
resource "aws_route53_record" "validation" {
  for_each = var.enabled ? var.hostnames : toset([])                                                                                          # 예: 이름마다 레코드 1개
  zone_id  = var.gateway_contract.public_zone_id                                                                                              # 예: "Z0123456789ABCDEFGHIJ"
  name     = one([for d in aws_acm_certificate.viewer[0].domain_validation_options : d.resource_record_name if d.domain_name == each.key])    # 예: "_abc123.dev.playdevops.click."
  type     = one([for d in aws_acm_certificate.viewer[0].domain_validation_options : d.resource_record_type if d.domain_name == each.key])    # 예: "CNAME"
  records  = [one([for d in aws_acm_certificate.viewer[0].domain_validation_options : d.resource_record_value if d.domain_name == each.key])] # 예: ["_def456.acm-validations.aws."]
  ttl      = 60                                                                                                                               # 예: 60 (초)
}

resource "aws_acm_certificate_validation" "viewer" {
  count                   = var.enabled ? 1 : 0                               # 예: 비활성이면 0개
  provider                = aws.global                                        # 예: aws.global (인증서와 같은 리전)
  certificate_arn         = aws_acm_certificate.viewer[0].arn                 # 예: 요청한 인증서의 ARN
  validation_record_fqdns = [for r in aws_route53_record.validation : r.fqdn] # 예: 위에서 만든 레코드의 전체 이름 목록
}

# VPC origin 전용 ENI 는 CloudFront 가 만듭니다. 내부 NLB 는 TCP 로 Envoy 의 HTTPS 를 전달합니다.
resource "aws_cloudfront_vpc_origin" "gateway" {
  count = var.enabled ? 1 : 0 # 예: 비활성이면 0개

  vpc_origin_endpoint_config {
    name                   = "${var.gateway_contract.cluster_name}-gateway" # 예: "contract2whale-dev-eks-gateway"
    arn                    = data.aws_lb.origin[0].arn                      # 예: 조회한 NLB 의 ARN
    http_port              = 80                                             # 예: 80 (쓰지 않지만 값이 필요)
    https_port             = 443                                            # 예: 443 (실제로 쓰는 포트)
    origin_protocol_policy = "https-only"                                   # 예: "https-only" (평문 경로를 만들지 않음)

    origin_ssl_protocols {
      items    = ["TLSv1.2"] # 예: ["TLSv1.2"]
      quantity = 1           # 예: 1 (items 의 개수)
    }
  }

  depends_on = [terraform_data.contract, data.aws_internet_gateway.attached] # 예: 검사와 IGW 조회 뒤에 만듭니다
}

# 세션과 로그인 응답은 공유 캐시하지 않습니다 (TTL 0). Host · cookie · Authorization · query 는 원본으로 보냅니다.
resource "aws_cloudfront_cache_policy" "disabled" {
  count       = var.enabled ? 1 : 0                             # 예: 비활성이면 0개
  name        = "${var.gateway_contract.cluster_name}-no-cache" # 예: "contract2whale-dev-eks-no-cache"
  default_ttl = 0                                               # 예: 0 (기본 보관 시간 없음)
  max_ttl     = 0                                               # 예: 0 (최대 보관 시간 없음)
  min_ttl     = 0                                               # 예: 0 (최소 보관 시간 없음)

  parameters_in_cache_key_and_forwarded_to_origin {
    enable_accept_encoding_brotli = false # 예: false
    enable_accept_encoding_gzip   = false # 예: false

    cookies_config {
      cookie_behavior = "none" # 예: "none" (캐시 키에 쿠키를 넣지 않음)
    }

    headers_config {
      header_behavior = "none" # 예: "none" (캐시 키에 헤더를 넣지 않음)
    }

    query_strings_config {
      query_string_behavior = "none" # 예: "none" (캐시 키에 query 를 넣지 않음)
    }
  }
}

resource "aws_cloudfront_origin_request_policy" "viewer" {
  count = var.enabled ? 1 : 0                               # 예: 비활성이면 0개
  name  = "${var.gateway_contract.cluster_name}-all-viewer" # 예: "contract2whale-dev-eks-all-viewer"

  cookies_config {
    cookie_behavior = "all" # 예: "all" (쿠키를 원본으로 전달)
  }

  headers_config {
    header_behavior = "allViewer" # 예: "allViewer" (요청자가 보낸 Host · Authorization 을 전달 → Envoy 의 hostname route 와 JWT 유지)
  }

  query_strings_config {
    query_string_behavior = "all" # 예: "all" (query 를 원본으로 전달)
  }
}

resource "aws_wafv2_web_acl" "edge" {
  count    = var.enabled ? 1 : 0                         # 예: 비활성이면 0개
  provider = aws.global                                  # 예: aws.global (CLOUDFRONT scope 는 us-east-1)
  name     = "${var.gateway_contract.cluster_name}-edge" # 예: "contract2whale-dev-eks-edge"
  scope    = "CLOUDFRONT"                                # 예: "CLOUDFRONT" (CloudFront 에 붙이는 범위)

  default_action {
    allow {} # 예: 규칙에 걸리지 않은 요청은 허용
  }

  dynamic "rule" {
    for_each = {
      AWSManagedRulesCommonRuleSet         = 10 # 예: 규칙 이름 → 평가 순서
      AWSManagedRulesKnownBadInputsRuleSet = 20
      AWSManagedRulesSQLiRuleSet           = 30
    }

    content {
      name     = rule.key   # 예: "AWSManagedRulesCommonRuleSet"
      priority = rule.value # 예: 10 (숫자가 작을수록 먼저 평가)

      override_action {
        none {} # 예: 룰 그룹의 동작을 그대로 씀
      }

      statement {
        managed_rule_group_statement {
          name        = rule.key # 예: 관리 룰 그룹 이름
          vendor_name = "AWS"    # 예: "AWS"
        }
      }

      visibility_config {
        cloudwatch_metrics_enabled = true     # 예: true (지표를 남김)
        metric_name                = rule.key # 예: 규칙 이름을 지표 이름으로 사용
        sampled_requests_enabled   = false    # 예: false (요청 표본을 저장하지 않음)
      }
    }
  }

  rule {
    name     = "request-rate" # 예: "request-rate"
    priority = 40             # 예: 40 (관리 규칙 뒤에 평가)

    action {
      block {} # 예: rate 규칙이 매칭한 요청을 차단; 정확한 N번째 요청·반영 시각 보장은 아님
    }

    statement {
      rate_based_statement {
        limit                 = var.rate_limit_per_5min # 예: 2000
        aggregate_key_type    = "IP"                    # 예: "IP" (요청 IP 로 셈)
        evaluation_window_sec = 300                     # 예: 300 (5분 창)
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true           # 예: true
      metric_name                = "request-rate" # 예: "request-rate"
      sampled_requests_enabled   = false          # 예: false
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = true                                        # 예: true
    metric_name                = "${var.gateway_contract.cluster_name}-edge" # 예: "contract2whale-dev-eks-edge"
    sampled_requests_enabled   = false                                       # 예: false
  }
}

# WAF 의 전체 요청 로그를 보존하되 Authorization · Cookie · query 는 가립니다. 로그 그룹 이름은 aws-waf-logs- 로 시작해야 합니다.
resource "aws_cloudwatch_log_group" "waf" {
  count             = var.enabled ? 1 : 0                                 # 예: 비활성이면 0개
  provider          = aws.global                                          # 예: aws.global (Web ACL 과 같은 리전)
  name              = "aws-waf-logs-${var.gateway_contract.cluster_name}" # 예: "aws-waf-logs-contract2whale-dev-eks"
  retention_in_days = 30                                                  # 예: 30 (보존 기간)
}

resource "aws_wafv2_web_acl_logging_configuration" "edge" {
  count                   = var.enabled ? 1 : 0                   # 예: 비활성이면 0개
  provider                = aws.global                            # 예: aws.global
  resource_arn            = aws_wafv2_web_acl.edge[0].arn         # 예: 위에서 만든 Web ACL 의 ARN
  log_destination_configs = [aws_cloudwatch_log_group.waf[0].arn] # 예: 위에서 만든 로그 그룹의 ARN

  redacted_fields {
    single_header {
      name = "authorization" # 예: "authorization" (헤더 값을 가림)
    }
  }

  redacted_fields {
    single_header {
      name = "cookie" # 예: "cookie" (헤더 값을 가림)
    }
  }

  redacted_fields {
    query_string {} # 예: query 문자열 전체를 가림
  }
}

resource "aws_cloudfront_distribution" "app" {
  count               = var.enabled ? 1 : 0                    # 예: 비활성이면 0개
  enabled             = true                                   # 예: true (배포를 켬)
  is_ipv6_enabled     = true                                   # 예: true (IPv6 주소도 제공)
  http_version        = "http2and3"                            # 예: "http2and3"
  aliases             = var.hostnames                          # 예: ["dev.playdevops.click"]
  comment             = "WAF protected internal Envoy Gateway" # 예: 콘솔에서 보이는 설명
  price_class         = "PriceClass_100"                       # 예: "PriceClass_100" (사용할 edge 위치 범위)
  wait_for_deployment = true                                   # 예: true (배포가 끝날 때까지 기다림)
  web_acl_id          = aws_wafv2_web_acl.edge[0].arn          # 예: 위에서 만든 Web ACL 의 ARN

  origin {
    origin_id   = "gateway"                      # 예: "gateway" (아래 동작이 가리킬 이름)
    domain_name = data.aws_lb.origin[0].dns_name # 예: 내부 NLB 의 DNS 이름 (전달 Host 는 viewer 의 app 이름)

    vpc_origin_config {
      vpc_origin_id            = aws_cloudfront_vpc_origin.gateway[0].id # 예: 위에서 만든 VPC origin
      origin_read_timeout      = 60                                      # 예: 60 (초)
      origin_keepalive_timeout = 5                                       # 예: 5 (초)
    }
  }

  default_cache_behavior {
    target_origin_id         = "gateway"                                                    # 예: 위 origin 의 이름
    viewer_protocol_policy   = "redirect-to-https"                                          # 예: HTTP 요청을 HTTPS 로 보냄
    allowed_methods          = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"] # 예: 앱이 쓰는 메서드 전부
    cached_methods           = ["GET", "HEAD"]                                              # 예: 저장을 고려할 메서드
    cache_policy_id          = aws_cloudfront_cache_policy.disabled[0].id                   # 예: TTL 0 정책
    origin_request_policy_id = aws_cloudfront_origin_request_policy.viewer[0].id            # 예: 전달 정책
    compress                 = true                                                         # 예: true (응답 압축)
  }

  restrictions {
    geo_restriction {
      restriction_type = "none" # 예: "none" (지역 제한 없음)
    }
  }

  viewer_certificate {
    acm_certificate_arn      = aws_acm_certificate_validation.viewer[0].certificate_arn # 예: 검증이 끝난 인증서
    ssl_support_method       = "sni-only"                                               # 예: "sni-only"
    minimum_protocol_version = "TLSv1.2_2021"                                           # 예: "TLSv1.2_2021"
  }

  depends_on = [aws_wafv2_web_acl_logging_configuration.edge] # 예: 로그 연결 뒤에 배포합니다
}

# 이 모드에서 앱 DNS 는 Terraform 만 소유합니다. ExternalDNS 가 같은 이름을 쓰게 하지 않습니다 (waf 모드는 ExternalDNS 신원이 없음).
resource "aws_route53_record" "app_ipv4" {
  for_each = var.enabled ? var.hostnames : toset([]) # 예: 이름마다 A 레코드 1개
  zone_id  = var.gateway_contract.public_zone_id     # 예: "Z0123456789ABCDEFGHIJ"
  name     = each.value                              # 예: "dev.playdevops.click"
  type     = "A"                                     # 예: "A" (IPv4 alias)

  alias {
    name                   = aws_cloudfront_distribution.app[0].domain_name    # 예: "d111111abcdef8.cloudfront.net"
    zone_id                = aws_cloudfront_distribution.app[0].hosted_zone_id # 예: CloudFront 의 고정 zone ID
    evaluate_target_health = false                                             # 예: false (alias 상태 검사를 쓰지 않음)
  }
}

resource "aws_route53_record" "app_ipv6" {
  for_each = var.enabled ? var.hostnames : toset([]) # 예: 이름마다 AAAA 레코드 1개
  zone_id  = var.gateway_contract.public_zone_id     # 예: "Z0123456789ABCDEFGHIJ"
  name     = each.value                              # 예: "dev.playdevops.click"
  type     = "AAAA"                                  # 예: "AAAA" (IPv6 alias)

  alias {
    name                   = aws_cloudfront_distribution.app[0].domain_name    # 예: "d111111abcdef8.cloudfront.net"
    zone_id                = aws_cloudfront_distribution.app[0].hosted_zone_id # 예: CloudFront 의 고정 zone ID
    evaluate_target_health = false                                             # 예: false
  }
}

terraform/environments/dev/platform/edge.modules/edge/outputs.tf:
# outputs.tf — modules/edge (dev · prod 루트 모듈이 공유하는 모듈)

output "edge_contract" {
  description = "CloudFront distribution, domain, WAF ARN and hostnames when enabled; null while disabled."
  value = var.enabled ? {
    distribution_id = aws_cloudfront_distribution.app[0].id          # 예: "E1ABCDEFGHIJKL"
    domain_name     = aws_cloudfront_distribution.app[0].domain_name # 예: "d111111abcdef8.cloudfront.net"
    waf_arn         = aws_wafv2_web_acl.edge[0].arn                  # 예: Web ACL 의 ARN
    hostnames       = sort(tolist(var.hostnames))                    # 예: ["dev.playdevops.click"]
  } : null                                                           # 예: 비활성이면 null
}

terraform/environments/dev/platform/edge.terraform/environments/dev/platform/edge:
# versions.tf — platform/edge 루트 모듈 (dev · prod 공통 코드)
# 환경 root 두 개 연결: Terraform 과 provider 버전을 고정합니다. backend 선언은 backend.tf 에, 모듈 버전과 aws.global alias 선언은 modules/edge/versions.tf 에 있습니다.

terraform {
  required_version = "= 1.16.0" # 예: "= 1.16.0" (등호로 정확한 버전 고정)

  required_providers {
    aws = {
      source  = "hashicorp/aws" # 예: "hashicorp/aws" (공식 레지스트리 경로)
      version = "= 6.62.0"      # 예: "= 6.62.0" (모듈과 같은 값)
    }
  }
}

# backend.tf — platform/edge 루트 모듈 (dev · prod 공통 코드)
# 환경 root 두 개 연결: backend 인자는 커밋하지 않는 backend.hcl 이 제공합니다 (terraform init -backend-config=backend.hcl).
# key 는 platform/edge/terraform.tfstate 로 실행 디렉터리 경로 규칙을 따릅니다 (platform/gateway/terraform.tfstate 와 같은 버킷; Edge 리소스를 이 key에서 관리).

terraform {
  backend "s3" {}
}

# providers.tf — platform/edge 루트 모듈 (dev · prod 공통 코드)
# 환경 root 두 개 연결: provider 두 개. 기본 provider 는 워크로드 리전(NLB 조회 · Route 53 · VPC origin), aws.global 은 us-east-1(CloudFront viewer 인증서 · CLOUDFRONT scope WAF · WAF 로그 그룹)입니다.
# 두 provider 모두 같은 계정으로 제한하고 같은 default_tags 를 씁니다. 모듈은 providers = { aws = aws, aws.global = aws.global } 로 둘을 받습니다.

provider "aws" {
  region              = var.region                # 예: "ap-northeast-2" (서울 리전)
  allowed_account_ids = [var.expected_account_id] # 예: ["111111111111"]

  default_tags {
    tags = {
      ManagedBy   = "Terraform"     # 예: "Terraform"
      Environment = var.environment # 예: "dev"
      Component   = "platform-edge" # 예: "platform-edge"
    }
  }
}

# CloudFront viewer 인증서와 CLOUDFRONT 범위 WAF 를 만들 provider 입니다.
provider "aws" {
  alias               = "global"                  # 예: "global" (모듈이 aws.global 로 받음)
  region              = "us-east-1"               # 예: "us-east-1" (전역 서비스의 API 리전; 변수로 바꾸지 않음)
  allowed_account_ids = [var.expected_account_id] # 예: ["111111111111"] (기본 provider 와 같은 계정)

  default_tags {
    tags = {
      ManagedBy   = "Terraform"     # 예: 같은 태그
      Environment = var.environment # 예: "dev"
      Component   = "platform-edge" # 예: "platform-edge"
    }
  }
}

# variables.tf — platform/edge 루트 모듈 (dev · prod 공통 코드)

variable "expected_account_id" {
  description = "AWS account that owns the NLB, the public zone and the CloudFront distribution; 12 digits."
  type        = string
  nullable    = false

  validation {
    condition     = can(regex("^[0-9]{12}$", var.expected_account_id)) # 예: "111111111111" 통과
    error_message = "Account ID must be 12 digits."
  }
}

variable "region" {
  description = "AWS region of the NLB and the public zone; only ap-northeast-2 is supported (CloudFront/WAF use the fixed us-east-1 alias)."
  type        = string
  default     = "ap-northeast-2" # 기본값: "ap-northeast-2"
  nullable    = false

  validation {
    condition     = var.region == "ap-northeast-2" # 예: 단일 값 비교
    error_message = "This root supports ap-northeast-2 only."
  }
}

variable "environment" {
  description = "Explicit environment name, 2-20 lowercase letters, digits or hyphens."
  type        = string
  nullable    = false

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{1,19}$", var.environment)) # 예: "dev" 통과 / "Dev" 거부
    error_message = "Use a 2-20 character lowercase environment name."
  }
}

# Gateway 루트 모듈의 State 가 있는 버킷입니다. backend.hcl 의 bucket 과 같은 값입니다.
variable "state_bucket_name" {
  description = "S3 bucket holding the platform/gateway state read by terraform_remote_state."
  type        = string # 예: "company-dev-tfstate-111111111111" (CI 보호 입력의 DEV_STATE_BUCKET)
  nullable    = false

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$", var.state_bucket_name)) # 예: 길이·문자 형식 검사; S3 이름의 모든 제약을 검사하는 것은 아님
    error_message = "state_bucket_name must be a valid S3 bucket name."
  }
}

# Dev 는 false 로 둡니다 (Dev 노출은 internal; CloudFront + WAF 공개는 Prod 의 CloudFront 와 WAF 로 공개 서비스 완성).
variable "enabled" {
  description = "Create CloudFront, WAF, viewer certificate and app DNS records; false keeps the root at the environment marker only."
  type        = bool
  default     = false # 기본값: false
  nullable    = false
}

variable "nlb_arn" {
  description = "ARN of the internal NLB that the controller created for the Gateway Service; empty while disabled."
  type        = string
  default     = "" # 기본값: "" (비활성)
  nullable    = false
}

variable "hostnames" {
  description = "Explicit public hostnames served by CloudFront (also the ACM viewer certificate SANs)."
  type        = set(string)
  default     = [] # 기본값: [] (비활성)
  nullable    = false

  validation {
    condition     = alltrue([for h in var.hostnames : can(regex("^[a-z0-9][a-z0-9.-]*[a-z0-9]$", h))]) # 예: 소문자 이름만
    error_message = "Use lowercase explicit DNS names without wildcard or trailing dot."
  }
}

variable "origin_tls_ready" {
  description = "Operator confirmation that the Envoy origin certificate is issued by the production CA."
  type        = bool
  default     = false # 기본값: false
  nullable    = false
}

variable "rate_limit_per_5min" {
  description = "Per-source-IP WAF rate threshold over a 300-second evaluation window; not an exact request allowance or immediate blocking guarantee."
  type        = number
  default     = 2000 # 기본값: 2000
  nullable    = false

  validation {
    condition     = var.rate_limit_per_5min >= 10 && var.rate_limit_per_5min == floor(var.rate_limit_per_5min) # 예: 10 이상의 정수
    error_message = "Use an integer rate limit of at least 10."
  }
}

# remote-state.tf — platform/edge 루트 모듈 (dev · prod 공통 코드)
# 읽는 쪽에는 State 객체 전체의 s3:GetObject 권한이 필요합니다 (관련 구성 의 State 역할 key 목록과 대조).

data "terraform_remote_state" "gateway" {
  backend = "s3" # 예: "s3"

  config = {
    bucket = var.state_bucket_name                # 예: "company-dev-tfstate-111111111111"
    key    = "platform/gateway/terraform.tfstate" # 예: Gateway 루트 모듈의 key
    region = var.region                           # 예: "ap-northeast-2"
  }

  lifecycle {
    postcondition {
      condition = alltrue([
        for name in ["cluster_name", "vpc_id", "exposure_mode", "nlb_security_group_id", "public_zone_id", "dns_zone_name"] :
        contains(keys(try(self.outputs.gateway_contract, {})), name) # 예: 6개 모두 gateway_contract 에 존재
      ])
      error_message = "platform/gateway state must expose gateway_contract with cluster_name, vpc_id, exposure_mode, nlb_security_group_id, public_zone_id and dns_zone_name (apply 계약 테스트와 controller 설치 first)."
    }
  }
}

# locals.tf — platform/edge 루트 모듈 (dev · prod 공통 코드)

locals {
  gateway_contract = {
    cluster_name          = data.terraform_remote_state.gateway.outputs.gateway_contract.cluster_name          # 예: "contract2whale-dev-eks"
    vpc_id                = data.terraform_remote_state.gateway.outputs.gateway_contract.vpc_id                # 예: "vpc-0123456789abcdef0"
    exposure_mode         = data.terraform_remote_state.gateway.outputs.gateway_contract.exposure_mode         # 예: "internal" (Dev; edge 를 켜려면 "waf")
    nlb_security_group_id = data.terraform_remote_state.gateway.outputs.gateway_contract.nlb_security_group_id # 예: "sg-0123456789abcdef0"
    public_zone_id        = data.terraform_remote_state.gateway.outputs.gateway_contract.public_zone_id        # 예: "ZPUBLIC"
    dns_zone_name         = data.terraform_remote_state.gateway.outputs.gateway_contract.dns_zone_name         # 예: "dev.playdevops.click"
  }
}

# main.tf — platform/edge 루트 모듈 (dev · prod 공통 코드)

module "component" {
  source = "../../../../../modules/edge" # 예: 이 루트 모듈에서 모듈까지의 상대 경로 (다섯 단계 위가 저장소 최상위)

  providers = {
    aws        = aws        # 예: 왼쪽은 모듈 안의 이름, 오른쪽은 루트 모듈의 provider (서울)
    aws.global = aws.global # 예: us-east-1 provider (ACM · WAF)
  }

  enabled             = var.enabled             # 예: false (Dev 기본)
  expected_account_id = var.expected_account_id # 예: "111111111111"
  gateway_contract    = local.gateway_contract  # 예: Gateway State 출력에서 고른 6개 항목
  nlb_arn             = var.nlb_arn             # 예: "" (비활성 상태의 기본값)
  hostnames           = var.hostnames           # 예: [] (비활성 상태의 기본값)
  origin_tls_ready    = var.origin_tls_ready    # 예: false (원본 인증서를 확인한 뒤 true)
  rate_limit_per_5min = var.rate_limit_per_5min # 예: 2000
}

# 이 디렉터리는 dev 만 받습니다. input 은 State 에 남는 marker 이며 AWS 자원을 만들지 않습니다.
resource "terraform_data" "environment_boundary" {
  input = var.environment # 예: "dev" (input 변경은 in-place 갱신)

  lifecycle {
    precondition {
      condition     = var.environment == "dev" # 예: "dev" 통과 / "prod" 거부 (prod 는 prod/platform/edge 디렉터리, 운영 환경)
      error_message = "This directory accepts only the dev environment."
    }

    precondition {
      condition     = terraform.workspace == "default" # 예: workspace 로 환경을 나누지 않음
      error_message = "Use default workspace and a distinct backend key."
    }
  }
}

# outputs.tf — platform/edge 루트 모듈 (dev · prod 공통 코드)
# 환경 root 두 개 연결: child module 의 출력을 같은 이름으로 루트 모듈 밖에 전달합니다. 비활성이면 null 입니다.

output "edge_contract" {
  description = "CloudFront distribution, domain, WAF ARN and hostnames when enabled; null while disabled."
  value       = module.component.edge_contract # 예: null (Dev 기본)
}

terraform/environments/prod/platform/cor.modules/core/versions.tf:
# versions.tf — modules/core (dev · prod 루트 모듈이 공유하는 모듈)
# core: AWS 권한(IAM Role · inline 정책 · Pod Identity 연결)만 Terraform 으로 관리합니다. Helm · Kubernetes provider 는 사용하지 않습니다.
# 과정 내부 전용 모듈이라 루트 모듈과 같은 값을 등호로 고정합니다. provider 블록은 두지 않습니다 (인증 · 리전 · default_tags 는 루트 모듈의 providers.tf 가 담당).

terraform {
  required_version = "= 1.16.0" # 예: "= 1.16.0" (등호로 정확한 버전 고정)

  required_providers {
    aws = {
      source  = "hashicorp/aws" # 예: "hashicorp/aws" (공식 레지스트리 경로)
      version = "= 6.62.0"      # 예: "= 6.62.0" (과정에 고정한 버전; 루트 모듈과 같은 값)
    }
  }
}

terraform/environments/prod/platform/cor.modules/core/variables.tf:
# variables.tf — modules/core (dev · prod 루트 모듈이 공유하는 모듈)
# core: 입력 4개입니다 (모두 기본값 없음). 앞 구성(eks 루트 모듈)의 cluster_contract 전체(12개 항목)를 받아도 이 모듈이 쓰는 세 속성만 타입 계약에 남깁니다.
# 검사식은 형식만 봅니다. 실제 AWS 객체 대조(클러스터 ARN · 공개 zone ID)는 main.tf 의 terraform_data.contract precondition 이 맡습니다.

# eks 루트 모듈 출력 cluster_contract 중 name · arn · region 만 받습니다. 나머지 속성은 object 타입 변환에서 버려집니다.
variable "cluster_contract" {
  description = "Cluster identity from the eks root state; only name, arn and region are used here."
  type = object({
    name   = string # 예: "contract2whale-dev-eks"
    arn    = string # 예: "arn:aws:eks:ap-northeast-2:111111111111:cluster/contract2whale-dev-eks"
    region = string # 예: "ap-northeast-2"
  })
  nullable = false

  validation {
    condition     = var.cluster_contract.region == "ap-northeast-2" # 예: "ap-northeast-2" 통과 / "us-east-1" 거부 (서울 리전만 허용)
    error_message = "This build targets Seoul."
  }

  validation {
    condition     = can(regex("^arn:aws:eks:ap-northeast-2:[0-9]{12}:cluster/[a-z][a-z0-9-]+$", var.cluster_contract.arn)) # 예: EKS 클러스터 ARN 형식 (계정 12자리 · 클러스터 이름)
    error_message = "cluster_contract.arn must be an EKS cluster ARN in ap-northeast-2."
  }
}

# 실제 대상 계정 ID 를 받아 잘못된 계정의 클러스터에 권한을 연결하지 않게 합니다.
variable "expected_account_id" {
  description = "AWS account that owns the cluster and the Route 53 zone; 12 digits."
  type        = string # 예: string (앞자리 0 이 사라지지 않도록 문자열)
  nullable    = false

  validation {
    condition     = can(regex("^[0-9]{12}$", var.expected_account_id)) # 예: "111111111111" 통과 / "1111" 거부
    error_message = "Account ID must be 12 digits."
  }
}

# 이미 존재하는 public hosted zone 입니다. DNS zone 자체는 여기서 생성하지 않습니다 (account account-baseline-dns 루트 모듈 소유).
variable "public_zone_id" {
  description = "Existing public Route 53 hosted-zone ID (without the /hostedzone/ prefix)."
  type        = string # 예: "Z0123456789ABCDEFGHIJ"
  nullable    = false

  validation {
    condition     = can(regex("^Z[A-Z0-9]+$", var.public_zone_id)) # 예: "Z0123456789ABCDEFGHIJ" 통과 / "/hostedzone/Z…" 거부
    error_message = "Supply the real public Route53 hosted-zone ID without /hostedzone/."
  }
}

# zone_id 직접 조회는 private_zone 필터를 무시하므로 이름과 public 필터로 조회한 ID 를 대조합니다.
variable "public_zone_name" {
  description = "Authoritative public DNS zone name in lowercase, with or without the trailing dot."
  type        = string # 예: "dev.playdevops.click"
  nullable    = false

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9.-]*\\.[a-z]{2,}\\.?$", var.public_zone_name)) # 예: "dev.playdevops.click" 통과 / "Example.COM" 거부
    error_message = "Supply the lowercase authoritative public DNS zone name."
  }
}

terraform/environments/prod/platform/cor.modules/core/main.tf:
# main.tf — modules/core (dev · prod 루트 모듈이 공유하는 모듈)
# core: data 2개(클러스터 · 공개 zone 조회) · 리소스 4개(계약 검사 terraform_data 1 · IAM Role 1 · inline 정책 1 · Pod Identity 연결 1).
# 읽기 조회로 다른 클러스터 · 다른 계정 · private DNS zone 오입력을 apply 전에 막습니다. 인증서 발급 객체(ClusterIssuer)는 만들지 않습니다.

# 계약의 이름으로 실제 클러스터를 조회합니다. 조회 결과의 ARN 이 계약 ARN 과 다르면 아래 precondition 이 plan을 중단합니다.
data "aws_eks_cluster" "this" {
  name = var.cluster_contract.name # 예: "contract2whale-dev-eks"
}

# 이름 + public 필터로 조회합니다. 같은 이름의 private zone 이 있어도 공개 zone 만 고릅니다.
data "aws_route53_zone" "public" {
  name         = var.public_zone_name # 예: "dev.playdevops.click" (조회할 공개 zone 의 도메인 이름)
  private_zone = false                # 예: false (private zone 을 제외하고 공개 zone 만 고름)
}

# AWS 자원을 만들지 않는 검사용 리소스입니다. precondition 4개 중 하나라도 거짓이면 plan 이 실패합니다.
resource "terraform_data" "contract" {
  lifecycle {
    precondition {
      condition     = terraform.workspace == "default" # 예: workspace 로 환경을 나누지 않음 (backend key 로 구분)
      error_message = "Use default workspace and a distinct backend key."
    }

    precondition {
      condition     = data.aws_eks_cluster.this.arn == var.cluster_contract.arn # 예: 이름으로 조회한 ARN 과 계약 ARN 이 글자 하나까지 같아야 통과
      error_message = "The EKS cluster looked up by name must match cluster_contract.arn (intended same-account cluster)."
    }

    precondition {
      condition     = split(":", var.cluster_contract.arn)[4] == var.expected_account_id # 예: ARN 의 5번째 항목(계정 12자리) == expected_account_id
      error_message = "cluster_contract.arn must belong to expected_account_id."
    }

    precondition {
      condition     = data.aws_route53_zone.public.zone_id == var.public_zone_id # 예: 이름으로 조회한 공개 zone ID 와 입력 ID 를 대조
      error_message = "The public zone selected by name must match the declared zone ID."
    }
  }
}

# HCL object 를 jsonencode 로 IAM JSON 으로 바꿉니다. 비밀키가 아닌 권한 정책입니다.
locals {
  # Pod Identity 서비스만 이 Role 을 맡습니다. namespace · ServiceAccount · 클러스터 ARN 세션 태그가 모두 일치해야 합니다.
  cert_manager_trust = {
    Version = "2012-10-17" # 예: "2012-10-17" (IAM 정책 문법 버전, 날짜가 아님)
    Statement = [{
      Effect    = "Allow"                                # 예: "Allow" (조건을 만족하면 허용)
      Principal = { Service = "pods.eks.amazonaws.com" } # 예: EKS Pod Identity 서비스만 이 Role 을 맡음
      Action    = ["sts:AssumeRole", "sts:TagSession"]   # 예: Role 을 맡는 동작과 세션 태그를 붙이는 동작
      Condition = {
        StringEquals = {
          "aws:RequestTag/kubernetes-namespace"       = "cert-manager"           # 예: "cert-manager" (이 namespace 의 Pod 만)
          "aws:RequestTag/kubernetes-service-account" = "cert-manager"           # 예: "cert-manager" (이 ServiceAccount 만; Helm values 의 serviceAccount.name 과 같아야 함)
          "aws:RequestTag/eks-cluster-arn"            = var.cluster_contract.arn # 예: "arn:aws:eks:ap-northeast-2:111111111111:cluster/contract2whale-dev-eks"
        }
      }
    }]
  }

  # TXT DNS01 만 변경합니다. A/AAAA 앱 레코드는 주소 레코드 담당(gateway Gateway · production Edge 루트 모듈)이 소유합니다.
  cert_manager_permissions = {
    Version = "2012-10-17" # 예: "2012-10-17" (IAM 정책 문법 버전)
    Statement = [
      {
        Effect   = "Allow"                        # 예: "Allow"
        Action   = ["route53:GetChange"]          # 예: 변경 반영 여부 조회
        Resource = ["arn:aws:route53:::change/*"] # 예: 모든 change ID (zone 별로 나눌 수 없는 자원)
      },
      {
        Effect   = "Allow"                                                # 예: "Allow"
        Action   = ["route53:ListResourceRecordSets"]                     # 예: 지정 zone 의 레코드 목록 조회
        Resource = ["arn:aws:route53:::hostedzone/${var.public_zone_id}"] # 예: "arn:aws:route53:::hostedzone/Z0123456789ABCDEFGHIJ"
      },
      {
        Effect   = "Allow"                                                # 예: "Allow" (아래 조건을 모두 만족할 때만 허용)
        Action   = ["route53:ChangeResourceRecordSets"]                   # 예: 레코드를 만들고 바꾸고 지우는 동작
        Resource = ["arn:aws:route53:::hostedzone/${var.public_zone_id}"] # 예: 입력한 공개 zone 하나
        Condition = {
          "ForAllValues:StringEquals" = {
            "route53:ChangeResourceRecordSetsRecordTypes" = ["TXT"]                        # 예: ["TXT"] (A · AAAA · CNAME 은 거부)
            "route53:ChangeResourceRecordSetsActions"     = ["CREATE", "UPSERT", "DELETE"] # 예: 만들기 · 덮어쓰기 · 지우기만 허용
          }
          "ForAllValues:StringLike" = {
            "route53:ChangeResourceRecordSetsNormalizedRecordNames" = ["_acme-challenge.*"] # 예: ACME 인증 확인용 이름만 허용
          }
        }
      }
    ]
  }
}

resource "aws_iam_role" "cert_manager" {
  name               = "${var.cluster_contract.name}-cert-manager" # 예: "contract2whale-dev-eks-cert-manager"
  assume_role_policy = jsonencode(local.cert_manager_trust)        # 예: 위 HCL object 를 IAM JSON 문자열로 변환

  depends_on = [terraform_data.contract] # 예: 클러스터 · zone 계약 검사를 먼저 통과시킴
}

resource "aws_iam_role_policy" "dns01" {
  name   = "route53-dns01"                            # 예: "route53-dns01" (Role 안에 붙는 inline 정책 이름)
  role   = aws_iam_role.cert_manager.id               # 예: "contract2whale-dev-eks-cert-manager" (정책을 붙일 Role)
  policy = jsonencode(local.cert_manager_permissions) # 예: TXT 로 좁힌 권한 object 를 JSON 으로 변환
}

# ServiceAccount 가 아직 없어도 연결은 만들 수 있습니다. 같은 namespace · 이름의 ServiceAccount 로 뜨는 Pod 에 임시 자격 증명이 주입됩니다.
resource "aws_eks_pod_identity_association" "cert_manager" {
  cluster_name    = var.cluster_contract.name     # 예: "contract2whale-dev-eks" (앞 구성 cluster_contract 의 name)
  namespace       = "cert-manager"                # 예: "cert-manager" (연결할 namespace)
  service_account = "cert-manager"                # 예: "cert-manager" (연결할 ServiceAccount 이름; Helm values 와 같아야 함)
  role_arn        = aws_iam_role.cert_manager.arn # 예: "arn:aws:iam::111111111111:role/contract2whale-dev-eks-cert-manager"

  depends_on = [aws_iam_role_policy.dns01] # 예: 권한 정책이 붙은 뒤에 연결을 만듦
}

terraform/environments/prod/platform/cor.modules/core/outputs.tf:
# outputs.tf — modules/core (dev · prod 루트 모듈이 공유하는 모듈)
# 공개 계약의 service_account와 chart values의 serviceAccount.name이 일치해야 SDK 임시 인증이 주입됩니다.

output "core_identity_contract" {
  description = "Cluster, namespace, service account, role ARN and public zone that the cert-manager install and later roots rely on."
  value = {
    cluster_name          = var.cluster_contract.name                          # 예: "contract2whale-dev-eks"
    namespace             = "cert-manager"                                     # 예: "cert-manager" (설치 대상 namespace)
    service_account       = "cert-manager"                                     # 예: "cert-manager" (Helm values 와 대조할 이름)
    cert_manager_role_arn = aws_iam_role.cert_manager.arn                      # 예: "arn:aws:iam::111111111111:role/contract2whale-dev-eks-cert-manager"
    public_zone_id        = var.public_zone_id                                 # 예: "Z0123456789ABCDEFGHIJ"
    public_zone_name      = trimsuffix(data.aws_route53_zone.public.name, ".") # 예: "dev.playdevops.click" (조회한 이름; 끝의 점은 떼어 account 출력과 같은 형식으로 맞춤)
  }
}

terraform/environments/prod/platform/cor.terraform/environments/prod/platform/cor:
# backend.tf — platform/core 루트 모듈 (prod · dev 공통 코드)
# 환경 root 와 계약 테스트: backend 인자는 커밋하지 않는 backend.hcl 이 제공합니다 (terraform init -backend-config=backend.hcl).
# key 는 platform/core/terraform.tfstate 로 실행 디렉터리 경로 규칙을 따릅니다 (eks/terraform.tfstate · account-baseline-dns/terraform.tfstate 와 같은 버킷).

terraform {
  backend "s3" {}
}

# locals.tf — platform/core 루트 모듈 (prod · dev 공통 코드)
# 환경 root 와 계약 테스트: State 에서 읽은 출력을 모듈 입력 모양으로 조립합니다. 세 값 모두 이 루트 모듈이 직접 입력받지 않습니다.

locals {
  # modules/core 의 cluster_contract 객체입니다. eks State 의 12개 항목 중 세 항목만 골라 계약 모양을 명시합니다.
  cluster_contract = {
    name   = data.terraform_remote_state.eks.outputs.cluster_contract.name   # 예: "contract2whale-prod-eks"
    arn    = data.terraform_remote_state.eks.outputs.cluster_contract.arn    # 예: "arn:aws:eks:ap-northeast-2:222222222222:cluster/contract2whale-prod-eks"
    region = data.terraform_remote_state.eks.outputs.cluster_contract.region # 예: "ap-northeast-2"
  }

  public_zone_id   = data.terraform_remote_state.dns.outputs.public_zone_id   # 예: "Z0123456789ABCDEFGHIJ" (계정 옵션과 공개 자식 DNS 루트 모듈 출력)
  public_zone_name = data.terraform_remote_state.dns.outputs.public_zone_name # 예: "app.playdevops.click" (계정 옵션과 공개 자식 DNS 루트 모듈 출력, 끝의 점 없음)
}

# main.tf — platform/core 루트 모듈 (prod · dev 공통 코드)
# 환경 root 와 계약 테스트: 환경별 입력은 루트 모듈, 재사용 리소스는 모듈에서 관리합니다. module "component" 로 변수 4개를 전달하고 환경 경계 1개를 둡니다.

module "component" {
  source = "../../../../../modules/core" # 예: 이 루트 모듈에서 모듈까지의 상대 경로 (다섯 단계 위가 저장소 최상위)

  cluster_contract    = local.cluster_contract  # 예: eks State 출력으로 조립한 {name, arn, region}
  expected_account_id = var.expected_account_id # 예: "222222222222" (숫자 12자리 계정 번호)
  public_zone_id      = local.public_zone_id    # 예: "Z0123456789ABCDEFGHIJ" (account-baseline-dns State 출력)
  public_zone_name    = local.public_zone_name  # 예: "app.playdevops.click" (같은 State 의 zone 이름)
}

# 이 디렉터리는 prod 만 받습니다. input 은 State 에 남는 marker 이며 AWS 자원을 만들지 않습니다.
resource "terraform_data" "environment_boundary" {
  input = var.environment # 예: "prod" (input 변경은 in-place 갱신)

  lifecycle {
    precondition {
      condition     = var.environment == "prod" # 예: "prod" 통과 / "dev" 거부 (dev 는 dev/platform/core 디렉터리)
      error_message = "This directory accepts only the prod environment."
    }

    precondition {
      condition     = terraform.workspace == "default" # 예: workspace 로 환경을 나누지 않음 (backend key 로 구분)
      error_message = "Use default workspace and a distinct backend key."
    }
  }
}

# outputs.tf — platform/core 루트 모듈 (prod · dev 공통 코드)
# 환경 root 와 계약 테스트: child module 의 출력을 같은 이름으로 루트 모듈 밖에 전달합니다. core apply receipt의 등록 필드를 승인 입력 PR로 cert-manager와 ClusterIssuer 선언에 전달합니다.

output "core_identity_contract" {
  description = "Cluster, namespace, service account, cert-manager role ARN and public zone for the Helm install and later roots."
  value       = module.component.core_identity_contract # 예: 6개 항목을 담은 map (cluster_name · namespace · service_account · cert_manager_role_arn · public_zone_id · public_zone_name)
}

# providers.tf — platform/core 루트 모듈 (prod · dev 공통 코드)
# 환경 root 와 계약 테스트: AWS API 만 사용합니다. cert-manager · 정책 · NetworkPolicy는 승인 Git source를 Argo가 설치하며 Kubernetes provider 는 두지 않습니다.
# 리전은 계약(cluster_contract.region)이 아니라 변수로 받습니다. provider 설정이 State 조회 결과에 의존하지 않게 하고, 변수 validation 과 모듈 validation 이 둘 다 ap-northeast-2 로 고정합니다.

provider "aws" {
  region              = var.region                # 예: "ap-northeast-2" (서울 리전; cluster_contract.region 과 같아야 함)
  allowed_account_ids = [var.expected_account_id] # 예: ["222222222222"] (다른 계정이면 실행을 거부)

  # 지원되는 AWS 리소스에 공통 분류 태그를 전달합니다. IAM 권한이 아닙니다.
  default_tags {
    tags = {
      ManagedBy   = "Terraform"     # 예: "Terraform" (수동 생성 리소스와 구분)
      Environment = var.environment # 예: "prod" (환경 구분)
      Component   = "platform-core" # 예: "platform-core" (이 루트 모듈이 만든 리소스에 공통으로 붙는 값)
    }
  }
}

# remote-state.tf — platform/core 루트 모듈 (prod · dev 공통 코드)
# 환경 root 와 계약 테스트: 앞 루트 모듈 두 곳(eks · account-baseline-dns)의 root 출력을 State 에서 직접 읽습니다. cluster-contract.json · deployment.tfvars.json 같은 입력 파일을 만들지 않습니다.
# 읽는 쪽에는 State 객체 전체의 s3:GetObject 권한이 필요합니다 (account-baseline 의 State 역할 key 목록과 대조).

# eks-control-plane · eks-nodes 의 EKS 루트 모듈입니다. locals.tf 가 cluster_contract 12개 항목 중 name · arn · region 만 모듈 입력으로 넘깁니다.
data "terraform_remote_state" "eks" {
  backend = "s3" # 예: "s3" (앞 루트 모듈이 State 를 둔 방식)

  config = {
    bucket = var.state_bucket_name   # 예: "company-prod-tfstate-222222222222"
    key    = "eks/terraform.tfstate" # 예: eks 루트 모듈의 key (클러스터 입력과 네트워크 계약; eks-nodes 노드 구성도 같은 key)
    region = var.region              # 예: "ap-northeast-2"
  }

  lifecycle {
    # 모듈 계약에 넣을 세 항목이 모두 있어야 합니다 (환경 root 와 모듈 연결 의 cluster_contract 출력).
    postcondition {
      condition = alltrue([
        for name in ["name", "arn", "region"] :
        contains(keys(try(self.outputs.cluster_contract, {})), name) # 예: 3개 모두 cluster_contract 에 존재
      ])
      error_message = "eks state must expose cluster_contract with name, arn and region (apply 생성 plan과 private API 검증 first)."
    }
  }
}

# 계정 옵션과 공개 자식 DNS 루트 모듈 의 공개 자식 Zone 루트 모듈입니다 (steps.tsv 에서 retain). Zone 을 만들지 않고 ID 와 이름만 읽습니다.
data "terraform_remote_state" "dns" {
  backend = "s3" # 예: "s3"

  config = {
    bucket = var.state_bucket_name                    # 예: "company-prod-tfstate-222222222222" (같은 버킷)
    key    = "account-baseline-dns/terraform.tfstate" # 예: account-baseline-dns 루트 모듈의 key (account-baseline 결정)
    region = var.region                               # 예: "ap-northeast-2"
  }

  lifecycle {
    # enabled = false 로 만든 State 는 두 출력이 null 입니다. DNS01 은 실제 공개 zone 이 있어야 합니다.
    postcondition {
      condition     = try(self.outputs.public_zone_id != null && self.outputs.public_zone_name != null, false) # 예: "Z…" · "app.playdevops.click" (null 이면 거부)
      error_message = "account-baseline-dns state must expose a non-null public_zone_id and public_zone_name (apply 계정 옵션과 공개 자식 DNS 루트 모듈 with the zone enabled first)."
    }
  }
}

# variables.tf — platform/core 루트 모듈 (prod · dev 공통 코드)
# 환경 root 와 계약 테스트: 루트 모듈 입력 4개입니다. 모듈 변수 4개 중 cluster_contract · public_zone_id · public_zone_name 은 remote-state.tf 가 State 에서 읽으므로 받지 않고,
# 대신 state_bucket_name 을 받습니다. expected_account_id 는 modules/core/variables.tf 와 같은 검사식으로 그대로 전달합니다.

variable "expected_account_id" {
  description = "AWS account that owns the cluster and the public zone; 12 digits."
  type        = string # 예: string (앞자리 0 이 사라지지 않도록 문자열)
  nullable    = false

  validation {
    condition     = can(regex("^[0-9]{12}$", var.expected_account_id)) # 예: "222222222222" 통과
    error_message = "Account ID must be 12 digits."
  }
}

# 클러스터 · zone 이 서울 리전에 있으므로 리전도 고정합니다. 모듈은 cluster_contract.region 이 같은 값인지 따로 검사합니다.
variable "region" {
  description = "AWS region for this root; only ap-northeast-2 is supported."
  type        = string
  default     = "ap-northeast-2" # 기본값: "ap-northeast-2"
  nullable    = false

  validation {
    condition     = var.region == "ap-northeast-2" # 예: 단일 값 비교
    error_message = "This root supports ap-northeast-2 only."
  }
}

# main.tf 의 environment_boundary 가 이 디렉터리에서는 "prod" 만 허용합니다.
variable "environment" {
  description = "Explicit environment name, 2-20 lowercase letters, digits or hyphens."
  type        = string
  nullable    = false

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{1,19}$", var.environment)) # 예: "prod" 통과 / "Prod" 거부
    error_message = "Use a 2-20 character lowercase environment name."
  }
}

# 앞 루트 모듈(eks · account-baseline-dns)의 State 가 있는 버킷입니다. backend.hcl 의 bucket 과 같은 값입니다.
variable "state_bucket_name" {
  description = "S3 bucket holding the eks and account-baseline-dns states read by terraform_remote_state."
  type        = string # 예: "company-prod-tfstate-222222222222" (work/lab.env 의 PROD_STATE_BUCKET)
  nullable    = false

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$", var.state_bucket_name)) # 예: S3 버킷 이름 규칙
    error_message = "state_bucket_name must be a valid S3 bucket name."
  }
}

# versions.tf — platform/core 루트 모듈 (prod · dev 공통 코드)
# 환경 root 와 계약 테스트: Terraform 과 provider 버전을 고정합니다. backend 선언은 backend.tf 에, 모듈 버전은 modules/core/versions.tf 에 있습니다.

terraform {
  required_version = "= 1.16.0" # 예: "= 1.16.0" (등호로 정확한 버전 고정)

  required_providers {
    aws = {
      source  = "hashicorp/aws" # 예: "hashicorp/aws" (공식 레지스트리 경로)
      version = "= 6.62.0"      # 예: "= 6.62.0" (모듈과 같은 값)
    }
  }
}

terraform/environments/prod/platform/gat.modules/gateway/versions.tf:
# versions.tf — modules/gateway (dev · prod 루트 모듈이 공유하는 모듈)
# controller 권한과 소유권: controller 신원(IAM Role · Pod Identity 연결)과 노출 경계(SG · private zone)만 Terraform 으로 관리합니다. NLB 자체는 controller 가 만듭니다.
# 과정 내부 전용 모듈이라 루트 모듈과 같은 값을 등호로 고정합니다. provider 블록은 두지 않습니다 (인증 · 리전 · default_tags 는 루트 모듈의 providers.tf 가 담당).

terraform {
  required_version = "= 1.16.0" # 예: "= 1.16.0" (등호로 정확한 버전 고정)

  required_providers {
    aws = {
      source  = "hashicorp/aws" # 예: "hashicorp/aws" (공식 레지스트리 경로)
      version = "= 6.62.0"      # 예: "= 6.62.0" (aws_eks_pod_identity_association · aws_vpc_security_group_*_rule 을 검증한 버전; 루트 모듈과 같은 값)
    }
  }
}

terraform/environments/prod/platform/gat.modules/gateway/variables.tf:
# variables.tf — modules/gateway (dev · prod 루트 모듈이 공유하는 모듈)
# 루트 모듈은 cluster_contract · public_zone · nlb_subnet_ids 를 앞 루트 모듈 State 에서 읽어 넘기고, exposure_mode · allowed_client_cidrs · existing_private_zone_id 만 terraform.tfvars 로 받습니다.

variable "cluster_contract" {
  description = "Cluster identity (name, arn, region, vpc_id) taken from the eks root output."
  type = object({
    name   = string # 예: "contract2whale-dev-eks"
    arn    = string # 예: "arn:aws:eks:ap-northeast-2:111111111111:cluster/contract2whale-dev-eks"
    region = string # 예: "ap-northeast-2"
    vpc_id = string # 예: "vpc-0123456789abcdef0"
  })
  nullable = false

  validation {
    condition     = var.cluster_contract.region == "ap-northeast-2" # 예: 서울 리전일 때만 참
    error_message = "This implementation is verified for the Seoul region."
  }

  validation {
    condition     = can(regex("^arn:aws:eks:[a-z0-9-]+:[0-9]{12}:cluster/[A-Za-z0-9_-]+$", var.cluster_contract.arn)) # 예: split(":")[4] 로 계정을 꺼낼 수 있는 형식
    error_message = "cluster_contract.arn must be an EKS cluster ARN."
  }
}

variable "expected_account_id" {
  description = "AWS account that owns the cluster, the zones and the security group; 12 digits."
  type        = string # 예: "111111111111" (앞자리 0 이 사라지지 않도록 문자열)
  nullable    = false

  validation {
    condition     = can(regex("^[0-9]{12}$", var.expected_account_id)) # 예: 숫자 12자리만 참
    error_message = "Use a 12-digit AWS account ID."
  }
}

# 인증서 구성(클러스터 보안 기반)과 같은 위임된 public zone 입니다. DNS01 은 공개 TXT 로 private 서비스의 인증서도 검증합니다.
variable "public_zone" {
  description = "Delegated public zone (id, name) shared with the cert-manager DNS01 solver."
  type = object({
    id   = string # 예: "Z0123456789ABCDEFGHIJ"
    name = string # 예: "dev.playdevops.click"
  })
  nullable = false
}

# internal 이 기본이며 입력 없이 인터넷 공개를 하지 않습니다.
variable "exposure_mode" {
  description = "internal (private NLB + private zone), public (internet-facing NLB + public zone) or waf (private NLB behind CloudFront)."
  type        = string     # 예: "internal" (세 갈래 중 하나를 고르는 문자열)
  default     = "internal" # 기본값: "internal" (값을 적지 않으면 비공개 경로)
  nullable    = false

  validation {
    condition     = contains(["internal", "public", "waf"], var.exposure_mode) # 예: 세 값 중 하나일 때만 참
    error_message = "Use internal, public, or waf."
  }
}

# internal · public의 IPv4 CIDR 규칙 입력입니다. 빈 목록은 이 모듈의 clients 규칙만 0개로 만듭니다. 별도 SG 출발지 규칙과 NLB에 연결된 모든 SG의 현재 규칙은 따로 대조합니다.
variable "allowed_client_cidrs" {
  description = "Approved client IPv4 CIDRs allowed to reach the NLB on TCP 443; empty means no CIDR rule."
  type        = set(string) # 예: ["203.0.113.7/32"] (승인된 접속망 목록)
  default     = []          # 기본값: [] (이 모듈의 clients CIDR 규칙 0개)
  nullable    = false

  validation {
    condition     = alltrue([for c in var.allowed_client_cidrs : can(cidrnetmask(c))]) # 예: 모든 원소가 IPv4 CIDR 형식일 때만 참
    error_message = "Use valid IPv4 CIDRs."
  }
}

# 기존 private zone 을 재사용할 때만 지정합니다. null 이면 internal · waf 모드에서 VPC 전용 zone 을 새로 만듭니다.
variable "existing_private_zone_id" {
  description = "Existing private hosted zone ID to reuse (already associated with the VPC); null creates a new one."
  type        = string # 예: "Z0PRIVATE00000000000"
  default     = null   # 기본값: null (재사용하지 않고 새로 만듭니다)
  nullable    = true   # 예: true (null 을 정상 값으로 받습니다)
}

variable "nlb_subnet_ids" {
  description = "Exactly three subnet IDs (one per Seoul AZ) where the controller places the NLB."
  type        = set(string) # 예: ["subnet-00000000000000001", "subnet-00000000000000002", "subnet-00000000000000003"]
  nullable    = false

  validation {
    condition     = length(var.nlb_subnet_ids) == 3 && alltrue([for s in var.nlb_subnet_ids : can(regex("^subnet-[0-9a-f]{8,17}$", s))])
    error_message = "Supply three distinct subnet IDs from the workload VPC."
  }
}

terraform/environments/prod/platform/gat.modules/gateway/main.tf:
# main.tf — modules/gateway (dev · prod 루트 모듈이 공유하는 모듈)
# NLB · Target Group 은 이 파일이 만들지 않습니다. AWS Load Balancer Controller 가 Gateway 의 Service 를 보고 만들고, Terraform 은 그 controller 의 신원과 권한만 소유합니다.
# 노출 경계(private zone · Security Group · 규칙)는 exposure.tf(exposure_mode 와 zone · NLB Security Group), 출력은 outputs.tf(exposure_mode 와 zone · NLB Security Group) 에 있습니다.

# 실제 plan 에서는 AWS 로 클러스터 · VPC · zone · 서브넷을 조회합니다. mock 테스트(tests/contracts.tftest.hcl)는 override_data 로 같은 모양의 응답을 줍니다.
data "aws_eks_cluster" "this" {
  name = var.cluster_contract.name # 예: "contract2whale-dev-eks" (계약에 적힌 클러스터 이름)
}

data "aws_vpc" "this" {
  id = var.cluster_contract.vpc_id # 예: "vpc-0123456789abcdef0" (계약에 적힌 VPC; cidr_block 은 exposure.tf 의 송신 규칙이 씀)
}

data "aws_route53_zone" "public" {
  name         = var.public_zone.name # 예: "dev.playdevops.click" (위임이 끝난 공개 zone 이름)
  private_zone = false                # 예: false (동일 이름 private zone을 제외한 공개 zone 조회)
}

data "aws_route53_zone" "private" {
  count        = contains(["internal", "waf"], var.exposure_mode) && var.existing_private_zone_id != null ? 1 : 0 # 예: internal + 재사용 ID → 1, 그 밖에는 0
  name         = var.public_zone.name                                                                             # 예: "dev.playdevops.click" (public zone 과 같은 이름)
  private_zone = true                                                                                             # 예: true (VPC 에 연결된 private zone 만 찾음)
  vpc_id       = var.cluster_contract.vpc_id                                                                      # 예: "vpc-0123456789abcdef0" (이 VPC 에 연결된 zone 으로 한정)
}

data "aws_subnet" "nlb" {
  for_each = var.nlb_subnet_ids # 예: 서브넷 ID 3개 집합 (원소마다 조회 1개)
  id       = each.value         # 예: "subnet-00000000000000001"
}

resource "terraform_data" "contract" {
  lifecycle {
    precondition {
      condition     = alltrue([for s in data.aws_subnet.nlb : s.vpc_id == var.cluster_contract.vpc_id]) # 예: 서브넷 3개가 모두 계약의 VPC 에 있을 때만 참
      error_message = "NLB subnets must belong to the intended VPC."
    }

    precondition {
      condition     = length(toset([for s in data.aws_subnet.nlb : s.availability_zone])) == 3 && alltrue([for s in data.aws_subnet.nlb : contains(["ap-northeast-2a", "ap-northeast-2b", "ap-northeast-2c"], s.availability_zone)])
      error_message = "NLB subnets must sit in three distinct Seoul AZs."
    }

    precondition {
      condition     = terraform.workspace == "default" # 예: workspace 로 환경을 나누지 않음 (backend key 로 구분)
      error_message = "Use default workspace and a distinct backend key."
    }

    precondition {
      condition     = data.aws_eks_cluster.this.arn == var.cluster_contract.arn # 예: 이름으로 조회한 ARN 과 계약 ARN 이 글자 하나까지 같아야 통과
      error_message = "The EKS cluster looked up by name must match cluster_contract.arn (intended same-account cluster)."
    }

    precondition {
      condition     = split(":", var.cluster_contract.arn)[4] == var.expected_account_id # 예: ARN 의 5번째 항목(계정 12자리) == expected_account_id
      error_message = "cluster_contract.arn must belong to expected_account_id."
    }

    precondition {
      condition     = data.aws_eks_cluster.this.vpc_config[0].vpc_id == var.cluster_contract.vpc_id # 예: 클러스터가 보고하는 VPC 와 계약의 vpc_id 가 같아야 통과
      error_message = "The cluster must run in cluster_contract.vpc_id."
    }

    precondition {
      condition     = data.aws_route53_zone.public.zone_id == var.public_zone.id # 예: 이름으로 조회한 공개 zone ID 와 입력 ID 를 대조
      error_message = "The public zone name and ID must match."
    }

    precondition {
      # 예: 재사용 ID 를 넣은 internal · waf 모드에서만 조회 결과와 입력 ID 를 비교 (그 밖에는 항상 참)
      condition     = var.existing_private_zone_id == null || !contains(["internal", "waf"], var.exposure_mode) ? true : data.aws_route53_zone.private[0].zone_id == var.existing_private_zone_id
      error_message = "The private zone must match the name, ID and VPC association."
    }

    precondition {
      condition     = var.exposure_mode != "waf" || length(var.allowed_client_cidrs) == 0 # 예: waf 모드가 아니거나, waf 모드에서 허용 CIDR 이 비어 있을 때만 참
      error_message = "WAF mode only accepts CloudFront origin traffic; do not add bypass client CIDRs."
    }
  }
}

locals {
  # ExternalDNS 가 레코드를 쓸 zone 입니다. internal · waf 는 private zone ID(재사용 또는 exposure.tf 가 만든 것), public 은 공개 zone ID 입니다.
  dns_zone_id = contains(["internal", "waf"], var.exposure_mode) ? (var.existing_private_zone_id != null ? var.existing_private_zone_id : aws_route53_zone.internal[0].zone_id) : var.public_zone.id # 예: "Z0PRIVATE00000000000"

  # controller 마다 Role 1 + Pod Identity 연결 1. waf 모드는 앱 DNS 를 Edge Terraform 이 소유하므로 ExternalDNS 신원을 만들지 않습니다.
  controllers = merge(
    { lbc = { namespace = "kube-system", sa = "aws-load-balancer-controller" } },                  # 예: Helm values 의 serviceAccount.name 과 같은 이름
    var.exposure_mode != "waf" ? { dns = { namespace = "kube-system", sa = "external-dns" } } : {} # 예: waf 가 아니면 항목 2개(lbc, dns), waf 면 1개(lbc)
  )
}

# Pod Identity 의 namespace · ServiceAccount · 클러스터 세션 태그를 모두 고정합니다 (DNS01 최소 권한과 Pod Identity 의 cert-manager Role 과 같은 신뢰 조건).
resource "aws_iam_role" "controller" {
  for_each = local.controllers                               # 예: { lbc = {...}, dns = {...} } (항목마다 Role 1개)
  name     = "${var.cluster_contract.name}-${each.value.sa}" # 예: "contract2whale-dev-eks-aws-load-balancer-controller" · "contract2whale-dev-eks-external-dns"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "pods.eks.amazonaws.com" } # 예: Pod Identity 서비스만 이 Role 을 맡음
      Action    = ["sts:AssumeRole", "sts:TagSession"]   # 예: 세션 태그를 붙이려면 TagSession 도 필요
      Condition = {
        StringEquals = {
          "aws:RequestTag/kubernetes-namespace"       = each.value.namespace     # 예: "kube-system"
          "aws:RequestTag/kubernetes-service-account" = each.value.sa            # 예: "aws-load-balancer-controller"
          "aws:RequestTag/eks-cluster-arn"            = var.cluster_contract.arn # 예: "arn:aws:eks:ap-northeast-2:111111111111:cluster/contract2whale-dev-eks"
        }
      }
    }]
  })

  depends_on = [terraform_data.contract] # 예: 계약 검사를 통과한 뒤에 만듭니다
}

# 공식 LBC v3.5.0 정책 원문입니다. EC2 조회와 ELB 생성에는 Resource = * 가 필요한 항목이 있습니다.
resource "aws_iam_policy" "lbc" {
  name   = "${var.cluster_contract.name}-load-balancer-controller"                  # 예: "contract2whale-dev-eks-load-balancer-controller"
  policy = file("${path.module}/policies/aws-load-balancer-controller-v3.5.0.json") # 예: 모듈 안의 공식 controller IAM 정책 파일을 읽음
}

resource "aws_iam_role_policy_attachment" "lbc" {
  role       = aws_iam_role.controller["lbc"].name # 예: "contract2whale-dev-eks-aws-load-balancer-controller"
  policy_arn = aws_iam_policy.lbc.arn              # 예: "arn:aws:iam::111111111111:policy/contract2whale-dev-eks-load-balancer-controller"
}

# ExternalDNS의 이 IAM 정책은 선택 zone의 A·AAAA·CNAME·TXT 변경을 허용합니다. DNS01 challenge TXT의 실제 생성·정리는 cert-manager solver가 담당하며, 별도로 승인한 core 신원·ClusterIssuer source를 대조합니다. 이 정책은 레코드 이름별 소유권 검사가 아닙니다.
resource "aws_iam_role_policy" "dns" {
  count = var.exposure_mode != "waf" ? 1 : 0 # 예: waf 모드가 아니면 1개, waf 모드면 0개
  role  = aws_iam_role.controller["dns"].id  # 예: "contract2whale-dev-eks-external-dns"
  name  = "route53-records"                  # 예: "route53-records" (Role 안에 붙는 inline 정책 이름)

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["route53:ListHostedZones", "route53:ListHostedZonesByName"] # 예: zone 목록 조회는 계정 전체 대상
        Resource = ["*"]
      },
      {
        Effect   = "Allow"
        Action   = ["route53:ListResourceRecordSets"]                    # 예: 레코드 조회는 선택한 zone 하나만
        Resource = ["arn:aws:route53:::hostedzone/${local.dns_zone_id}"] # 예: "arn:aws:route53:::hostedzone/Z0PRIVATE00000000000"
      },
      {
        Effect   = "Allow"
        Action   = ["route53:ChangeResourceRecordSets"] # 예: 레코드 변경은 선택한 zone 에서 A · AAAA · CNAME · TXT 만
        Resource = ["arn:aws:route53:::hostedzone/${local.dns_zone_id}"]
        Condition = {
          "ForAllValues:StringEquals" = {
            "route53:ChangeResourceRecordSetsRecordTypes" = ["A", "AAAA", "CNAME", "TXT"] # 예: NS · SOA · MX 등은 거부
          }
        }
      }
    ]
  })
}

resource "aws_eks_pod_identity_association" "controller" {
  for_each        = local.controllers                     # 예: 항목마다 연결 1개
  cluster_name    = var.cluster_contract.name             # 예: "contract2whale-dev-eks"
  namespace       = each.value.namespace                  # 예: "kube-system"
  service_account = each.value.sa                         # 예: "aws-load-balancer-controller" · "external-dns"
  role_arn        = aws_iam_role.controller[each.key].arn # 예: "arn:aws:iam::111111111111:role/contract2whale-dev-eks-external-dns"

  depends_on = [aws_iam_role_policy_attachment.lbc, aws_iam_role_policy.dns] # 예: 권한이 붙은 뒤에 연결합니다
}

terraform/environments/prod/platform/gat.terraform/environments/prod/platform/gat:
# backend.tf — platform/gateway 루트 모듈 (prod · dev 공통 코드)
# 환경 root 두 개 연결: backend 인자는 커밋하지 않는 backend.hcl 이 제공합니다 (terraform init -backend-config=backend.hcl).
# key 는 platform/gateway/terraform.tfstate 로 실행 디렉터리 경로 규칙을 따릅니다 (platform/core/terraform.tfstate 와 같은 버킷; 원본의 platform/gateway-iam/prod/… 를 P2 규칙으로 바꿈).

terraform {
  backend "s3" {}
}

# locals.tf — platform/gateway 루트 모듈 (prod · dev 공통 코드)
# 환경 root 두 개 연결: State 에서 읽은 출력을 모듈 입력 모양으로 조립합니다. 세 값 모두 이 루트 모듈이 직접 입력받지 않습니다.

locals {
  # modules/gateway 의 cluster_contract 객체입니다. eks State 의 12개 항목 중 네 항목만 골라 계약 모양을 명시합니다.
  cluster_contract = {
    name   = data.terraform_remote_state.eks.outputs.cluster_contract.name   # 예: "contract2whale-prod-eks"
    arn    = data.terraform_remote_state.eks.outputs.cluster_contract.arn    # 예: "arn:aws:eks:ap-northeast-2:222222222222:cluster/contract2whale-prod-eks"
    region = data.terraform_remote_state.eks.outputs.cluster_contract.region # 예: "ap-northeast-2"
    vpc_id = data.terraform_remote_state.eks.outputs.cluster_contract.vpc_id # 예: "vpc-0123456789abcdef0"
  }

  public_zone = {
    id   = data.terraform_remote_state.dns.outputs.public_zone_id   # 예: "Z0123456789ABCDEFGHIJ" (계정 옵션과 공개 자식 DNS 루트 모듈 출력)
    name = data.terraform_remote_state.dns.outputs.public_zone_name # 예: "app.playdevops.click" (끝의 점 없음)
  }

  # public 은 IGW 경로가 있는 public 서브넷, internal · waf 는 NAT 뒤의 일반 Private 서브넷(vpc)입니다. EKS 서브넷(eks-network)은 노드 · Pod 전용으로 남깁니다.
  nlb_subnet_ids = toset(var.exposure_mode == "public" ? data.terraform_remote_state.network.outputs.public_subnet_ids : data.terraform_remote_state.network.outputs.private_subnet_ids) # 예: ["subnet-0pri1...", "subnet-0pri2...", "subnet-0pri3..."]
}

# main.tf — platform/gateway 루트 모듈 (prod · dev 공통 코드)
# 환경 root 두 개 연결: 환경별 입력은 루트 모듈, 재사용 리소스는 모듈에서 관리합니다. module "component" 로 변수 7개를 전달하고 환경 경계 1개를 둡니다.

module "component" {
  source = "../../../../../modules/gateway" # 예: 이 루트 모듈에서 모듈까지의 상대 경로 (다섯 단계 위가 저장소 최상위)

  cluster_contract         = local.cluster_contract       # 예: eks State 출력으로 조립한 {name, arn, region, vpc_id}
  expected_account_id      = var.expected_account_id      # 예: "222222222222"
  public_zone              = local.public_zone            # 예: account-baseline-dns State 출력으로 조립한 {id, name}
  exposure_mode            = var.exposure_mode            # 예: "waf" (Prod 선택값)
  allowed_client_cidrs     = var.allowed_client_cidrs     # 예: [] (최종 Prod)
  existing_private_zone_id = var.existing_private_zone_id # 예: null (없으면 새로 만듦)
  nlb_subnet_ids           = local.nlb_subnet_ids         # 예: network/vpc State 의 서브넷 3개 (모드에 따라 public · private)
}

# 이 디렉터리는 prod 만 받습니다. input 은 State 에 남는 marker 이며 AWS 자원을 만들지 않습니다.
resource "terraform_data" "environment_boundary" {
  input = var.environment # 예: "prod" (input 변경은 in-place 갱신)

  lifecycle {
    precondition {
      condition     = var.environment == "prod" # 예: "prod" 통과 / "dev" 거부 (dev 는 dev/platform/gateway 디렉터리)
      error_message = "This directory accepts only the prod environment."
    }

    precondition {
      condition     = terraform.workspace == "default" # 예: workspace 로 환경을 나누지 않음 (backend key 로 구분)
      error_message = "Use default workspace and a distinct backend key."
    }
  }
}

# providers.tf — platform/gateway 루트 모듈 (prod · dev 공통 코드)
# 환경 root 두 개 연결: AWS API 만 사용합니다. controller · Gateway · 인증서는 승인 Git source를 Argo가 설치하며 Kubernetes provider 는 두지 않습니다.
# 리전은 계약(cluster_contract.region)이 아니라 변수로 받습니다. provider 설정이 State 조회 결과에 의존하지 않게 하고, 변수 validation 과 모듈 validation 이 둘 다 ap-northeast-2 로 고정합니다.

provider "aws" {
  region              = var.region                # 예: "ap-northeast-2" (서울 리전; cluster_contract.region 과 같아야 함)
  allowed_account_ids = [var.expected_account_id] # 예: ["222222222222"] (다른 계정이면 실행을 거부)

  # 지원되는 AWS 리소스에 공통 분류 태그를 전달합니다. IAM 권한이 아닙니다.
  default_tags {
    tags = {
      ManagedBy   = "Terraform"        # 예: "Terraform" (수동 생성 리소스와 구분)
      Environment = var.environment    # 예: "prod" (환경 구분)
      Component   = "platform-gateway" # 예: "platform-gateway" (이 루트 모듈이 만든 리소스에 공통으로 붙는 값)
    }
  }
}

# remote-state.tf — platform/gateway 루트 모듈 (prod · dev 공통 코드)
# 환경 root 두 개 연결: 앞 루트 모듈 세 곳(eks · account-baseline-dns · network/vpc)의 root 출력을 State 에서 직접 읽습니다. input.auto.tfvars.json 같은 입력 파일을 만들지 않습니다.
# 읽는 쪽에는 State 객체 전체의 s3:GetObject 권한이 필요합니다 (account-baseline 의 State 역할 key 목록과 대조).

# eks-control-plane · eks-nodes 의 EKS 루트 모듈입니다. locals.tf 가 cluster_contract 12개 항목 중 name · arn · region · vpc_id 만 모듈 입력으로 넘깁니다.
data "terraform_remote_state" "eks" {
  backend = "s3" # 예: "s3" (앞 루트 모듈이 State 를 둔 방식)

  config = {
    bucket = var.state_bucket_name   # 예: "company-prod-tfstate-222222222222"
    key    = "eks/terraform.tfstate" # 예: eks 루트 모듈의 key (클러스터 입력과 네트워크 계약)
    region = var.region              # 예: "ap-northeast-2"
  }

  lifecycle {
    postcondition {
      condition = alltrue([
        for name in ["name", "arn", "region", "vpc_id"] :
        contains(keys(try(self.outputs.cluster_contract, {})), name) # 예: 4개 모두 cluster_contract 에 존재
      ])
      error_message = "eks state must expose cluster_contract with name, arn, region and vpc_id (apply 생성 plan과 private API 검증 first)."
    }
  }
}

# 계정 옵션과 공개 자식 DNS 루트 모듈 의 공개 자식 Zone 루트 모듈입니다 (steps.tsv 에서 retain). cert-manager DNS01 과 같은 zone 입니다.
data "terraform_remote_state" "dns" {
  backend = "s3" # 예: "s3"

  config = {
    bucket = var.state_bucket_name                    # 예: 같은 버킷
    key    = "account-baseline-dns/terraform.tfstate" # 예: account-baseline-dns 루트 모듈의 key (account-baseline 결정)
    region = var.region                               # 예: "ap-northeast-2"
  }

  lifecycle {
    postcondition {
      condition     = try(self.outputs.public_zone_id != null && self.outputs.public_zone_name != null, false) # 예: "Z…" · "app.playdevops.click" (null 이면 거부)
      error_message = "account-baseline-dns state must expose a non-null public_zone_id and public_zone_name (apply 계정 옵션과 공개 자식 DNS 루트 모듈 with the zone enabled first)."
    }
  }
}

# vpc · eks-network 의 네트워크 루트 모듈입니다. NLB 서브넷은 exposure_mode 에 따라 public_subnet_ids 또는 private_subnet_ids(vpc 일반 Private 3개) 를 씁니다.
data "terraform_remote_state" "network" {
  backend = "s3" # 예: "s3"

  config = {
    bucket = var.state_bucket_name           # 예: 같은 버킷
    key    = "network/vpc/terraform.tfstate" # 예: network/vpc 루트 모듈의 key (출력 계약과 계약 테스트)
    region = var.region                      # 예: "ap-northeast-2"
  }

  lifecycle {
    postcondition {
      condition     = length(try(self.outputs.public_subnet_ids, [])) == 3 && length(try(self.outputs.private_subnet_ids, [])) == 3 # 예: 두 목록 모두 AZ 3개
      error_message = "network/vpc state must expose three public_subnet_ids and three private_subnet_ids (apply 출력 계약과 계약 테스트 first)."
    }
  }
}

# variables.tf — platform/gateway 루트 모듈 (prod · dev 공통 코드)
# 환경 root 두 개 연결: 루트 모듈 입력 7개입니다. 모듈 변수 7개 중 cluster_contract · public_zone · nlb_subnet_ids 는 remote-state.tf 가 State(eks · account-baseline-dns · network/vpc)에서 읽으므로 받지 않고,
# 대신 region · environment · state_bucket_name 을 받습니다. expected_account_id · exposure_mode · allowed_client_cidrs · existing_private_zone_id 는 모듈과 같은 검사식으로 그대로 전달합니다.

variable "expected_account_id" {
  description = "AWS account that owns the cluster, the zones and the security group; 12 digits."
  type        = string # 예: string (앞자리 0 이 사라지지 않도록 문자열)
  nullable    = false

  validation {
    condition     = can(regex("^[0-9]{12}$", var.expected_account_id)) # 예: "222222222222" 통과
    error_message = "Account ID must be 12 digits."
  }
}

# 클러스터 · zone 이 서울 리전에 있으므로 리전도 고정합니다. 모듈은 cluster_contract.region 이 같은 값인지 따로 검사합니다.
variable "region" {
  description = "AWS region for this root; only ap-northeast-2 is supported."
  type        = string
  default     = "ap-northeast-2" # 기본값: "ap-northeast-2"
  nullable    = false

  validation {
    condition     = var.region == "ap-northeast-2" # 예: 단일 값 비교
    error_message = "This root supports ap-northeast-2 only."
  }
}

# main.tf 의 environment_boundary 가 이 디렉터리에서는 "prod" 만 허용합니다.
variable "environment" {
  description = "Explicit environment name, 2-20 lowercase letters, digits or hyphens."
  type        = string
  nullable    = false

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{1,19}$", var.environment)) # 예: "prod" 통과 / "Prod" 거부
    error_message = "Use a 2-20 character lowercase environment name."
  }
}

# 앞 루트 모듈(eks · account-baseline-dns · network/vpc)의 State 가 있는 버킷입니다. backend.hcl 의 bucket 과 같은 값입니다.
variable "state_bucket_name" {
  description = "S3 bucket holding the eks, account-baseline-dns and network/vpc states read by terraform_remote_state."
  type        = string # 예: "company-prod-tfstate-222222222222" (work/lab.env 의 PROD_STATE_BUCKET)
  nullable    = false

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$", var.state_bucket_name)) # 예: S3 버킷 이름 규칙
    error_message = "state_bucket_name must be a valid S3 bucket name."
  }
}

# Prod 는 waf 입니다. locals.tf 가 이 값으로 NLB 서브넷(public ↔ private)을 고릅니다.
variable "exposure_mode" {
  description = "internal (private NLB + private zone), public (internet-facing NLB + public zone) or waf (private NLB behind CloudFront)."
  type        = string
  default     = "internal" # 기본값: "internal"
  nullable    = false

  validation {
    condition     = contains(["internal", "public", "waf"], var.exposure_mode) # 예: 세 값 중 하나
    error_message = "Use internal, public, or waf."
  }
}

# waf 모드는 빈 목록이어야 합니다 (모듈 precondition 이 CIDR 우회를 거부; 공개 원본 접속은 후편 CloudFront VPC Origin 절차에서 구성).
variable "allowed_client_cidrs" {
  description = "Approved client IPv4 CIDRs allowed to reach the NLB on TCP 443; empty means no CIDR rule."
  type        = set(string)
  default     = [] # 기본값: [] (인바운드 CIDR 규칙 0개)
  nullable    = false

  validation {
    condition     = alltrue([for c in var.allowed_client_cidrs : can(cidrnetmask(c))]) # 예: IPv4 CIDR 형식만
    error_message = "Use valid IPv4 CIDRs."
  }
}

variable "existing_private_zone_id" {
  description = "Existing private hosted zone ID to reuse (already associated with the VPC); null creates a new one."
  type        = string
  default     = null # 기본값: null (모듈이 VPC 전용 private zone 을 새로 만듦)
  nullable    = true
}

# versions.tf — platform/gateway 루트 모듈 (prod · dev 공통 코드)
# 환경 root 두 개 연결: Terraform 과 provider 버전을 고정합니다. backend 선언은 backend.tf 에, 모듈 버전은 modules/gateway/versions.tf 에 있습니다.

terraform {
  required_version = "= 1.16.0" # 예: "= 1.16.0" (등호로 정확한 버전 고정)

  required_providers {
    aws = {
      source  = "hashicorp/aws" # 예: "hashicorp/aws" (공식 레지스트리 경로)
      version = "= 6.62.0"      # 예: "= 6.62.0" (모듈과 같은 값)
    }
  }
}

terraform/environments/prod/platform/ale.modules/alerting/versions.tf:
# versions.tf — modules/alerting (dev · prod 루트 모듈이 공유하는 모듈)
# 계정 이벤트 경보 모듈: 계정 이벤트 경보(SNS 토픽 · 이메일 구독 · EventBridge 규칙 · 로그 지표 필터 · 경보 · Alertmanager Pod Identity)만 Terraform 으로 관리합니다.
# 과정 내부 전용 모듈이라 루트 모듈과 같은 값을 등호로 고정합니다 (P7). provider 블록은 두지 않습니다.

terraform {
  required_version = "= 1.16.0" # 예: "= 1.16.0" (이 버전에서만 실행합니다)

  required_providers {
    aws = {
      source  = "hashicorp/aws" # 예: "hashicorp/aws" (공식 레지스트리 경로)
      version = "= 6.62.0"      # 예: "= 6.62.0" (AWS provider 를 한 버전으로 고정합니다)
    }
  }
}

terraform/environments/prod/platform/ale.modules/alerting/variables.tf:
# variables.tf — modules/alerting (dev · prod 루트 모듈이 공유하는 모듈)

variable "expected_account_id" {
  # 예: Dev 111111111111 / Prod 222222222222. 사용자의 실제 로그인 계정으로 치환합니다.
  description = "알림 리소스를 관리할 실제 AWS 계정 ID."
  type        = string # 예: string (계정 번호를 문자열로 받습니다)
  nullable    = false  # 예: false (값을 비울 수 없습니다)

  validation {
    condition     = can(regex("^[0-9]{12}$", var.expected_account_id)) # 예: "111111111111" 통과, "123" 거부
    error_message = "expected_account_id must contain exactly 12 digits."
  }
}

variable "environment" {
  # 예: dev. 이 값이 topic · alarm 이름과 계약의 환경 경계를 정합니다.
  description = "Environment name that prefixes every alerting resource name (contract2whale-<environment>-…)."
  type        = string # 예: string (환경 이름을 문자열로 받습니다)
  nullable    = false  # 예: false (값을 비울 수 없습니다)

  validation {
    condition     = contains(["dev", "prod"], var.environment) # 예: "dev" 통과, "stage" 거부
    error_message = "environment must be dev or prod."
  }
}

variable "region" {
  # 예: ap-northeast-2 (서울). cluster ARN 의 리전도 같아야 합니다.
  description = "AWS region; only ap-northeast-2 is supported."
  type        = string           # 예: string (리전 이름을 문자열로 받습니다)
  default     = "ap-northeast-2" # 예: "ap-northeast-2" (서울 리전)
  nullable    = false            # 예: false (값을 비울 수 없습니다)

  validation {
    condition     = var.region == "ap-northeast-2" # 예: "us-east-1" 거부
    error_message = "This course alerting module supports ap-northeast-2 only."
  }
}

variable "cluster_contract" {
  # 예: { name="contract2whale-dev-eks", arn="arn:aws:eks:ap-northeast-2:111111111111:cluster/contract2whale-dev-eks", region="ap-northeast-2" }.
  description = "같은 환경의 EKS cluster_contract output. 필요한 필드만 읽는다."
  type        = object({ name = string, arn = string, region = string }) # 예: 필드 세 개를 가진 object (나머지 항목은 타입 변환에서 제외)
  nullable    = false                                                    # 예: false (값을 비울 수 없습니다)

  validation {
    condition     = can(regex("^[A-Za-z0-9][A-Za-z0-9_-]{0,99}$", var.cluster_contract.name)) # 예: "contract2whale-dev-eks" 통과
    error_message = "cluster_contract.name must be a valid EKS cluster name."
  }
}

variable "platform_log_group_name" {
  # 예: /platform/contract2whale-dev-eks/application. 운영 기반 구성이 이미 만든 플랫폼 컨테이너 로그 그룹입니다.
  description = "같은 환경 operations_contract의 platform_log_group_name."
  type        = string # 예: string (로그 그룹 이름을 문자열로 받습니다)
  nullable    = false  # 예: false (값을 비울 수 없습니다)
}

variable "receiver_email" {
  # 예: ops-alerts@example.com. 메일 주소를 바꾸면 새 구독 확인이 필요합니다.
  description = "SNS 확인 이메일을 수신하고 구독을 직접 승인할 주소."
  type        = string                   # 예: string (주소를 문자열로 받습니다)
  default     = "ops-alerts@example.com" # 예: 실습자가 자기 주소로 바꾸는 자리
  nullable    = false                    # 예: null 이면 위 기본 주소를 사용합니다

  validation {
    condition     = can(regex("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$", var.receiver_email)) # 예: "not-an-email" 거부
    error_message = "receiver_email must be an email address without whitespace."
  }
}

variable "sample_delete_validation_run_id" {
  # 예: 평소 null, Dev 노드 점검 직전에만 verify-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.
  description = "Dev 노드 점검 감지만 명시적으로 무장하는 단일 validation run ID. null이면 생성하지 않는다."
  type        = string # 예: string (식별자를 문자열로 받습니다)
  default     = null   # 예: null (감지를 만들지 않는 기본 상태)

  validation {
    # 예: null 통과, "verify-0123456789abcdef0123456789abcdef" 통과, "verify-all" 거부
    condition     = var.sample_delete_validation_run_id == null ? true : can(regex("^verify-[0-9a-f]{32}$", var.sample_delete_validation_run_id))
    error_message = "Use null or verify- followed by exactly 32 lowercase hex characters."
  }
}

terraform/environments/prod/platform/ale.modules/alerting/main.tf:
# main.tf — modules/alerting (dev · prod 루트 모듈이 공유하는 모듈)
# 이메일 구독은 수신자가 확인 링크를 눌러야 전달됩니다 (Terraform 이 확인할 수 없음). Alertmanager 자체는 관측 파이프라인 가 설치하며 여기서는 신원과 게시 권한만 만듭니다 (E3).

locals {
  # 예: environment=dev 이면 이름 접두사는 contract2whale-dev 입니다.
  prefix                       = "contract2whale-${var.environment}"                                     # 예: "contract2whale-dev" (모든 이름의 앞부분)
  namespace                    = "monitoring"                                                            # 예: "monitoring" (경보를 묶는 Pod 의 네임스페이스; 관측 파이프라인 kube-prometheus-stack)
  alertmanager_service_account = "platform-alertmanager"                                                 # 예: 그 Pod 의 ServiceAccount 이름 (알림 루트 모듈과 설치 검사 overlay 의 serviceAccount.name)
  metric_namespace             = "contract2whale/Incidents/${var.environment}"                           # 예: "contract2whale/Incidents/dev" (지표를 담는 네임스페이스)
  sample_deletion_armed        = var.environment == "dev" && var.sample_delete_validation_run_id != null # 예: false (기본 상태)
}

resource "terraform_data" "contract" {
  input = {
    account_id   = var.expected_account_id   # 예: "111111111111" (값이 바뀌면 검사를 다시 실행합니다)
    environment  = var.environment           # 예: "dev"
    cluster_name = var.cluster_contract.name # 예: "contract2whale-dev-eks"
  }

  lifecycle {
    precondition {
      # 예: 다른 계정의 ARN 이나 다른 리전의 계약을 넣으면 거부합니다
      condition     = var.cluster_contract.region == var.region && var.cluster_contract.arn == "arn:aws:eks:${var.region}:${var.expected_account_id}:cluster/${var.cluster_contract.name}"
      error_message = "cluster_contract must match the expected account, Seoul region and cluster name."
    }
    precondition {
      condition     = var.cluster_contract.name == "contract2whale-${var.environment}-eks" # 예: Prod 이름을 Dev 입력에 넣으면 거부
      error_message = "cluster_contract.name must match contract2whale-<environment>-eks."
    }
    precondition {
      condition     = var.platform_log_group_name == "/platform/${var.cluster_contract.name}/application" # 예: 다른 클러스터의 로그 그룹을 넣으면 거부
      error_message = "platform_log_group_name must belong to this cluster's operations contract."
    }
    precondition {
      condition     = var.sample_delete_validation_run_id == null || var.environment == "dev" # 예: Prod 에서 감지를 켜면 거부
      error_message = "Sample deletion detection can be armed only in dev."
    }
  }
}

resource "aws_sns_topic" "alerts" {
  # 예: contract2whale-dev-alerts (Prod 는 별도 계정의 contract2whale-prod-alerts).
  name       = "${local.prefix}-alerts" # 예: "contract2whale-dev-alerts"
  fifo_topic = false                    # 예: false (이메일 구독을 지원하는 Standard 토픽)

  depends_on = [terraform_data.contract] # 예: 소유권 검사를 통과한 뒤에 만듭니다
}

# email endpoint 의 소유자가 받은 확인 링크를 직접 승인해야 알림이 전달됩니다.
resource "aws_sns_topic_subscription" "email" {
  # 예: 같은 환경 topic ARN 과 ops-alerts@example.com. 확인 링크는 수신자가 승인합니다.
  topic_arn              = aws_sns_topic.alerts.arn # 예: 위에서 만든 토픽 하나
  protocol               = "email"                  # 예: "email" (메일로 받습니다)
  endpoint               = var.receiver_email       # 예: "ops-alerts@example.com"
  endpoint_auto_confirms = false                    # 예: false (endpoint 의 자동 확인 처리를 가정하지 않습니다)
}

resource "aws_iam_role" "alertmanager" {
  # 예: contract2whale-dev-alertmanager. 노드 역할에 SNS 권한을 추가하지 않습니다.
  name = "${local.prefix}-alertmanager" # 예: "contract2whale-dev-alertmanager"
  assume_role_policy = jsonencode({
    Version = "2012-10-17" # 예: 정책 문서 형식의 버전 번호
    Statement = [{
      Effect    = "Allow"                                # 예: "Allow" (허용)
      Principal = { Service = "pods.eks.amazonaws.com" } # 예: Pod 별 신원 경로의 주체
      Action    = ["sts:AssumeRole", "sts:TagSession"]   # 예: 역할을 맡고 세션 태그를 전달합니다
      Condition = {
        StringEquals = {
          # 예: arn:aws:eks:ap-northeast-2:111111111111:cluster/contract2whale-dev-eks.
          "aws:RequestTag/eks-cluster-arn"            = var.cluster_contract.arn           # 예: 이 클러스터여야 합니다
          "aws:RequestTag/kubernetes-namespace"       = local.namespace                    # 예: "monitoring"
          "aws:RequestTag/kubernetes-service-account" = local.alertmanager_service_account # 예: "platform-alertmanager"
        }
      }
    }]
  })

  depends_on = [terraform_data.contract] # 예: 소유권 검사를 통과한 뒤에 만듭니다
}

resource "aws_iam_role_policy" "publish" {
  name = "publish-environment-alerts" # 예: 역할에 붙는 인라인 정책 이름
  role = aws_iam_role.alertmanager.id # 예: 위에서 만든 역할
  policy = jsonencode({
    Version = "2012-10-17" # 예: 정책 문서 형식의 버전 번호
    Statement = [{
      Effect = "Allow"       # 예: "Allow" (허용)
      Action = "sns:Publish" # 예: 게시 동작 하나만 허용합니다
      # 예: arn:aws:sns:ap-northeast-2:111111111111:contract2whale-dev-alerts 하나만 허용합니다.
      Resource = aws_sns_topic.alerts.arn
    }]
  })
}

resource "aws_eks_pod_identity_association" "alertmanager" {
  # 예: contract2whale-dev-eks 의 monitoring/platform-alertmanager 에만 역할을 연결합니다.
  cluster_name    = var.cluster_contract.name          # 예: "contract2whale-dev-eks"
  namespace       = local.namespace                    # 예: "monitoring"
  service_account = local.alertmanager_service_account # 예: "platform-alertmanager"
  role_arn        = aws_iam_role.alertmanager.arn      # 예: 위에서 만든 역할의 ARN

  depends_on = [aws_iam_role_policy.publish] # 예: 정책 부착 이후에 연결 (modules/operations 와 같은 순서)
}

# EC2 state-change 이벤트에는 태그 필터를 넣지 않습니다. 계정 · 리전 내 모든 EC2 가 대상입니다.
resource "aws_cloudwatch_event_rule" "ec2_state_change" {
  # 예: contract2whale-dev-ec2-state-change. EKS 태그가 아닌 계정 · 리전으로 범위를 고정합니다.
  name           = "${local.prefix}-ec2-state-change"                             # 예: "contract2whale-dev-ec2-state-change"
  description    = "EC2 instance state changes in this account and Seoul region." # 예: 규칙의 설명 문구
  event_bus_name = "default"                                                      # 예: "default" (계정 기본 이벤트 버스)
  event_pattern = jsonencode({
    source        = ["aws.ec2"]                                                                   # 예: 인스턴스가 내는 이벤트만
    "detail-type" = ["EC2 Instance State-change Notification"]                                    # 예: 상태 변화 알림만
    account       = [var.expected_account_id]                                                     # 예: ["111111111111"]
    region        = [var.region]                                                                  # 예: ["ap-northeast-2"]
    detail        = { state = ["stopping", "stopped", "shutting-down", "terminated", "running"] } # 예: 다섯 상태
  })

  depends_on = [terraform_data.contract] # 예: 소유권 검사를 통과한 뒤에 만듭니다
}

resource "aws_sns_topic_policy" "alerts" {
  arn = aws_sns_topic.alerts.arn # 예: 정책을 붙일 토픽 하나
  policy = jsonencode({
    Version = "2012-10-17" # 예: 정책 문서 형식의 버전 번호
    Statement = [
      {
        Sid       = "EventBridgePublish"                 # 예: 첫 번째 문장의 레이블
        Effect    = "Allow"                              # 예: "Allow" (허용)
        Principal = { Service = "events.amazonaws.com" } # 예: 이벤트 규칙이 서비스로서 호출합니다
        Action    = "sns:Publish"                        # 예: 게시 동작 하나만 허용합니다
        Resource  = aws_sns_topic.alerts.arn             # 예: 이 토픽 하나만
      },
      {
        Sid       = "EnvironmentCloudWatchAlarmsPublish"     # 예: 두 번째 문장의 레이블
        Effect    = "Allow"                                  # 예: "Allow" (허용)
        Principal = { Service = "cloudwatch.amazonaws.com" } # 예: 경보가 서비스로서 호출합니다
        Action    = "sns:Publish"                            # 예: 게시 동작 하나만 허용합니다
        Resource  = aws_sns_topic.alerts.arn                 # 예: 이 토픽 하나만
        Condition = {
          # 예: 서울 Dev 계정의 contract2whale-dev-* CloudWatch alarm 만 게시할 수 있습니다.
          StringEquals = { "aws:SourceAccount" = var.expected_account_id }                                                           # 예: 이 계정의 경보만
          ArnLike      = { "aws:SourceArn" = "arn:aws:cloudwatch:${var.region}:${var.expected_account_id}:alarm:${local.prefix}-*" } # 예: 이름 접두사가 맞는 경보만
        }
      }
    ]
  })
}

resource "aws_cloudwatch_event_target" "ec2_state_change" {
  # 예: 메일 본문의 detail.instance-id=i-0123456789abcdef0 로 실제 EC2 를 구별합니다.
  rule           = aws_cloudwatch_event_rule.ec2_state_change.name # 예: 위에서 만든 규칙
  event_bus_name = "default"                                       # 예: "default" (계정 기본 이벤트 버스)
  target_id      = "environment-alerts"                            # 예: 규칙 안에서 이 대상을 가리키는 이름
  arn            = aws_sns_topic.alerts.arn                        # 예: 게시할 토픽
  # input / input_path / input_transformer 를 생략해 detail.instance-id 를 포함한 원문을 전달합니다.

  depends_on = [aws_sns_topic_policy.alerts] # 예: 토픽 정책이 먼저 붙도록 순서를 고정합니다
}

terraform/environments/prod/platform/ale.terraform/environments/prod/platform/ale:
# backend.tf — platform/alerting 루트 모듈 (prod · dev 공통 코드)
# 알림 루트 모듈과 설치 검사: backend 인자는 커밋하지 않는 backend.hcl 이 제공합니다 (terraform init -backend-config=backend.hcl).
# key 는 platform/alerting/terraform.tfstate 로 실행 디렉터리 경로 규칙을 따릅니다 (원본 platform/alerting/prod/terraform.tfstate — P2; platform/operations 와 다른 key, 같은 버킷).

terraform {
  backend "s3" {}
}

# locals.tf — platform/alerting 루트 모듈 (prod · dev 공통 코드)
# 알림 루트 모듈과 설치 검사: State 에서 읽은 출력을 모듈 입력 모양으로 조립합니다. 두 값 모두 이 루트 모듈이 직접 입력받지 않습니다.

locals {
  # modules/alerting 의 cluster_contract 객체입니다. eks State 의 12개 항목 중 세 항목만 골라 계약 모양을 명시합니다.
  cluster_contract = {
    name   = data.terraform_remote_state.eks.outputs.cluster_contract.name   # 예: "contract2whale-prod-eks"
    arn    = data.terraform_remote_state.eks.outputs.cluster_contract.arn    # 예: "arn:aws:eks:ap-northeast-2:222222222222:cluster/contract2whale-prod-eks"
    region = data.terraform_remote_state.eks.outputs.cluster_contract.region # 예: "ap-northeast-2"
  }

  platform_log_group_name = data.terraform_remote_state.operations.outputs.operations_contract.platform_log_group_name # 예: "/platform/contract2whale-prod-eks/application" (운영 기반 루트 모듈과 계약 출력)
}

# main.tf — platform/alerting 루트 모듈 (prod · dev 공통 코드)
# 알림 루트 모듈과 설치 검사: 환경별 root 가 State 를 분리하고 재사용 리소스는 module 이 관리합니다. module "component" 로 변수 7개를 전달하고 환경 경계 1개를 둡니다.

module "component" {
  source = "../../../../../modules/alerting" # 예: 이 루트 모듈에서 모듈까지의 상대 경로 (다섯 단계 위가 저장소 최상위)

  expected_account_id             = var.expected_account_id             # 예: "222222222222"
  environment                     = var.environment                     # 예: "prod"
  region                          = var.region                          # 예: "ap-northeast-2"
  cluster_contract                = local.cluster_contract              # 예: eks State 출력으로 조립한 {name, arn, region}
  platform_log_group_name         = local.platform_log_group_name       # 예: platform/operations State 의 "/platform/contract2whale-prod-eks/application"
  receiver_email                  = var.receiver_email                  # 예: "ops-alerts@example.com"
  sample_delete_validation_run_id = var.sample_delete_validation_run_id # 예: null (감지를 켜지 않은 상태)

  depends_on = [terraform_data.environment_boundary] # 예: 환경 경계를 통과한 뒤에 호출합니다
}

# 이 디렉터리는 prod 만 받습니다. input 은 State 에 남는 marker 이며 AWS 자원을 만들지 않습니다.
resource "terraform_data" "environment_boundary" {
  input = var.environment # 예: "prod" (input 변경은 in-place 갱신)

  lifecycle {
    precondition {
      condition     = var.environment == "prod" # 예: "prod" 통과 / "dev" 거부 (dev 는 dev/platform/alerting 디렉터리 — production)
      error_message = "This directory accepts only the prod environment."
    }

    precondition {
      condition     = terraform.workspace == "default" # 예: workspace 로 환경을 나누지 않음 (backend key 로 구분)
      error_message = "Use default workspace and a distinct backend key."
    }
  }
}

# providers.tf — platform/alerting 루트 모듈 (prod · dev 공통 코드)
# 알림 루트 모듈과 설치 검사: AWS API 만 사용합니다. Alertmanager 자체는 observability 가 Helm 으로 설치하며 Kubernetes provider 는 두지 않습니다.
# 리전은 변수로 받고 모듈의 precondition 이 계약(cluster_contract.region)과 대조합니다.

provider "aws" {
  region              = var.region                # 예: "ap-northeast-2" (서울 리전)
  allowed_account_ids = [var.expected_account_id] # 예: ["222222222222"] (다른 계정이면 실행을 거부)

  # 지원되는 AWS 리소스에 공통 분류 태그를 전달합니다. IAM 권한이 아닙니다.
  default_tags {
    tags = {
      ManagedBy   = "Terraform"         # 예: "Terraform" (수동 생성 리소스와 구분)
      Environment = var.environment     # 예: "prod" (환경 구분)
      Component   = "platform-alerting" # 예: "platform-alerting" (이 루트 모듈이 만든 리소스에 공통으로 붙는 값)
    }
  }
}

# remote-state.tf — platform/alerting 루트 모듈 (prod · dev 공통 코드)
# 알림 루트 모듈과 설치 검사: 앞 루트 모듈 두 곳(eks · platform/operations)의 root 출력을 State 에서 직접 읽습니다 (P1). .local/alerting/prod/*.json · terraform.tfvars.json 같은 입력 파일을 만들지 않습니다.
# 읽는 쪽에는 State 객체의 s3:GetObject 권한이 필요합니다 (account-baseline 의 State 역할 key 목록과 대조: eks/terraform.tfstate · platform/operations/terraform.tfstate).
# 이 루트 적용 뒤 실제 topic_arn을 검토해 operations의 alerts_topic_arn 입력에 전달하고 새 plan을 적용합니다.

# eks-control-plane · eks-nodes 의 EKS 루트 모듈입니다. locals.tf 가 cluster_contract 12개 항목 중 name · arn · region 만 모듈 입력으로 넘깁니다.
data "terraform_remote_state" "eks" {
  backend = "s3" # 예: "s3" (앞 루트 모듈이 State 를 둔 방식)

  config = {
    bucket = var.state_bucket_name   # 예: "company-prod-tfstate-222222222222"
    key    = "eks/terraform.tfstate" # 예: eks 루트 모듈의 key (클러스터 입력과 네트워크 계약)
    region = var.region              # 예: "ap-northeast-2"
  }

  lifecycle {
    postcondition {
      condition = alltrue([
        for name in ["name", "arn", "region"] :
        contains(keys(try(self.outputs.cluster_contract, {})), name) # 예: 3개 모두 cluster_contract 에 존재
      ])
      error_message = "eks state must expose cluster_contract with name, arn and region (apply 생성 plan과 private API 검증 first)."
    }
  }
}

# 운영 기반 루트 모듈과 계약 의 운영 기반 루트 모듈입니다. 로그 그룹 이름만 읽습니다 (fluent_bit 을 끈 State 는 null 이라 거부).
data "terraform_remote_state" "operations" {
  backend = "s3" # 예: "s3"

  config = {
    bucket = var.state_bucket_name                   # 예: "company-prod-tfstate-222222222222" (같은 버킷)
    key    = "platform/operations/terraform.tfstate" # 예: platform/operations 루트 모듈의 key (운영 기반 루트 모듈과 계약)
    region = var.region                              # 예: "ap-northeast-2"
  }

  lifecycle {
    postcondition {
      condition     = try(self.outputs.operations_contract.platform_log_group_name != null, false) # 예: "/platform/contract2whale-prod-eks/application" (null 이면 거부)
      error_message = "platform/operations state must expose operations_contract.platform_log_group_name (apply 운영 기반 루트 모듈과 계약 with fluent_bit enabled first)."
    }
  }
}

# variables.tf — platform/alerting 루트 모듈 (prod · dev 공통 코드)
# 알림 루트 모듈과 설치 검사: 루트 모듈 입력 6개입니다. 모듈 입력 7개 중 cluster_contract · platform_log_group_name 은 remote-state.tf 가 eks · platform/operations State 에서 읽으므로 받지 않고(P1),
# 대신 state_bucket_name 을 받습니다. receiver_email 은 실습자가 terraform.tfvars 에서 자기 주소로 바꿉니다.

variable "expected_account_id" {
  description = "AWS account that owns the cluster and the alerting resources; 12 digits."
  type        = string # 예: string (앞자리 0 이 사라지지 않도록 문자열)
  nullable    = false

  validation {
    condition     = can(regex("^[0-9]{12}$", var.expected_account_id)) # 예: "222222222222" 통과, "123" 거부
    error_message = "expected_account_id must contain exactly 12 digits."
  }
}

# main.tf 의 environment_boundary 가 이 디렉터리에서는 "prod" 만 허용합니다. 모듈은 prod · dev 만 받습니다.
variable "environment" {
  description = "Environment name; this directory accepts prod only (dev is dev/platform/alerting, production)."
  type        = string # 예: string (환경 이름을 문자열로 받습니다)
  nullable    = false

  validation {
    condition     = contains(["prod", "dev"], var.environment) # 예: "prod" 통과, "stage" 거부
    error_message = "environment must be prod or dev."
  }
}

variable "region" {
  description = "AWS region for this root; only ap-northeast-2 is supported."
  type        = string
  default     = "ap-northeast-2" # 기본값: "ap-northeast-2"
  nullable    = false

  validation {
    condition     = var.region == "ap-northeast-2" # 예: "us-east-1" 거부
    error_message = "This root supports ap-northeast-2 only."
  }
}

# 앞 루트 모듈(eks · platform/operations)의 State 가 있는 버킷입니다. backend.hcl 의 bucket 과 같은 값입니다.
variable "state_bucket_name" {
  description = "S3 bucket holding the eks and platform/operations states read by terraform_remote_state."
  type        = string # 예: "company-prod-tfstate-222222222222" (work/lab.env 의 PROD_STATE_BUCKET)
  nullable    = false

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$", var.state_bucket_name)) # 예: S3 버킷 이름 규칙
    error_message = "state_bucket_name must be a valid S3 bucket name."
  }
}

variable "receiver_email" {
  description = "SNS 확인 이메일을 수신하고 구독을 직접 승인할 주소."
  type        = string                   # 예: string (주소를 문자열로 받습니다)
  default     = "ops-alerts@example.com" # 예: 실습자가 자기 주소로 바꾸는 자리 (terraform.tfvars)
  nullable    = false

  validation {
    condition     = can(regex("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$", var.receiver_email)) # 예: "not-an-email" 거부
    error_message = "receiver_email must be an email address without whitespace."
  }
}

variable "sample_delete_validation_run_id" {
  description = "Dev 전용 샘플 삭제 감지 요청 ID. 공유 모듈은 Prod의 비-null 입력을 거부하므로 Prod는 null을 유지한다."
  type        = string # 예: string (식별자를 문자열로 받습니다)
  default     = null   # 예: null (Prod에서 유지할 null; 감지 실습은 Dev에서 별도 승인)

  validation {
    # 예: null 통과, "verify-0123456789abcdef0123456789abcdef" 통과, "verify-all" 거부
    condition     = var.sample_delete_validation_run_id == null ? true : can(regex("^verify-[0-9a-f]{32}$", var.sample_delete_validation_run_id))
    error_message = "Use null or verify- followed by exactly 32 lowercase hex characters."
  }
}

# versions.tf — platform/alerting 루트 모듈 (prod · dev 공통 코드)
# 알림 루트 모듈과 설치 검사: Terraform 과 provider 버전을 고정합니다. backend 선언은 backend.tf 에, 모듈 버전은 modules/alerting/versions.tf 에 있습니다.

terraform {
  required_version = "= 1.16.0" # 예: "= 1.16.0" (등호로 정확한 버전 고정)

  required_providers {
    aws = {
      source  = "hashicorp/aws" # 예: "hashicorp/aws" (공식 레지스트리 경로)
      version = "= 6.62.0"      # 예: "= 6.62.0" (모듈과 같은 값)
    }
  }
}

