# variables.tf — modules/tenant-pod-identity (dev · prod 루트 모듈이 공유하는 모듈)

variable "expected_account_id" {
  description = "AWS account that owns the cluster, the secrets and the export bucket; 12 digits."
  type        = string # 예: "111111111111"
  nullable    = false

  validation {
    condition     = can(regex("^[0-9]{12}$", var.expected_account_id)) # 예: "111111111111" 통과
    error_message = "Account ID must be 12 digits."
  }
}

variable "region" {
  description = "AWS region for this module; only ap-northeast-2 is supported in this course."
  type        = string
  default     = "ap-northeast-2" # 기본값: "ap-northeast-2"
  nullable    = false

  validation {
    condition     = var.region == "ap-northeast-2" # 예: 단일 값 비교
    error_message = "This module supports ap-northeast-2 only."
  }
}

variable "environment" {
  description = "Environment name that must match the data contract: dev or prod."
  type        = string
  nullable    = false

  validation {
    condition     = contains(["dev", "prod"], var.environment) # 예: "dev" 통과 / "staging" 거부
    error_message = "environment must be dev or prod."
  }
}

# Pod Identity 신뢰 정책의 세션 태그(eks-cluster-arn)에 쓰는 값입니다 (E3).
variable "cluster_contract" {
  description = "Cluster name and ARN used for the association and the trust policy session tags."
  type = object({
    name = string # 예: "contract2whale-dev-eks"
    arn  = string # 예: "arn:aws:eks:ap-northeast-2:111111111111:cluster/contract2whale-dev-eks"
  })
  nullable = false

  validation {
    condition     = can(regex("^arn:aws:eks:[a-z0-9-]+:[0-9]{12}:cluster/", var.cluster_contract.arn)) # 예: EKS 클러스터 ARN 형식
    error_message = "cluster_contract.arn must be an EKS cluster ARN."
  }
}

variable "data_contract" {
  description = "Environment, account, cluster, namespace, service accounts, secret ARNs, media location and KMS key from the data root."
  type = object({
    environment  = string # 예: "dev"
    account_id   = string # 예: "111111111111"
    region       = string # 예: "ap-northeast-2"
    cluster_name = string # 예: "contract2whale-dev-eks"
    namespace    = string # 예: "contract2whale-demo"

    service_accounts = object({
      runtime   = string # 예: "commerce-api" (스토어프런트 commerce-web 은 AWS 를 부르지 않아 여기에 없습니다)
      operator  = string # 예: "database-operator"
      migration = string # 예: "delivery-migration"
    })

    credentials = object({
      master_secret_arn    = string           # 예: "arn:aws:secretsmanager:…:secret:rds!db-…" (운영자만 읽음)
      migration_secret_arn = string           # 예: 스키마 변경 계정 시크릿
      runtime_secret_arn   = string           # 예: 앱 실행 계정 시크릿
      app_secret_arn       = optional(string) # 예: Medusa 의 JWT_SECRET · COOKIE_SECRET 비밀 (계약에 없으면 null — 권한에서도 빠집니다)
    })

    # 상품 이미지 같은 미디어 파일이 올라가는 곳입니다. 애플리케이션 데이터 내보내기 버킷을 그대로 쓰고 이름만 계약에 남았습니다.
    export = object({
      bucket_arn = string # 예: "arn:aws:s3:::cp-dev-app-exports-111111111111-ap-northeast-2" (미디어 버킷)
      prefix     = string # 예: "media/dev/commerce-api/" (Medusa file-s3 의 S3_PREFIX · commerce-api 만 씁니다)
    })

    kms_key_arn = string # 예: "arn:aws:kms:ap-northeast-2:111111111111:key/…"
  })
  nullable = false

  validation {
    condition = alltrue([
      for arn in concat([var.data_contract.credentials.master_secret_arn, var.data_contract.credentials.migration_secret_arn, var.data_contract.credentials.runtime_secret_arn], compact([var.data_contract.credentials.app_secret_arn])) :
      can(regex("^arn:aws:secretsmanager:", arn)) # 예: 주어진 값 모두 Secrets Manager ARN
    ])
    error_message = "credentials must be Secrets Manager ARNs (the data root outputs them)."
  }

  validation {
    condition     = endswith(var.data_contract.export.prefix, "/") && !startswith(var.data_contract.export.prefix, "/") # 예: "media/dev/commerce-api/" 통과 / "/media/dev" 거부
    error_message = "export.prefix must be a relative key prefix ending with a slash."
  }
}

# 배포 플랫폼 delivery 모듈이 만든 migration Role 입니다. 이 모듈은 Role 을 만들지 않고 데이터 권한(인라인 정책)과 Pod Identity 연결만 더합니다.
variable "migration_role_arn" {
  description = "ARN of the delivery migration role created in 배포 플랫폼; this module attaches the migration secret policy and the association to it."
  type        = string # 예: "arn:aws:iam::111111111111:role/platform/contract2whale-dev-eks-delivery-migration"
  nullable    = false

  validation {
    condition     = can(regex("^arn:aws:iam::[0-9]{12}:role/", var.migration_role_arn)) # 예: IAM Role ARN 형식
    error_message = "migration_role_arn must be an IAM role ARN."
  }
}

# 운영 도구 운영 기반의 External Secrets controller Role 입니다. 앱 비밀 읽기 Role(secrets_reader)이 이 Role 만 신뢰합니다 (assume-role chaining).
variable "external_secrets_role_arn" {
  description = "ARN of the cluster-wide External Secrets controller role (operations root output external_secrets_role_arn); the only principal the application secrets reader role trusts."
  type        = string # 예: "arn:aws:iam::111111111111:role/contract2whale-dev-eks-external-secrets"
  nullable    = false

  validation {
    condition     = can(regex("^arn:aws:iam::[0-9]{12}:role/", var.external_secrets_role_arn)) # 예: IAM Role ARN 형식
    error_message = "external_secrets_role_arn must be an IAM role ARN."
  }
}

terraform/environments/prod/identity.modules/tenant-pod-identity/main.tf:
# main.tf — modules/tenant-pod-identity (dev · prod 루트 모듈이 공유하는 모듈)
# 세 신원의 경계: runtime(commerce-api) 은 실행 계정 · 앱 비밀과 자기 미디어 접두사, operator 는 관리 시크릿 · 앱 비밀 읽기와 앱 자격 증명 발행, migration 은 스키마 변경 계정 · 앱 비밀입니다.
# 앱 비밀 읽기 Role(secrets_reader)은 Pod 신원이 아니라 External Secrets controller 가 SecretStore 로 맡는 읽기 전용 Role 입니다 (assume-role chaining).
# 스토어프런트(commerce-web) 는 AWS API 를 부르지 않습니다. 그래서 Role 도 Pod Identity 연결도 만들지 않고, 이 모듈의 Pod 신원은 셋 그대로입니다.
# IAM 이 열어 주는 것은 AWS API 뿐입니다. 데이터베이스 안의 SQL 권한(GRANT)은 데이터베이스 초기화 Job 이 따로 만듭니다.

locals {
  name_prefix       = "${var.cluster_contract.name}-app"                                                # 예: "contract2whale-dev-eks-app" (이 모듈이 만드는 Role 이름 접두사)
  migration_role_id = regex("^arn:aws:iam::[0-9]{12}:role/(?:.*/)?([^/]+)$", var.migration_role_arn)[0] # 예: "contract2whale-dev-eks-delivery-migration" (경로가 있어도 마지막 이름만)
  export_resource   = "${var.data_contract.export.bucket_arn}/${var.data_contract.export.prefix}*"      # 예: "arn:aws:s3:::cp-dev-app-exports-…/media/dev/commerce-api/*" (미디어 객체가 올라가는 곳)

  # 앱 비밀(Medusa 의 JWT_SECRET · COOKIE_SECRET)은 계약에 있을 때만 권한에 들어갑니다. 없으면 목록에서 빠집니다 (compact).
  runtime_secrets   = compact([var.data_contract.credentials.runtime_secret_arn, var.data_contract.credentials.app_secret_arn])                                                     # 예: 실행 계정 비밀 + 앱 비밀
  migration_secrets = compact([var.data_contract.credentials.migration_secret_arn, var.data_contract.credentials.app_secret_arn])                                                   # 예: 스키마 변경 계정 비밀 + 앱 비밀 (db:migrate 도 설정을 읽습니다)
  reader_secrets    = compact([var.data_contract.credentials.runtime_secret_arn, var.data_contract.credentials.migration_secret_arn, var.data_contract.credentials.app_secret_arn]) # 예: ExternalSecret 두 개(commerce-api-runtime · commerce-api-migration)가 읽는 세 비밀
  contract_arns     = concat([var.data_contract.credentials.master_secret_arn, var.data_contract.credentials.migration_secret_arn, var.data_contract.credentials.runtime_secret_arn, var.data_contract.kms_key_arn], compact([var.data_contract.credentials.app_secret_arn]))

  # Pod Identity 는 세션 태그 세 개로 "이 클러스터의 이 namespace 의 이 ServiceAccount" 를 증명합니다 (E3).
  pod_identity_trust = {
    for key, service_account in var.data_contract.service_accounts : key => jsonencode({
      Version = "2012-10-17" # 예: "2012-10-17" (정책 문법 버전, 날짜가 아닙니다)
      Statement = [{
        Sid       = "PodIdentityAssumes${title(key)}"      # 예: "PodIdentityAssumesRuntime" (사람이 읽는 Statement 식별자)
        Effect    = "Allow"                                # 예: "Allow" (조건에 맞는 요청을 허용합니다)
        Principal = { Service = "pods.eks.amazonaws.com" } # 예: EKS Pod Identity 에이전트만
        Action    = ["sts:AssumeRole", "sts:TagSession"]   # 예: Pod Identity 는 두 동작이 모두 필요
        Condition = {
          StringEquals = {
            "aws:RequestTag/kubernetes-namespace"       = var.data_contract.namespace # 예: "contract2whale-demo"
            "aws:RequestTag/kubernetes-service-account" = service_account             # 예: "commerce-api" · "database-operator" · "delivery-migration"
            "aws:RequestTag/eks-cluster-arn"            = var.cluster_contract.arn    # 예: 이 클러스터의 Pod 만
          }
        }
      }]
    })
  }
}

resource "terraform_data" "guard" {
  input = "${var.environment}:${var.data_contract.namespace}" # 예: "dev:contract2whale-demo" (State 에 남는 표식)

  lifecycle {
    precondition {
      condition     = var.data_contract.environment == var.environment && var.data_contract.account_id == var.expected_account_id && var.data_contract.region == var.region # 예: 데이터 계약과 이 루트 모듈의 환경 · 계정 · 리전이 같아야 함
      error_message = "data_contract must describe the same environment, account and region as this root (an environment mix-up)."
    }

    precondition {
      condition     = var.data_contract.cluster_name == var.cluster_contract.name # 예: 다른 클러스터의 계약을 쓰지 않음
      error_message = "data_contract.cluster_name must equal cluster_contract.name."
    }

    precondition {
      condition = alltrue([
        for arn in local.contract_arns :
        split(":", arn)[4] == var.expected_account_id && split(":", arn)[3] == var.region # 예: 시크릿 · 키가 같은 계정 · 같은 리전에 있어야 함 (이름만 Dev 인 Prod ARN 거부)
      ])
      error_message = "Secrets and the KMS key must live in expected_account_id and region (name says dev, ARN says prod is the mistake this catches)."
    }

    precondition {
      condition     = startswith(var.data_contract.export.prefix, "media/${var.environment}/") # 예: "media/dev/commerce-api/" 통과 / "media/prod/commerce-api/" 거부
      error_message = "export.prefix must start with media/<environment>/ (the media prefix of the data contract)."
    }

    precondition {
      condition     = split(":", var.migration_role_arn)[4] == var.expected_account_id && endswith(local.migration_role_id, "-delivery-migration") # 예: 같은 계정의 배포 플랫폼 migration Role 인지
      error_message = "migration_role_arn must be the delivery migration role of this account (배포 플랫폼 execution contract)."
    }
  }
}

# runtime: 앱 Pod(commerce-api) 의 신원입니다. 실행 계정과 선택적 앱 비밀을 읽고, 자기 미디어 접두사 아래의 객체만 다룹니다.
resource "aws_iam_role" "runtime" {
  name               = "${local.name_prefix}-runtime"      # 예: "contract2whale-dev-eks-app-runtime"
  path               = "/platform/"                        # 예: "/platform/" (배포 플랫폼 Role 과 같은 경로 규칙)
  assume_role_policy = local.pod_identity_trust["runtime"] # 예: namespace/ServiceAccount/클러스터 조건이 붙은 신뢰 정책

  depends_on = [terraform_data.guard] # 예: 계약 검사를 통과한 뒤에 만듭니다
}

resource "aws_iam_role_policy" "runtime" {
  name = "application-data" # 예: Role 안에 붙는 인라인 정책 이름
  role = aws_iam_role.runtime.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "RuntimeSecret" # 예: 자기 실행 계정 시크릿과 앱 비밀만 읽기 (관리자 · 스키마 변경 시크릿은 없음)
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue", "secretsmanager:DescribeSecret"]
        Resource = local.runtime_secrets
      },
      {
        Sid      = "OwnExportObjects" # 예: 자기 접두사 아래의 객체만 읽고 쓰고 지움 (관리자 화면의 미디어 업로드 · 삭제)
        Effect   = "Allow"
        Action   = ["s3:PutObject", "s3:GetObject", "s3:DeleteObject", "s3:AbortMultipartUpload"]
        Resource = [local.export_resource]
      },
      {
        Sid      = "ListOwnExportPrefix" # 예: 목록 조회도 접두사로 제한 (버킷 전체 목록 금지)
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = [var.data_contract.export.bucket_arn]
        Condition = {
          StringLike = { "s3:prefix" = ["${var.data_contract.export.prefix}*"] }
        }
      },
      {
        Sid      = "ExportKeyViaS3" # 예: 키 사용은 S3 를 거치는 호출로만 (직접 복호화 금지)
        Effect   = "Allow"
        Action   = ["kms:GenerateDataKey", "kms:Decrypt", "kms:DescribeKey"]
        Resource = [var.data_contract.kms_key_arn]
        Condition = {
          StringEquals = { "kms:ViaService" = "s3.${var.region}.amazonaws.com" }
        }
      },
      {
        Sid      = "RuntimeSecretKey" # 예: 시크릿 복호화는 Secrets Manager 를 거치는 호출로만
        Effect   = "Allow"
        Action   = ["kms:Decrypt"]
        Resource = [var.data_contract.kms_key_arn]
        Condition = {
          StringEquals = { "kms:ViaService" = "secretsmanager.${var.region}.amazonaws.com" }
        }
      },
    ]
  })
}

# operator: 초기화 · 진단 Job 의 신원입니다. 관리 시크릿과 앱 비밀을 읽고, 후보 비밀번호를 만들어 앱 시크릿 두 개를 발행합니다. 내보내기 버킷 권한은 없습니다.
resource "aws_iam_role" "operator" {
  name               = "${local.name_prefix}-database-operator" # 예: "contract2whale-dev-eks-app-database-operator"
  path               = "/platform/"                             # 예: "/platform/"
  assume_role_policy = local.pod_identity_trust["operator"]     # 예: database-operator ServiceAccount 만

  depends_on = [terraform_data.guard] # 예: 계약 검사를 통과한 뒤에 만듭니다
}

resource "aws_iam_role_policy" "operator" {
  name = "database-bootstrap" # 예: Role 안에 붙는 인라인 정책 이름
  role = aws_iam_role.operator.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat([
      {
        Sid      = "MasterSecret" # 예: RDS 가 관리하는 관리자 시크릿 읽기 (앱 · migration 에는 없는 권한)
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue", "secretsmanager:DescribeSecret"]
        Resource = [var.data_contract.credentials.master_secret_arn]
      },
      {
        Sid    = "PublishApplicationCredentials" # 예: 앱 시크릿 두 개에 후보 값을 올리고 현재 버전으로 승격
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret",
          "secretsmanager:PutSecretValue",
          "secretsmanager:UpdateSecretVersionStage",
          "secretsmanager:ListSecretVersionIds",
        ]
        Resource = [var.data_contract.credentials.migration_secret_arn, var.data_contract.credentials.runtime_secret_arn]
      },
      {
        Sid      = "GeneratePasswords" # 예: 후보 비밀번호 생성 (리소스를 지정할 수 없는 동작이라 "*")
        Effect   = "Allow"
        Action   = ["secretsmanager:GetRandomPassword"]
        Resource = ["*"]
      },
      {
        Sid      = "OperatorSecretKey" # 예: 시크릿 암복호화는 Secrets Manager 를 거치는 호출로만
        Effect   = "Allow"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
        Resource = [var.data_contract.kms_key_arn]
        Condition = {
          StringEquals = { "kms:ViaService" = "secretsmanager.${var.region}.amazonaws.com" }
        }
      },
      ], var.data_contract.credentials.app_secret_arn == null ? [] : [
      {
        Sid      = "ReadApplicationSecret" # 예: 앱 비밀(jwt_secret · cookie_secret)을 읽어 실행 계정 비밀에 옮겨 적음 (쓰기 없음)
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue", "secretsmanager:DescribeSecret"]
        Resource = [var.data_contract.credentials.app_secret_arn]
      },
    ])
  })
}

# migration: 배포 플랫폼이 만든 Role 에 데이터 권한만 더합니다. Role · 신뢰 정책은 배포 플랫폼 소유이고 여기서 다시 만들지 않습니다.
# Argo CD PreSync Job 이 앱 이미지로 medusa db:migrate 를 돌리므로, 이 신원이 읽는 것은 스키마 변경 계정 비밀과 앱 비밀 둘뿐입니다.
resource "aws_iam_role_policy" "migration" {
  name = "migration-secret"      # 예: Role 안에 붙는 인라인 정책 이름 (배포 플랫폼 의 정책과 이름이 겹치지 않음)
  role = local.migration_role_id # 예: "contract2whale-dev-eks-delivery-migration" (ARN 에서 뽑은 Role 이름)

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "MigrationSecret" # 예: 스키마 변경 계정 시크릿과 앱 비밀만 읽기 (medusa db:migrate 도 설정을 읽어 JWT_SECRET · COOKIE_SECRET 을 요구)
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue", "secretsmanager:DescribeSecret"]
        Resource = local.migration_secrets
      },
      {
        Sid      = "MigrationSecretKey" # 예: 시크릿 복호화는 Secrets Manager 를 거치는 호출로만
        Effect   = "Allow"
        Action   = ["kms:Decrypt"]
        Resource = [var.data_contract.kms_key_arn]
        Condition = {
          StringEquals = { "kms:ViaService" = "secretsmanager.${var.region}.amazonaws.com" }
        }
      },
    ]
  })

  depends_on = [terraform_data.guard] # 예: migration Role 이 이 계정의 배포 플랫폼 Role 인지 확인한 뒤에
}

# 앱 비밀 읽기: 운영 도구 External Secrets controller 가 SecretStore(spec.provider.aws.role)로 맡는 읽기 전용 Role 입니다 (assume-role chaining).
# ExternalSecret 두 개(commerce-api-runtime · commerce-api-migration)가 같은 SecretStore 를 쓰므로 실행 계정 · 스키마 변경 계정 · 앱 비밀을 읽습니다. 관리자 시크릿은 없습니다.
resource "aws_iam_role" "secrets_reader" {
  name = "${var.cluster_contract.name}-data-app-secrets" # 예: "contract2whale-dev-eks-data-app-secrets" (gitops overlay 의 SecretStore role 과 같은 이름)
  path = "/platform/"                                    # 예: "/platform/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid       = "ExternalSecretsControllerChaining"
      Effect    = "Allow"
      Principal = { AWS = var.external_secrets_role_arn } # 예: 운영 도구 controller Role (platform/operations 루트 모듈 출력 external_secrets_role_arn)
      Action    = ["sts:AssumeRole", "sts:TagSession"]    # 예: 역할 사용 + 세션 태그 전달
      Condition = {
        StringEquals = {
          "aws:PrincipalTag/kubernetes-namespace"       = "external-secrets" # 예: controller 가 도는 네임스페이스 (운영 도구)
          "aws:PrincipalTag/kubernetes-service-account" = "external-secrets" # 예: controller ServiceAccount (운영 도구 values serviceAccount.name)
        }
      }
    }]
  })

  depends_on = [terraform_data.guard] # 예: 계약 검사를 통과한 뒤에 만듭니다
}

resource "aws_iam_role_policy" "secrets_reader" {
  name = "read-application-secrets"     # 예: Role 안에 붙는 인라인 정책 이름
  role = aws_iam_role.secrets_reader.id # 예: 위 Role

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ReadApplicationSecrets" # 예: 실행 계정 · 스키마 변경 계정 · 앱 비밀 읽기 2동작 (관리자 시크릿 · 쓰기 없음)
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue", "secretsmanager:DescribeSecret"]
        Resource = local.reader_secrets
      },
      {
        Sid      = "ReaderSecretKey" # 예: 시크릿 복호화는 Secrets Manager 를 거치는 호출로만
        Effect   = "Allow"
        Action   = ["kms:Decrypt"]
        Resource = [var.data_contract.kms_key_arn]
        Condition = {
          StringEquals = { "kms:ViaService" = "secretsmanager.${var.region}.amazonaws.com" }
        }
      },
    ]
  })
}

resource "aws_eks_pod_identity_association" "runtime" {
  cluster_name    = var.cluster_contract.name                  # 예: "contract2whale-dev-eks"
  namespace       = var.data_contract.namespace                # 예: "contract2whale-demo"
  service_account = var.data_contract.service_accounts.runtime # 예: "commerce-api"
  role_arn        = aws_iam_role.runtime.arn                   # 예: "arn:aws:iam::…:role/platform/contract2whale-dev-eks-app-runtime"

  depends_on = [aws_iam_role_policy.runtime] # 예: 권한이 붙은 뒤에 연결을 만듭니다
}

resource "aws_eks_pod_identity_association" "operator" {
  cluster_name    = var.cluster_contract.name                   # 예: "contract2whale-dev-eks"
  namespace       = var.data_contract.namespace                 # 예: "contract2whale-demo"
  service_account = var.data_contract.service_accounts.operator # 예: "database-operator"
  role_arn        = aws_iam_role.operator.arn                   # 예: "arn:aws:iam::…:role/platform/contract2whale-dev-eks-app-database-operator"

  depends_on = [aws_iam_role_policy.operator] # 예: 권한이 붙은 뒤에 연결을 만듭니다
}

# 배포 플랫폼 는 migration Role 과 신뢰 정책만 만들고 연결은 만들지 않습니다 (배포 플랫폼 사양의 인계 항목). 그래서 이 연결의 소유자는 애플리케이션 데이터 입니다.
resource "aws_eks_pod_identity_association" "migration" {
  cluster_name    = var.cluster_contract.name                    # 예: "contract2whale-dev-eks"
  namespace       = var.data_contract.namespace                  # 예: "contract2whale-demo"
  service_account = var.data_contract.service_accounts.migration # 예: "delivery-migration" (gitops/platform/tenant-baseline/overlays/dev/serviceaccount-delivery-migration.yaml)
  role_arn        = var.migration_role_arn                       # 예: 배포 플랫폼이 만든 Role

  depends_on = [aws_iam_role_policy.migration] # 예: 데이터 권한이 붙은 뒤에 연결을 만듭니다
}

terraform/environments/prod/identity.modules/tenant-pod-identity/outputs.tf:
# outputs.tf — modules/tenant-pod-identity (dev · prod 루트 모듈이 공유하는 모듈)

output "identity_contract" {
  description = "Environment, cluster, namespace, the three identities (role ARN, service account, association ID) and the secrets reader role."
  value = {
    environment  = var.environment             # 예: "dev"
    cluster_name = var.cluster_contract.name   # 예: "contract2whale-dev-eks"
    namespace    = var.data_contract.namespace # 예: "contract2whale-demo"

    runtime = {
      role_arn        = aws_iam_role.runtime.arn                                # 예: "arn:aws:iam::…:role/platform/contract2whale-dev-eks-app-runtime"
      service_account = var.data_contract.service_accounts.runtime              # 예: "commerce-api"
      association_id  = aws_eks_pod_identity_association.runtime.association_id # 예: "a-abcdefghij1234567"
    }

    operator = {
      role_arn        = aws_iam_role.operator.arn                                # 예: "arn:aws:iam::…:role/platform/contract2whale-dev-eks-app-database-operator"
      service_account = var.data_contract.service_accounts.operator              # 예: "database-operator"
      association_id  = aws_eks_pod_identity_association.operator.association_id # 예: "a-bcdefghij12345678"
    }

    migration = {
      role_arn        = var.migration_role_arn                                    # 예: 배포 플랫폼이 만든 Role (이 모듈은 정책 · 연결만 더함)
      service_account = var.data_contract.service_accounts.migration              # 예: "delivery-migration"
      association_id  = aws_eks_pod_identity_association.migration.association_id # 예: "a-cdefghij123456789"
    }

    secrets_reader = {
      role_arn = aws_iam_role.secrets_reader.arn # 예: "arn:aws:iam::…:role/platform/contract2whale-dev-eks-data-app-secrets" (SecretStore spec.provider.aws.role)
    }
  }
}

terraform/environments/prod/identity.terraform/environments/prod/identity/bac:
# backend.tf — identity 루트 모듈 (prod · dev 공통 코드)
# 데이터 루트 모듈과 PostgreSQL 버전 고정: backend 인자는 커밋하지 않는 backend.hcl 이 제공합니다 (terraform init -backend-config=backend.hcl).
# key 는 identity/terraform.tfstate 로 실행 디렉터리 경로 규칙을 따릅니다 (P2). data 루트 모듈과 State 를 나누면 데이터 자원을 건드리지 않고 권한만 다시 적용할 수 있습니다.

terraform {
  backend "s3" {}
}

terraform/environments/prod/identity.terraform/environments/prod/identity/loc:
# locals.tf — identity 루트 모듈 (prod · dev 공통 코드)
# 데이터 루트 모듈과 PostgreSQL 버전 고정: State 에서 읽은 출력을 모듈 입력 두 객체의 모양으로 추립니다. data_contract 는 12키지만 이 모듈이 쓰는 9키만 넘깁니다.

locals {
  # modules/tenant-pod-identity 의 cluster_contract 객체 (eks State 의 cluster_contract 12항목 중 2개).
  cluster_contract = {
    name = data.terraform_remote_state.eks.outputs.cluster_contract.name # 예: "contract2whale-prod-eks"
    arn  = data.terraform_remote_state.eks.outputs.cluster_contract.arn  # 예: "arn:aws:eks:ap-northeast-2:222222222222:cluster/contract2whale-prod-eks"
  }

  contract = data.terraform_remote_state.data.outputs.data_contract # 예: 데이터베이스 · KMS 키 · 시크릿 · 미디어 버킷 의 12키 계약

  # 앱 비밀 읽기 Role 이 신뢰할 operations External Secrets controller Role 입니다.
  external_secrets_role_arn = data.terraform_remote_state.operations.outputs.external_secrets_role_arn # 예: "arn:aws:iam::222222222222:role/contract2whale-prod-eks-external-secrets"

  # 모듈이 요구하는 모양으로 추린 데이터 계약입니다 (Role 이름 · 태그처럼 쓰지 않는 값은 넘기지 않습니다).
  data_contract = {
    environment  = local.contract.environment  # 예: "prod"
    account_id   = local.contract.account_id   # 예: "222222222222"
    region       = local.contract.region       # 예: "ap-northeast-2"
    cluster_name = local.contract.cluster_name # 예: "contract2whale-prod-eks"
    namespace    = local.contract.namespace    # 예: "contract2whale-demo"

    service_accounts = {
      runtime   = local.contract.service_accounts.runtime   # 예: "commerce-api" (스토어프런트 commerce-web 은 AWS 를 부르지 않아 신원이 없습니다)
      operator  = local.contract.service_accounts.operator  # 예: "database-operator"
      migration = local.contract.service_accounts.migration # 예: "delivery-migration"
    }

    credentials = {
      master_secret_arn    = local.contract.credentials.master_secret_arn    # 예: RDS 관리 Secret
      migration_secret_arn = local.contract.credentials.migration_secret_arn # 예: 스키마 변경 계정 시크릿
      runtime_secret_arn   = local.contract.credentials.runtime_secret_arn   # 예: 앱 실행 계정 시크릿
      app_secret_arn       = local.contract.credentials.app_secret_arn       # 예: Medusa JWT_SECRET · COOKIE_SECRET 비밀 (runtime · migration 이 함께 읽음)
    }

    export = {
      bucket_arn = local.contract.export.bucket_arn # 예: "arn:aws:s3:::cp-prod-app-exports-…" (이름은 내보내기 그대로, 쓰임은 미디어)
      prefix     = local.contract.export.prefix     # 예: "media/prod/commerce-api/" (Medusa file-s3 의 S3_PREFIX)
    }

    kms_key_arn = local.contract.kms_key_arn # 예: "arn:aws:kms:…:key/…"
  }
}

terraform/environments/prod/identity.terraform/environments/prod/identity/mai:
# main.tf — identity 루트 모듈 (prod · dev 공통 코드)
# 데이터 루트 모듈과 PostgreSQL 버전 고정: module "component" 로 변수 7개를 전달하고 환경 경계 1개를 둡니다. 모듈이 계약 검사 1 · Role 3 · 인라인 정책 4 · Pod Identity 연결 3 = 11 리소스를 만들고, 환경 경계까지 더해 이 루트 모듈의 적용은 12 리소스입니다.
# 데이터 자원(130)과 State 를 나눠 두었기 때문에 권한만 고쳐 다시 적용해도 데이터베이스 plan이 나오지 않습니다.

module "component" {
  source = "../../../../modules/tenant-pod-identity" # 예: 이 루트 모듈에서 모듈까지의 상대 경로

  expected_account_id = var.expected_account_id         # 예: "222222222222"
  region              = var.region                      # 예: "ap-northeast-2"
  environment         = var.environment                 # 예: "prod"
  cluster_contract    = local.cluster_contract          # 예: eks State 의 이름 · ARN
  data_contract       = local.data_contract             # 예: data State 의 계약에서 추린 9키
  migration_role_arn  = data.aws_iam_role.migration.arn # 예: 이름으로 조회한 delivery Role 의 ARN

  external_secrets_role_arn = local.external_secrets_role_arn # 예: platform/operations State 의 ESO controller Role (앱 비밀 읽기 Role 의 신뢰 주체)
}

# 이 디렉터리는 prod 만 받습니다. input 은 State 에 남는 marker 이며 AWS 자원을 만들지 않습니다.
resource "terraform_data" "environment_boundary" {
  input = var.environment # 예: "prod"

  lifecycle {
    precondition {
      condition     = var.environment == "prod" # 예: "prod" 통과 / "dev" 거부 (dev 는 dev/identity 디렉터리)
      error_message = "This directory accepts only the prod environment."
    }

    precondition {
      condition     = terraform.workspace == "default" # 예: workspace 로 환경을 나누지 않음
      error_message = "Use default workspace and a distinct backend key."
    }
  }
}

terraform/environments/prod/identity.terraform/environments/prod/identity/out:
# outputs.tf — identity 루트 모듈 (dev · prod 공통 코드)

output "identity_contract" {
  description = "Environment, cluster, namespace, the three identities (role ARN, service account, association ID) and the secrets reader role."
  value       = module.component.identity_contract # 예: 7개 키를 담은 object
}

output "operator_image" {
  description = "Noncredential immutable operator image reference from the data contract and verified publication digest."
  value       = var.operator_image_digest == null ? null : "${data.terraform_remote_state.data.outputs.data_contract.operator.repository_url}@${var.operator_image_digest}"
}

terraform/environments/prod/identity.terraform/environments/prod/identity/pro:
# providers.tf — identity 루트 모듈 (prod · dev 공통 코드)
# 데이터 루트 모듈과 PostgreSQL 버전 고정: AWS API 만 사용합니다 (ServiceAccount는 승인된 tenant-baseline source를 Argo가 만듭니다). 연결은 클러스터 API 가 아니라 EKS API 로 만들어지므로 kubeconfig 가 필요 없습니다.

provider "aws" {
  region              = var.region                # 예: "ap-northeast-2" (서울 리전)
  allowed_account_ids = [var.expected_account_id] # 예: ["222222222222"] (다른 계정이면 실행을 거부)

  default_tags {
    tags = {
      ManagedBy   = "Terraform"     # 예: "Terraform"
      Environment = var.environment # 예: "prod"
      Component   = "identity"      # 예: "identity" (이 루트 모듈이 만든 Role 에 붙는 값)
    }
  }
}

terraform/environments/prod/identity.terraform/environments/prod/identity/rem:
# remote-state.tf — identity 루트 모듈 (prod · dev 공통 코드)
# 데이터 루트 모듈과 PostgreSQL 버전 고정: 앞 루트 모듈 세 곳(data · eks · platform/operations)의 root 출력을 State 에서 읽고, delivery 가 만든 migration Role 은 이름으로 IAM 을 조회합니다 (P1 · P3).
# 배포 전달 State 는 여기서 읽지 않습니다 — migration Role 은 루트 모듈과 적용 의 적용에서 이미 만들어졌으므로 이름으로만 조회합니다.

# 데이터 루트 모듈과 PostgreSQL 버전 고정 의 데이터 루트 모듈입니다. 시크릿 ARN · 내보내기 위치 · 키 · ServiceAccount 이름이 모두 여기서 옵니다.
data "terraform_remote_state" "data" {
  backend = "s3" # 예: "s3"

  config = {
    bucket = var.state_bucket_name    # 예: "company-prod-tfstate-222222222222"
    key    = "data/terraform.tfstate" # 예: data 루트 모듈의 key (데이터 루트 모듈과 PostgreSQL 버전 고정)
    region = var.region               # 예: "ap-northeast-2"
  }

  lifecycle {
    postcondition {
      condition = alltrue([
        for name in ["environment", "account_id", "region", "cluster_name", "namespace", "service_accounts", "credentials", "export", "kms_key_arn"] :
        contains(keys(try(self.outputs.data_contract, {})), name) # 예: 9개 모두 data_contract 에 존재
      ])
      error_message = "data state must expose data_contract with the namespace, service accounts, credentials, export and KMS key (apply prod/data first)."
    }
  }
}

# eks-control-plane 의 EKS 루트 모듈입니다. Pod Identity 신뢰 정책의 세션 태그에 쓸 클러스터 ARN 하나를 읽습니다.
data "terraform_remote_state" "eks" {
  backend = "s3" # 예: "s3"

  config = {
    bucket = var.state_bucket_name   # 예: 같은 버킷
    key    = "eks/terraform.tfstate" # 예: eks 루트 모듈의 key (클러스터 입력과 네트워크 계약)
    region = var.region              # 예: "ap-northeast-2"
  }

  lifecycle {
    postcondition {
      condition     = can(regex("^arn:aws:eks:", try(self.outputs.cluster_contract.arn, ""))) && try(self.outputs.cluster_contract.name, "") != "" # 예: 클러스터 ARN · 이름
      error_message = "eks state must expose cluster_contract with name and arn (apply 생성 plan과 private API 검증 first)."
    }
  }
}

# operations 의 운영 기반 루트 모듈입니다. 클러스터 전체 External Secrets controller 의 Role ARN 을 읽어 앱 비밀 읽기 Role 이 신뢰할 주체로 넣습니다 (assume-role chaining).
data "terraform_remote_state" "operations" {
  backend = "s3" # 예: "s3"

  config = {
    bucket = var.state_bucket_name                   # 예: 같은 버킷
    key    = "platform/operations/terraform.tfstate" # 예: operations 루트 모듈의 key (운영 기반 루트 모듈과 계약)
    region = var.region                              # 예: "ap-northeast-2"
  }

  lifecycle {
    postcondition {
      condition     = can(regex("^arn:aws:iam::[0-9]{12}:role/[A-Za-z0-9_+=,.@/-]+$", try(self.outputs.external_secrets_role_arn, ""))) # 예: IAM Role ARN 형식
      error_message = "operations state must expose external_secrets_role_arn (apply operations with external_secrets enabled first)."
    }
  }
}

# 배포 모듈이 만든 migration Role 입니다. ARN 을 State 에서 받지 않고 이름 규약(<cluster>-delivery-migration)으로 조회해 실제 존재까지 확인합니다.
data "aws_iam_role" "migration" {
  name = "${data.terraform_remote_state.eks.outputs.cluster_contract.name}-delivery-migration" # 예: "contract2whale-prod-eks-delivery-migration"

  lifecycle {
    postcondition {
      condition     = self.path == "/platform/" && strcontains(self.assume_role_policy, "pods.eks.amazonaws.com") # 예: delivery 가 만든 Pod Identity 전용 Role 인지 (provider가 반환한 정책 문서에서 경로·주체를 검사하며 전체 신뢰 조건은 기존 delivery source와 별도로 대조합니다)
      error_message = "The delivery migration role must be the delivery role under /platform/ that trusts pods.eks.amazonaws.com (apply prod/delivery first — 루트 모듈과 적용)."
    }
  }
}

terraform/environments/prod/identity.terraform/environments/prod/identity/var:
# variables.tf — identity 루트 모듈 (dev · prod 공통 코드)

variable "expected_account_id" {
  description = "AWS account that owns the cluster, the roles and the data resources; 12 digits."
  type        = string # 예: "222222222222"
  nullable    = false

  validation {
    condition     = can(regex("^[0-9]{12}$", var.expected_account_id)) # 예: "222222222222" 통과
    error_message = "Account ID must be 12 digits."
  }
}

variable "region" {
  description = "AWS region for this root; only ap-northeast-2 is supported."
  type        = string
  default     = "ap-northeast-2" # 기본값: "ap-northeast-2"
  nullable    = false

  validation {
    condition     = var.region == "ap-northeast-2" # 예: 단일 값 비교
    error_message = "This root supports ap-northeast-2 only."
  }
}

# main.tf 의 environment_boundary 가 이 디렉터리에서는 "prod" 만 허용합니다 (dev는 dev/identity).
variable "environment" {
  description = "Explicit environment name: dev or prod (must match the data contract)."
  type        = string
  nullable    = false

  validation {
    condition     = contains(["prod", "dev"], var.environment) # 예: "prod" 통과 / "staging" 거부
    error_message = "environment must be dev or prod."
  }
}

# 앞 루트 모듈(data · eks)의 State 가 있는 버킷입니다. backend.hcl 의 bucket 과 같은 값입니다.
variable "state_bucket_name" {
  description = "S3 bucket holding the data and eks states read by terraform_remote_state."
  type        = string # 예: "company-prod-tfstate-222222222222" (work/lab.env 의 PROD_STATE_BUCKET)
  nullable    = false

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$", var.state_bucket_name)) # 예: S3 버킷 이름 규칙
    error_message = "state_bucket_name must be a valid S3 bucket name."
  }
}

variable "operator_image_digest" {
  description = "Published operator ECR image digest, reviewed after the image build; never a mutable tag."
  type        = string
  default     = null
  nullable    = true
  validation {
    condition     = var.operator_image_digest == null ? true : can(regex("^sha256:[0-9a-f]{64}$", var.operator_image_digest))
    error_message = "operator_image_digest must be a complete immutable ECR sha256 digest or null before image publication."
  }
}

terraform/environments/prod/identity.terraform/environments/prod/identity/ver:
# versions.tf — identity 루트 모듈 (prod · dev 공통 코드)
# 데이터 루트 모듈과 PostgreSQL 버전 고정: Terraform 과 provider 버전을 고정합니다. backend 선언은 backend.tf 에, 모듈 버전은 modules/tenant-pod-identity/versions.tf 에 있습니다.

terraform {
  required_version = "= 1.16.0" # 예: "= 1.16.0" (등호로 정확한 버전 고정)

  required_providers {
    aws = {
      source  = "hashicorp/aws" # 예: "hashicorp/aws" (공식 레지스트리 경로)
      version = "= 6.62.0"      # 예: "= 6.62.0" (모듈과 같은 값)
    }
  }
}

terraform/environments/prod/platform/edg.modules/edge/versions.tf:
# versions.tf — modules/edge (dev · prod 루트 모듈이 공유하는 모듈)
# Prod 공개 Edge 모듈: CloudFront · WAF · viewer 인증서는 Gateway 와 별도 State 를 씁니다. Gateway 와 NLB 를 만든 뒤 enabled = true 로 명시적으로 켭니다.
# CloudFront viewer 인증서(ACM)와 CLOUDFRONT scope WAF 는 us-east-1 API 에서 만들므로 루트 모듈에서 aws.global provider 를 추가로 받습니다. provider 블록은 두지 않습니다.

terraform {
  required_version = "= 1.16.0" # 예: "= 1.16.0" (등호로 정확한 버전 고정)

  required_providers {
    aws = {
      source                = "hashicorp/aws" # 예: "hashicorp/aws"
      version               = "= 6.62.0"      # 예: "= 6.62.0" (aws_cloudfront_vpc_origin 을 검증한 버전; 루트 모듈과 같은 값)
      configuration_aliases = [aws.global]    # 예: [aws.global] (루트 모듈의 providers = { aws.global = aws.global } 로 받음)
    }
  }
}

terraform/environments/prod/platform/edg.modules/edge/variables.tf:
# variables.tf — modules/edge (dev · prod 루트 모듈이 공유하는 모듈)

variable "enabled" {
  description = "Create CloudFront, WAF, viewer certificate and app DNS records; false keeps the root at zero AWS resources."
  type        = bool  # 예: bool
  default     = false # 기본값: false (기본은 만들지 않음)
  nullable    = false
}

variable "expected_account_id" {
  description = "AWS account that owns the NLB, the public zone and the CloudFront distribution; 12 digits."
  type        = string # 예: "111111111111"
  nullable    = false

  validation {
    condition     = can(regex("^[0-9]{12}$", var.expected_account_id)) # 예: 숫자 12자리만 통과
    error_message = "Use a 12-digit account ID."
  }
}

variable "gateway_contract" {
  description = "Six items of the gateway root output: cluster_name, vpc_id, exposure_mode, nlb_security_group_id, public_zone_id, dns_zone_name."
  type = object({
    cluster_name          = string # 예: "contract2whale-dev-eks"
    vpc_id                = string # 예: "vpc-0123456789abcdef0"
    exposure_mode         = string # 예: "waf" (edge 를 켤 수 있는 유일한 모드)
    nlb_security_group_id = string # 예: "sg-0123456789abcdef0"
    public_zone_id        = string # 예: "Z0123456789ABCDEFGHIJ"
    dns_zone_name         = string # 예: "dev.playdevops.click"
  })
  nullable = false
}

# NLB Service 가 Active 가 된 뒤 aws elbv2 describe-load-balancers 로 확인한 ARN 을 전달합니다.
variable "nlb_arn" {
  description = "ARN of the internal NLB that the controller created for the Gateway Service; empty while disabled."
  type        = string # 예: "arn:aws:elasticloadbalancing:ap-northeast-2:111111111111:loadbalancer/net/k8s-platfor-platform-0123456789/abcdef0123456789"
  default     = ""     # 기본값: "" (비활성 상태에서는 쓰지 않음)
  nullable    = false
}

# 와일드카드 대신 실제 공개 FQDN 목록입니다. Gateway Certificate 와 HTTPRoute 의 이름과 같아야 합니다.
variable "hostnames" {
  description = "Explicit public hostnames served by CloudFront (also the ACM viewer certificate SANs)."
  type        = set(string) # 예: ["dev.playdevops.click"]
  default     = []          # 기본값: [] (비활성 상태의 기본값)
  nullable    = false

  validation {
    condition     = alltrue([for h in var.hostnames : can(regex("^[a-z0-9][a-z0-9.-]*[a-z0-9]$", h))]) # 예: 소문자 이름만 통과 (와일드카드 · 끝의 점 거부)
    error_message = "Use lowercase explicit DNS names without wildcard or trailing dot."
  }
}

# 승인한 hostname의 Gateway 원본 인증서·체인·실제 TLS 응답을 확인한 뒤 운영자가 입력하는 선언입니다. Terraform의 true 검사나 mock 테스트가 인증서 발급·TLS 성공을 실측하지 않습니다.
variable "origin_tls_ready" {
  description = "Operator confirmation that the Envoy origin certificate is issued by the production CA."
  type        = bool  # 예: bool
  default     = false # 기본값: false (원본 인증서를 확인한 뒤 true 로 바꿈)
  nullable    = false
}

variable "rate_limit_per_5min" {
  description = "Per-source-IP WAF rate threshold over a 300-second evaluation window; not an exact request allowance or immediate blocking guarantee."
  type        = number # 예: 2000
  default     = 2000   # 기본값: 2000 (300초 평가 창의 IP별 rate 기준; 정확한 요청 허용량·즉시 차단 보장이 아님)
  nullable    = false

  validation {
    condition     = var.rate_limit_per_5min >= 10 && var.rate_limit_per_5min == floor(var.rate_limit_per_5min) # 예: 10 이상의 정수
    error_message = "Use an integer rate limit of at least 10."
  }
}

terraform/environments/prod/platform/edg.modules/edge/main.tf:
# main.tf — modules/edge (dev · prod 루트 모듈이 공유하는 모듈)
# 모든 data · 리소스가 var.enabled 로 개수를 0 또는 1(hostnames 만큼)로 정하므로 기본값(false)에서는 아무것도 만들지 않습니다.
# 읽기 조회에서 internet-facing NLB · TLS listener · 다른 VPC 의 원본을 거부합니다. 이 모듈의 최종 사용처는 Prod(CloudFront 와 WAF 로 공개 서비스 완성) 이며 Dev 루트 모듈은 비활성 상태로 코드만 검증합니다.

data "aws_lb" "origin" {
  count = var.enabled ? 1 : 0 # 예: 비활성이면 조회하지 않음
  arn   = var.nlb_arn         # 예: controller 가 만든 NLB 의 ARN
}

data "aws_lb_listener" "https_tcp" {
  count             = var.enabled ? 1 : 0 # 예: 비활성이면 조회하지 않음
  load_balancer_arn = var.nlb_arn         # 예: 같은 NLB 의 ARN
  port              = 443                 # 예: 443 (Envoy 로 전달하는 listener)
}

# VPC origin 은 VPC 에 IGW 가 연결돼 있어야 합니다 (private 서브넷에 IGW 기본 route 를 추가하는 것이 아님).
data "aws_internet_gateway" "attached" {
  count = var.enabled ? 1 : 0 # 예: 비활성이면 조회하지 않음

  filter {
    name   = "attachment.vpc-id"           # 예: VPC 에 붙은 IGW 를 찾는 필터
    values = [var.gateway_contract.vpc_id] # 예: ["vpc-0123456789abcdef0"]
  }
}

resource "terraform_data" "contract" {
  count = var.enabled ? 1 : 0 # 예: 비활성이면 검사 리소스도 만들지 않음

  lifecycle {
    precondition {
      condition     = terraform.workspace == "default" && var.gateway_contract.exposure_mode == "waf" # 예: 기본 workspace + Gateway 가 waf 모드일 때만 참
      error_message = "Enable only behind a WAF-mode internal Gateway in the default workspace."
    }

    precondition {
      condition     = var.origin_tls_ready && length(var.hostnames) > 0 # 예: 원본 인증서 확인 선언 + 이름 1개 이상
      error_message = "Enable only after the WAF-mode internal Gateway has a production TLS certificate and explicit hostnames."
    }

    precondition {
      # 예: zone apex 자체 또는 점으로 구분한 하위 도메인만 허용 ("evildev.playdevops.click" 같은 유사 접미사 거부)
      condition     = alltrue([for h in var.hostnames : h == trimsuffix(var.gateway_contract.dns_zone_name, ".") || endswith(h, ".${trimsuffix(var.gateway_contract.dns_zone_name, ".")}")])
      error_message = "Every hostname must equal the delegated zone apex or be its proper subdomain."
    }

    precondition {
      # 예: 조회한 NLB 가 internal · network · 같은 VPC · 계약 SG 를 가질 때만 참
      condition     = data.aws_lb.origin[0].internal && data.aws_lb.origin[0].load_balancer_type == "network" && data.aws_lb.origin[0].vpc_id == var.gateway_contract.vpc_id && contains(data.aws_lb.origin[0].security_groups, var.gateway_contract.nlb_security_group_id)
      error_message = "CloudFront VPC origin must use the same-VPC internal NLB with the contract security group."
    }

    precondition {
      condition     = data.aws_lb_listener.https_tcp[0].protocol == "TCP" # 예: NLB 가 TLS 를 끝내지 않고 Envoy 로 전달할 때만 참
      error_message = "The NLB 443 listener must be TCP; TLS terminates at Envoy."
    }
  }
}

# ACM 공개 인증서는 viewer TLS 만 담당하며 Envoy 원본 인증서는 cert-manager 가 따로 발급합니다.
resource "aws_acm_certificate" "viewer" {
  count                     = var.enabled ? 1 : 0                                          # 예: 비활성이면 0개
  provider                  = aws.global                                                   # 예: aws.global (us-east-1)
  domain_name               = sort(tolist(var.hostnames))[0]                               # 예: "dev.playdevops.click" (정렬된 첫 이름)
  subject_alternative_names = slice(sort(tolist(var.hostnames)), 1, length(var.hostnames)) # 예: 나머지 이름 목록
  validation_method         = "DNS"                                                        # 예: "DNS" (ACM 이 제공한 CNAME 레코드로 소유를 증명)

  lifecycle {
    create_before_destroy = true # 예: true (새 인증서를 먼저 만들고 바꿈)
  }

  depends_on = [terraform_data.contract] # 예: NLB와 도메인 조건 검사를 먼저 지나갑니다
}

# provider 가 domain_validation_options 를 만든 뒤 각 DNS 검증 레코드를 생성합니다. 주소 키는 사용자가 전달한 hostname 으로 확정합니다.
resource "aws_route53_record" "validation" {
  for_each = var.enabled ? var.hostnames : toset([])                                                                                          # 예: 이름마다 레코드 1개
  zone_id  = var.gateway_contract.public_zone_id                                                                                              # 예: "Z0123456789ABCDEFGHIJ"
  name     = one([for d in aws_acm_certificate.viewer[0].domain_validation_options : d.resource_record_name if d.domain_name == each.key])    # 예: "_abc123.dev.playdevops.click."
  type     = one([for d in aws_acm_certificate.viewer[0].domain_validation_options : d.resource_record_type if d.domain_name == each.key])    # 예: "CNAME"
  records  = [one([for d in aws_acm_certificate.viewer[0].domain_validation_options : d.resource_record_value if d.domain_name == each.key])] # 예: ["_def456.acm-validations.aws."]
  ttl      = 60                                                                                                                               # 예: 60 (초)
}

resource "aws_acm_certificate_validation" "viewer" {
  count                   = var.enabled ? 1 : 0                               # 예: 비활성이면 0개
  provider                = aws.global                                        # 예: aws.global (인증서와 같은 리전)
  certificate_arn         = aws_acm_certificate.viewer[0].arn                 # 예: 요청한 인증서의 ARN
  validation_record_fqdns = [for r in aws_route53_record.validation : r.fqdn] # 예: 위에서 만든 레코드의 전체 이름 목록
}

# VPC origin 전용 ENI 는 CloudFront 가 만듭니다. 내부 NLB 는 TCP 로 Envoy 의 HTTPS 를 전달합니다.
resource "aws_cloudfront_vpc_origin" "gateway" {
  count = var.enabled ? 1 : 0 # 예: 비활성이면 0개

  vpc_origin_endpoint_config {
    name                   = "${var.gateway_contract.cluster_name}-gateway" # 예: "contract2whale-dev-eks-gateway"
    arn                    = data.aws_lb.origin[0].arn                      # 예: 조회한 NLB 의 ARN
    http_port              = 80                                             # 예: 80 (쓰지 않지만 값이 필요)
    https_port             = 443                                            # 예: 443 (실제로 쓰는 포트)
    origin_protocol_policy = "https-only"                                   # 예: "https-only" (평문 경로를 만들지 않음)

    origin_ssl_protocols {
      items    = ["TLSv1.2"] # 예: ["TLSv1.2"]
      quantity = 1           # 예: 1 (items 의 개수)
    }
  }

  depends_on = [terraform_data.contract, data.aws_internet_gateway.attached] # 예: 검사와 IGW 조회 뒤에 만듭니다
}

# 세션과 로그인 응답은 공유 캐시하지 않습니다 (TTL 0). Host · cookie · Authorization · query 는 원본으로 보냅니다.
resource "aws_cloudfront_cache_policy" "disabled" {
  count       = var.enabled ? 1 : 0                             # 예: 비활성이면 0개
  name        = "${var.gateway_contract.cluster_name}-no-cache" # 예: "contract2whale-dev-eks-no-cache"
  default_ttl = 0                                               # 예: 0 (기본 보관 시간 없음)
  max_ttl     = 0                                               # 예: 0 (최대 보관 시간 없음)
  min_ttl     = 0                                               # 예: 0 (최소 보관 시간 없음)

  parameters_in_cache_key_and_forwarded_to_origin {
    enable_accept_encoding_brotli = false # 예: false
    enable_accept_encoding_gzip   = false # 예: false

    cookies_config {
      cookie_behavior = "none" # 예: "none" (캐시 키에 쿠키를 넣지 않음)
    }

    headers_config {
      header_behavior = "none" # 예: "none" (캐시 키에 헤더를 넣지 않음)
    }

    query_strings_config {
      query_string_behavior = "none" # 예: "none" (캐시 키에 query 를 넣지 않음)
    }
  }
}

resource "aws_cloudfront_origin_request_policy" "viewer" {
  count = var.enabled ? 1 : 0                               # 예: 비활성이면 0개
  name  = "${var.gateway_contract.cluster_name}-all-viewer" # 예: "contract2whale-dev-eks-all-viewer"

  cookies_config {
    cookie_behavior = "all" # 예: "all" (쿠키를 원본으로 전달)
  }

  headers_config {
    header_behavior = "allViewer" # 예: "allViewer" (요청자가 보낸 Host · Authorization 을 전달 → Envoy 의 hostname route 와 JWT 유지)
  }

  query_strings_config {
    query_string_behavior = "all" # 예: "all" (query 를 원본으로 전달)
  }
}

resource "aws_wafv2_web_acl" "edge" {
  count    = var.enabled ? 1 : 0                         # 예: 비활성이면 0개
  provider = aws.global                                  # 예: aws.global (CLOUDFRONT scope 는 us-east-1)
  name     = "${var.gateway_contract.cluster_name}-edge" # 예: "contract2whale-dev-eks-edge"
  scope    = "CLOUDFRONT"                                # 예: "CLOUDFRONT" (CloudFront 에 붙이는 범위)

  default_action {
    allow {} # 예: 규칙에 걸리지 않은 요청은 허용
  }

  dynamic "rule" {
    for_each = {
      AWSManagedRulesCommonRuleSet         = 10 # 예: 규칙 이름 → 평가 순서
      AWSManagedRulesKnownBadInputsRuleSet = 20
      AWSManagedRulesSQLiRuleSet           = 30
    }

    content {
      name     = rule.key   # 예: "AWSManagedRulesCommonRuleSet"
      priority = rule.value # 예: 10 (숫자가 작을수록 먼저 평가)

      override_action {
        none {} # 예: 룰 그룹의 동작을 그대로 씀
      }

      statement {
        managed_rule_group_statement {
          name        = rule.key # 예: 관리 룰 그룹 이름
          vendor_name = "AWS"    # 예: "AWS"
        }
      }

      visibility_config {
        cloudwatch_metrics_enabled = true     # 예: true (지표를 남김)
        metric_name                = rule.key # 예: 규칙 이름을 지표 이름으로 사용
        sampled_requests_enabled   = false    # 예: false (요청 표본을 저장하지 않음)
      }
    }
  }

  rule {
    name     = "request-rate" # 예: "request-rate"
    priority = 40             # 예: 40 (관리 규칙 뒤에 평가)

    action {
      block {} # 예: rate 규칙이 매칭한 요청을 차단; 정확한 N번째 요청·반영 시각 보장은 아님
    }

    statement {
      rate_based_statement {
        limit                 = var.rate_limit_per_5min # 예: 2000
        aggregate_key_type    = "IP"                    # 예: "IP" (요청 IP 로 셈)
        evaluation_window_sec = 300                     # 예: 300 (5분 창)
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true           # 예: true
      metric_name                = "request-rate" # 예: "request-rate"
      sampled_requests_enabled   = false          # 예: false
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = true                                        # 예: true
    metric_name                = "${var.gateway_contract.cluster_name}-edge" # 예: "contract2whale-dev-eks-edge"
    sampled_requests_enabled   = false                                       # 예: false
  }
}

# WAF 의 전체 요청 로그를 보존하되 Authorization · Cookie · query 는 가립니다. 로그 그룹 이름은 aws-waf-logs- 로 시작해야 합니다.
resource "aws_cloudwatch_log_group" "waf" {
  count             = var.enabled ? 1 : 0                                 # 예: 비활성이면 0개
  provider          = aws.global                                          # 예: aws.global (Web ACL 과 같은 리전)
  name              = "aws-waf-logs-${var.gateway_contract.cluster_name}" # 예: "aws-waf-logs-contract2whale-dev-eks"
  retention_in_days = 30                                                  # 예: 30 (보존 기간)
}

resource "aws_wafv2_web_acl_logging_configuration" "edge" {
  count                   = var.enabled ? 1 : 0                   # 예: 비활성이면 0개
  provider                = aws.global                            # 예: aws.global
  resource_arn            = aws_wafv2_web_acl.edge[0].arn         # 예: 위에서 만든 Web ACL 의 ARN
  log_destination_configs = [aws_cloudwatch_log_group.waf[0].arn] # 예: 위에서 만든 로그 그룹의 ARN

  redacted_fields {
    single_header {
      name = "authorization" # 예: "authorization" (헤더 값을 가림)
    }
  }

  redacted_fields {
    single_header {
      name = "cookie" # 예: "cookie" (헤더 값을 가림)
    }
  }

  redacted_fields {
    query_string {} # 예: query 문자열 전체를 가림
  }
}

resource "aws_cloudfront_distribution" "app" {
  count               = var.enabled ? 1 : 0                    # 예: 비활성이면 0개
  enabled             = true                                   # 예: true (배포를 켬)
  is_ipv6_enabled     = true                                   # 예: true (IPv6 주소도 제공)
  http_version        = "http2and3"                            # 예: "http2and3"
  aliases             = var.hostnames                          # 예: ["dev.playdevops.click"]
  comment             = "WAF protected internal Envoy Gateway" # 예: 콘솔에서 보이는 설명
  price_class         = "PriceClass_100"                       # 예: "PriceClass_100" (사용할 edge 위치 범위)
  wait_for_deployment = true                                   # 예: true (배포가 끝날 때까지 기다림)
  web_acl_id          = aws_wafv2_web_acl.edge[0].arn          # 예: 위에서 만든 Web ACL 의 ARN

  origin {
    origin_id   = "gateway"                      # 예: "gateway" (아래 동작이 가리킬 이름)
    domain_name = data.aws_lb.origin[0].dns_name # 예: 내부 NLB 의 DNS 이름 (전달 Host 는 viewer 의 app 이름)

    vpc_origin_config {
      vpc_origin_id            = aws_cloudfront_vpc_origin.gateway[0].id # 예: 위에서 만든 VPC origin
      origin_read_timeout      = 60                                      # 예: 60 (초)
      origin_keepalive_timeout = 5                                       # 예: 5 (초)
    }
  }

  default_cache_behavior {
    target_origin_id         = "gateway"                                                    # 예: 위 origin 의 이름
    viewer_protocol_policy   = "redirect-to-https"                                          # 예: HTTP 요청을 HTTPS 로 보냄
    allowed_methods          = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"] # 예: 앱이 쓰는 메서드 전부
    cached_methods           = ["GET", "HEAD"]                                              # 예: 저장을 고려할 메서드
    cache_policy_id          = aws_cloudfront_cache_policy.disabled[0].id                   # 예: TTL 0 정책
    origin_request_policy_id = aws_cloudfront_origin_request_policy.viewer[0].id            # 예: 전달 정책
    compress                 = true                                                         # 예: true (응답 압축)
  }

  restrictions {
    geo_restriction {
      restriction_type = "none" # 예: "none" (지역 제한 없음)
    }
  }

  viewer_certificate {
    acm_certificate_arn      = aws_acm_certificate_validation.viewer[0].certificate_arn # 예: 검증이 끝난 인증서
    ssl_support_method       = "sni-only"                                               # 예: "sni-only"
    minimum_protocol_version = "TLSv1.2_2021"                                           # 예: "TLSv1.2_2021"
  }

  depends_on = [aws_wafv2_web_acl_logging_configuration.edge] # 예: 로그 연결 뒤에 배포합니다
}

# 이 모드에서 앱 DNS 는 Terraform 만 소유합니다. ExternalDNS 가 같은 이름을 쓰게 하지 않습니다 (waf 모드는 ExternalDNS 신원이 없음).
resource "aws_route53_record" "app_ipv4" {
  for_each = var.enabled ? var.hostnames : toset([]) # 예: 이름마다 A 레코드 1개
  zone_id  = var.gateway_contract.public_zone_id     # 예: "Z0123456789ABCDEFGHIJ"
  name     = each.value                              # 예: "dev.playdevops.click"
  type     = "A"                                     # 예: "A" (IPv4 alias)

  alias {
    name                   = aws_cloudfront_distribution.app[0].domain_name    # 예: "d111111abcdef8.cloudfront.net"
    zone_id                = aws_cloudfront_distribution.app[0].hosted_zone_id # 예: CloudFront 의 고정 zone ID
    evaluate_target_health = false                                             # 예: false (alias 상태 검사를 쓰지 않음)
  }
}

resource "aws_route53_record" "app_ipv6" {
  for_each = var.enabled ? var.hostnames : toset([]) # 예: 이름마다 AAAA 레코드 1개
  zone_id  = var.gateway_contract.public_zone_id     # 예: "Z0123456789ABCDEFGHIJ"
  name     = each.value                              # 예: "dev.playdevops.click"
  type     = "AAAA"                                  # 예: "AAAA" (IPv6 alias)

  alias {
    name                   = aws_cloudfront_distribution.app[0].domain_name    # 예: "d111111abcdef8.cloudfront.net"
    zone_id                = aws_cloudfront_distribution.app[0].hosted_zone_id # 예: CloudFront 의 고정 zone ID
    evaluate_target_health = false                                             # 예: false
  }
}

terraform/environments/prod/platform/edg.modules/edge/outputs.tf:
# outputs.tf — modules/edge (dev · prod 루트 모듈이 공유하는 모듈)

output "edge_contract" {
  description = "CloudFront distribution, domain, WAF ARN and hostnames when enabled; null while disabled."
  value = var.enabled ? {
    distribution_id = aws_cloudfront_distribution.app[0].id          # 예: "E1ABCDEFGHIJKL"
    domain_name     = aws_cloudfront_distribution.app[0].domain_name # 예: "d111111abcdef8.cloudfront.net"
    waf_arn         = aws_wafv2_web_acl.edge[0].arn                  # 예: Web ACL 의 ARN
    hostnames       = sort(tolist(var.hostnames))                    # 예: ["dev.playdevops.click"]
  } : null                                                           # 예: 비활성이면 null
}

terraform/environments/prod/platform/edg.terraform/environments/prod/platform/edg:
# main.tf — platform/edge 루트 모듈 (prod · dev 공통 코드)
# CloudFront 와 WAF 로 공개 서비스 완성: 환경별 입력은 루트 모듈, 재사용 리소스는 모듈에서 관리합니다. module "component" 로 변수 7개와 provider 2개를 전달하고 환경 경계 1개를 둡니다.
# Prod 의 첫 plan은 환경 경계 1개 + 모듈 13개 = 14개입니다 (enabled = true · hostnames 1개).

module "component" {
  source = "../../../../../modules/edge" # 예: 이 루트 모듈에서 모듈까지의 상대 경로 (다섯 단계 위가 저장소 최상위)

  providers = {
    aws        = aws        # 예: 왼쪽은 모듈 안의 이름, 오른쪽은 루트 모듈의 provider (서울)
    aws.global = aws.global # 예: us-east-1 provider (ACM · WAF)
  }

  enabled             = var.enabled             # 예: true (Prod 는 공개)
  expected_account_id = var.expected_account_id # 예: "222222222222"
  gateway_contract    = local.gateway_contract  # 예: Gateway State 출력에서 고른 6개 항목
  nlb_arn             = var.nlb_arn             # 예: 조회한 Prod 내부 NLB 의 ARN
  hostnames           = var.hostnames           # 예: ["app.playdevops.click"]
  origin_tls_ready    = var.origin_tls_ready    # 예: true (원본 인증서를 확인한 뒤)
  rate_limit_per_5min = var.rate_limit_per_5min # 예: 2000
}

# 이 디렉터리는 prod 만 받습니다. input 은 State 에 남는 marker 이며 AWS 자원을 만들지 않습니다.
resource "terraform_data" "environment_boundary" {
  input = var.environment # 예: "prod" (input 변경은 in-place 갱신)

  lifecycle {
    precondition {
      condition     = var.environment == "prod" # 예: "prod" 통과 / "dev" 거부 (dev 는 dev/platform/edge 디렉터리, 환경 root 두 개 연결)
      error_message = "This directory accepts only the prod environment."
    }

    precondition {
      condition     = terraform.workspace == "default" # 예: workspace 로 환경을 나누지 않음
      error_message = "Use default workspace and a distinct backend key."
    }
  }
}

# versions.tf — platform/edge 루트 모듈 (dev · prod 공통 코드)
# 환경 root 두 개 연결: Terraform 과 provider 버전을 고정합니다. backend 선언은 backend.tf 에, 모듈 버전과 aws.global alias 선언은 modules/edge/versions.tf 에 있습니다.

terraform {
  required_version = "= 1.16.0" # 예: "= 1.16.0" (등호로 정확한 버전 고정)

  required_providers {
    aws = {
      source  = "hashicorp/aws" # 예: "hashicorp/aws" (공식 레지스트리 경로)
      version = "= 6.62.0"      # 예: "= 6.62.0" (모듈과 같은 값)
    }
  }
}

# providers.tf — platform/edge 루트 모듈 (dev · prod 공통 코드)
# 환경 root 두 개 연결: provider 두 개. 기본 provider 는 워크로드 리전(NLB 조회 · Route 53 · VPC origin), aws.global 은 us-east-1(CloudFront viewer 인증서 · CLOUDFRONT scope WAF · WAF 로그 그룹)입니다.
# 두 provider 모두 같은 계정으로 제한하고 같은 default_tags 를 씁니다. 모듈은 providers = { aws = aws, aws.global = aws.global } 로 둘을 받습니다.

provider "aws" {
  region              = var.region                # 예: "ap-northeast-2" (서울 리전)
  allowed_account_ids = [var.expected_account_id] # 예: ["111111111111"]

  default_tags {
    tags = {
      ManagedBy   = "Terraform"     # 예: "Terraform"
      Environment = var.environment # 예: "dev"
      Component   = "platform-edge" # 예: "platform-edge"
    }
  }
}

# CloudFront viewer 인증서와 CLOUDFRONT 범위 WAF 를 만들 provider 입니다.
provider "aws" {
  alias               = "global"                  # 예: "global" (모듈이 aws.global 로 받음)
  region              = "us-east-1"               # 예: "us-east-1" (전역 서비스의 API 리전; 변수로 바꾸지 않음)
  allowed_account_ids = [var.expected_account_id] # 예: ["111111111111"] (기본 provider 와 같은 계정)

  default_tags {
    tags = {
      ManagedBy   = "Terraform"     # 예: 같은 태그
      Environment = var.environment # 예: "dev"
      Component   = "platform-edge" # 예: "platform-edge"
    }
  }
}

# backend.tf — platform/edge 루트 모듈 (dev · prod 공통 코드)
# 환경 root 두 개 연결: backend 인자는 커밋하지 않는 backend.hcl 이 제공합니다 (terraform init -backend-config=backend.hcl).
# key 는 platform/edge/terraform.tfstate 로 실행 디렉터리 경로 규칙을 따릅니다 (platform/gateway/terraform.tfstate 와 같은 버킷; Edge 리소스를 이 key에서 관리).

terraform {
  backend "s3" {}
}

# variables.tf — platform/edge 루트 모듈 (dev · prod 공통 코드)

variable "expected_account_id" {
  description = "AWS account that owns the NLB, the public zone and the CloudFront distribution; 12 digits."
  type        = string
  nullable    = false

  validation {
    condition     = can(regex("^[0-9]{12}$", var.expected_account_id)) # 예: "111111111111" 통과
    error_message = "Account ID must be 12 digits."
  }
}

variable "region" {
  description = "AWS region of the NLB and the public zone; only ap-northeast-2 is supported (CloudFront/WAF use the fixed us-east-1 alias)."
  type        = string
  default     = "ap-northeast-2" # 기본값: "ap-northeast-2"
  nullable    = false

  validation {
    condition     = var.region == "ap-northeast-2" # 예: 단일 값 비교
    error_message = "This root supports ap-northeast-2 only."
  }
}

variable "environment" {
  description = "Explicit environment name, 2-20 lowercase letters, digits or hyphens."
  type        = string
  nullable    = false

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{1,19}$", var.environment)) # 예: "dev" 통과 / "Dev" 거부
    error_message = "Use a 2-20 character lowercase environment name."
  }
}

# Gateway 루트 모듈의 State 가 있는 버킷입니다. backend.hcl 의 bucket 과 같은 값입니다.
variable "state_bucket_name" {
  description = "S3 bucket holding the platform/gateway state read by terraform_remote_state."
  type        = string # 예: "company-dev-tfstate-111111111111" (CI 보호 입력의 DEV_STATE_BUCKET)
  nullable    = false

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$", var.state_bucket_name)) # 예: 길이·문자 형식 검사; S3 이름의 모든 제약을 검사하는 것은 아님
    error_message = "state_bucket_name must be a valid S3 bucket name."
  }
}

# Dev 는 false 로 둡니다 (Dev 노출은 internal; CloudFront + WAF 공개는 Prod 의 CloudFront 와 WAF 로 공개 서비스 완성).
variable "enabled" {
  description = "Create CloudFront, WAF, viewer certificate and app DNS records; false keeps the root at the environment marker only."
  type        = bool
  default     = false # 기본값: false
  nullable    = false
}

variable "nlb_arn" {
  description = "ARN of the internal NLB that the controller created for the Gateway Service; empty while disabled."
  type        = string
  default     = "" # 기본값: "" (비활성)
  nullable    = false
}

variable "hostnames" {
  description = "Explicit public hostnames served by CloudFront (also the ACM viewer certificate SANs)."
  type        = set(string)
  default     = [] # 기본값: [] (비활성)
  nullable    = false

  validation {
    condition     = alltrue([for h in var.hostnames : can(regex("^[a-z0-9][a-z0-9.-]*[a-z0-9]$", h))]) # 예: 소문자 이름만
    error_message = "Use lowercase explicit DNS names without wildcard or trailing dot."
  }
}

variable "origin_tls_ready" {
  description = "Operator confirmation that the Envoy origin certificate is issued by the production CA."
  type        = bool
  default     = false # 기본값: false
  nullable    = false
}

variable "rate_limit_per_5min" {
  description = "Per-source-IP WAF rate threshold over a 300-second evaluation window; not an exact request allowance or immediate blocking guarantee."
  type        = number
  default     = 2000 # 기본값: 2000
  nullable    = false

  validation {
    condition     = var.rate_limit_per_5min >= 10 && var.rate_limit_per_5min == floor(var.rate_limit_per_5min) # 예: 10 이상의 정수
    error_message = "Use an integer rate limit of at least 10."
  }
}

# locals.tf — platform/edge 루트 모듈 (dev · prod 공통 코드)

locals {
  gateway_contract = {
    cluster_name          = data.terraform_remote_state.gateway.outputs.gateway_contract.cluster_name          # 예: "contract2whale-dev-eks"
    vpc_id                = data.terraform_remote_state.gateway.outputs.gateway_contract.vpc_id                # 예: "vpc-0123456789abcdef0"
    exposure_mode         = data.terraform_remote_state.gateway.outputs.gateway_contract.exposure_mode         # 예: "internal" (Dev; edge 를 켜려면 "waf")
    nlb_security_group_id = data.terraform_remote_state.gateway.outputs.gateway_contract.nlb_security_group_id # 예: "sg-0123456789abcdef0"
    public_zone_id        = data.terraform_remote_state.gateway.outputs.gateway_contract.public_zone_id        # 예: "ZPUBLIC"
    dns_zone_name         = data.terraform_remote_state.gateway.outputs.gateway_contract.dns_zone_name         # 예: "dev.playdevops.click"
  }
}

# remote-state.tf — platform/edge 루트 모듈 (dev · prod 공통 코드)
# 읽는 쪽에는 State 객체 전체의 s3:GetObject 권한이 필요합니다 (관련 구성 의 State 역할 key 목록과 대조).

data "terraform_remote_state" "gateway" {
  backend = "s3" # 예: "s3"

  config = {
    bucket = var.state_bucket_name                # 예: "company-dev-tfstate-111111111111"
    key    = "platform/gateway/terraform.tfstate" # 예: Gateway 루트 모듈의 key
    region = var.region                           # 예: "ap-northeast-2"
  }

  lifecycle {
    postcondition {
      condition = alltrue([
        for name in ["cluster_name", "vpc_id", "exposure_mode", "nlb_security_group_id", "public_zone_id", "dns_zone_name"] :
        contains(keys(try(self.outputs.gateway_contract, {})), name) # 예: 6개 모두 gateway_contract 에 존재
      ])
      error_message = "platform/gateway state must expose gateway_contract with cluster_name, vpc_id, exposure_mode, nlb_security_group_id, public_zone_id and dns_zone_name (apply 계약 테스트와 controller 설치 first)."
    }
  }
}

# outputs.tf — platform/edge 루트 모듈 (dev · prod 공통 코드)
# 환경 root 두 개 연결: child module 의 출력을 같은 이름으로 루트 모듈 밖에 전달합니다. 비활성이면 null 입니다.

output "edge_contract" {
  description = "CloudFront distribution, domain, WAF ARN and hostnames when enabled; null while disabled."
  value       = module.component.edge_contract # 예: null (Dev 기본)
}

terraform/environments/dev/platform/oper.terraform/environments/dev/platform/oper:
# backend.tf — platform/operations 루트 모듈 (dev · prod 공통 코드)
# 운영 기반 루트 모듈과 계약: backend 인자는 커밋하지 않는 backend.hcl 이 제공합니다 (terraform init -backend-config=backend.hcl).
# key 는 platform/operations/terraform.tfstate 로 실행 디렉터리 경로 규칙을 따릅니다 (원본 platform/operations/dev/terraform.tfstate — P2; eks · platform/core 와 같은 버킷).

terraform {
  backend "s3" {}
}

# main.tf — platform/operations 루트 모듈 (dev · prod 공통 코드)

module "component" {
  source   = "../../../../../modules/runtime-operations"
  retained = data.terraform_remote_state.retained.outputs.retained # 예: 이 루트 모듈에서 모듈까지의 상대 경로 (다섯 단계 위가 저장소 최상위)

  enabled_services                   = var.enabled_services                     # 예: 네 도구 모두 (루트 모듈 기본값)
  expected_account_id                = var.expected_account_id                  # 예: "111111111111" (숫자 12자리 계정 번호)
  region                             = var.region                               # 예: "ap-northeast-2" (서울 리전)
  cluster_contract                   = local.cluster_contract                   # 예: eks State 출력으로 조립한 {name, arn, region, kubernetes_version}
  node_group_autoscaling_group_names = local.node_group_autoscaling_group_names # 예: eks State 의 node_contract.autoscaling_group_names (실제 ASG 이름 집합)
  application_log_retention_days     = var.application_log_retention_days       # 예: 90 (허용 목록에 있는 보존 기간)
  alerts_topic_arn                   = local.alerts_topic_arn                   # 예: null (첫 적용) 또는 검토한 alerts_topic_arn 입력
}

# 이 디렉터리는 dev 만 받습니다. input 은 State 에 남는 marker 이며 AWS 자원을 만들지 않습니다.
resource "terraform_data" "environment_boundary" {
  input = var.environment # 예: "dev" (input 변경은 in-place 갱신)

  lifecycle {
    precondition {
      condition     = var.environment == "dev" # 예: "dev" 통과 / "prod" 거부 (prod 는 prod/platform/operations 디렉터리 — 운영 환경)
      error_message = "This directory accepts only the dev environment."
    }

    precondition {
      condition     = terraform.workspace == "default" # 예: workspace 로 환경을 나누지 않음 (backend key 로 구분)
      error_message = "Use default workspace and a distinct backend key."
    }
  }
}

# outputs.tf — platform/operations 루트 모듈 (dev · prod 공통 코드)

output "operations_contract" {
  description = "Account, cluster, region, platform log group, backup bucket and alerts topic ARN for native platform configuration and later roots."
  value       = module.component.operations_contract # 공개 필드: (account_id · cluster_name · region · platform_log_group_name · velero_bucket_name · velero_bucket_arn · alerts_topic_arn)
}



# 배포 플랫폼 의 delivery 루트 모듈이 terraform_remote_state 로 읽습니다 (assume-role chaining 의 신뢰 주체).
output "external_secrets_role_arn" {
  description = "IAM role of the cluster-wide External Secrets controller (read by the delivery root)."
  value       = module.component.external_secrets_role_arn # 예: "arn:aws:iam::111111111111:role/contract2whale-dev-eks-external-secrets"
}

output "grafana_secret_name" {
  value       = module.component.grafana_secret_name
  description = "External secret source name only; no credential data."
}

# providers.tf — platform/operations 루트 모듈 (dev · prod 공통 코드)
# 운영 기반 루트 모듈과 계약: AWS API 만 사용합니다. Helm release(Autoscaler · External Secrets · Fluent Bit · Velero)는 승인 GitOps Application을 읽는 Argo CD가 설치하며 Kubernetes provider 는 두지 않습니다.
# 리전은 계약(cluster_contract.region)이 아니라 변수로 받습니다. provider 설정이 State 조회 결과에 의존하지 않게 하고, 모듈의 precondition 이 두 값을 대조합니다.

provider "aws" {
  region              = var.region                # 예: "ap-northeast-2" (서울 리전; cluster_contract.region 과 같아야 함)
  allowed_account_ids = [var.expected_account_id] # 예: ["111111111111"] (다른 계정이면 실행을 거부)

  # 지원되는 AWS 리소스에 공통 분류 태그를 전달합니다. IAM 권한이 아닙니다.
  default_tags {
    tags = {
      ManagedBy   = "Terraform"           # 예: "Terraform" (수동 생성 리소스와 구분)
      Environment = var.environment       # 예: "dev" (환경 구분)
      Component   = "platform-operations" # 예: "platform-operations" (이 루트 모듈이 만든 리소스에 공통으로 붙는 값)
    }
  }
}

# remote-state.tf — platform/operations 루트 모듈 (dev · prod 공통 코드)
# 운영 기반 루트 모듈과 계약: 앞 루트 모듈(eks)의 root 출력을 State 에서 직접 읽습니다 (P1). upstream.auto.tfvars.json 같은 입력 파일을 만들지 않으며, 노드 그룹이 늘면 다음 plan 에 ASG 태그가 자동으로 나타납니다 (D7).
# 경보 토픽 ARN은 기본 null인 공개 입력입니다. 아직 없는 alerting State를 읽지 않으므로 최초 적용과 재개가 순환하지 않습니다.
# 읽는 쪽에는 State 객체의 s3:GetObject 권한이 필요합니다 (관련 구성 의 State 역할 key 목록과 대조: eks/terraform.tfstate).

data "terraform_remote_state" "eks" {
  backend = "s3" # 예: "s3" (앞 루트 모듈이 State 를 둔 방식)

  config = {
    bucket = var.state_bucket_name   # 예: "company-dev-tfstate-111111111111"
    key    = "eks/terraform.tfstate" # 예: eks 루트 모듈의 key (클러스터 입력과 네트워크 계약; 노드와 Add-on 노드 구성도 같은 key)
    region = var.region              # 예: "ap-northeast-2"
  }

  lifecycle {
    # 모듈 계약에 넣을 네 항목이 모두 있어야 합니다 (환경 root 와 모듈 연결 의 cluster_contract 출력).
    postcondition {
      condition = alltrue([
        for name in ["name", "arn", "region", "kubernetes_version"] :
        contains(keys(try(self.outputs.cluster_contract, {})), name) # 예: 4개 모두 cluster_contract 에 존재
      ])
      error_message = "eks state must expose cluster_contract with name, arn, region and kubernetes_version (apply 생성 plan과 private API 검증 first)."
    }

    postcondition {
      condition     = length(try(self.outputs.node_contract.autoscaling_group_names, [])) > 0 # 예: ["eks-contract2whale-dev-eks-system-…"] (노드와 Add-on 시점 1개)
      error_message = "eks state must expose node_contract.autoscaling_group_names with at least one ASG (apply 적용과 배치 실측 first)."
    }
  }
}

data "terraform_remote_state" "retained" {
  backend = "s3"
  config = {
    bucket  = var.state_bucket_name
    key     = "retained/operations/terraform.tfstate"
    region  = var.region
    encrypt = true
  }
}

# variables.tf — platform/operations 루트 모듈 (dev · prod 공통 코드)
# 대신 state_bucket_name 을 받습니다. 원본의 "cat modules/operations/variables.tf > variables.tf" 복사는 쓰지 않습니다 (내용이 다름).

variable "expected_account_id" {
  description = "AWS account that owns the cluster and the operations resources; 12 digits."
  type        = string # 예: string (앞자리 0 이 사라지지 않도록 문자열)
  nullable    = false

  validation {
    condition     = can(regex("^[0-9]{12}$", var.expected_account_id)) # 예: "111111111111" 통과
    error_message = "Account ID must be 12 digits."
  }
}

# 클러스터가 서울 리전에 있으므로 리전도 고정합니다. 모듈은 cluster_contract.region 이 같은 값인지 따로 검사합니다.
variable "region" {
  description = "AWS region for this root; only ap-northeast-2 is supported."
  type        = string
  default     = "ap-northeast-2" # 기본값: "ap-northeast-2"
  nullable    = false

  validation {
    condition     = var.region == "ap-northeast-2" # 예: 단일 값 비교
    error_message = "This root supports ap-northeast-2 only."
  }
}

# main.tf 의 environment_boundary 가 이 디렉터리에서는 "dev" 만 허용합니다.
variable "environment" {
  description = "Explicit environment name, 2-20 lowercase letters, digits or hyphens."
  type        = string
  nullable    = false

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{1,19}$", var.environment)) # 예: "dev" 통과 / "Dev" 거부
    error_message = "Use a 2-20 character lowercase environment name."
  }
}

# 앞 루트 모듈(eks)의 State가 있는 버킷입니다. backend.hcl 의 bucket 과 같은 값입니다.
variable "state_bucket_name" {
  description = "S3 bucket holding the eks state read by terraform_remote_state."
  type        = string # 예: "company-dev-tfstate-111111111111" (work/lab.env 의 DEV_STATE_BUCKET)
  nullable    = false

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$", var.state_bucket_name)) # 예: S3 버킷 이름 규칙
    error_message = "state_bucket_name must be a valid S3 bucket name."
  }
}

# 이 환경이 운영하는 도구 목록입니다. 모듈 기본값은 autoscaler 하나이지만 dev 루트 모듈은 네 도구를 처음부터 모두 켭니다 (D5; 도구별 STEP 0 "AWS 자원 추가" 는 없음).
variable "enabled_services" {
  description = "Operations services whose AWS resources this root declares."
  type        = set(string)
  default     = ["autoscaler", "external_secrets", "fluent_bit", "velero"] # 기본값: 네 도구 모두 (모듈 validation 이 이름을 검사)
  nullable    = false
}

variable "application_log_retention_days" {
  description = "Retention in days for the platform container log group (module validation restricts the allowed values)."
  type        = number
  default     = 90 # 기본값: 90 (모듈 허용 목록 중 하나)
  nullable    = false
}

# 알림 루트의 생성보다 앞서 적용될 수 있으므로 공개 ARN을 선택 입력으로 받습니다.
variable "alerts_topic_arn" {
  description = "Reviewed public SNS topic ARN; null until the alerting root exists."
  type        = string
  default     = null
  nullable    = true
  validation {
    condition     = var.alerts_topic_arn == null ? true : can(regex("^arn:aws:sns:[a-z0-9-]+:[0-9]{12}:[A-Za-z0-9_-]+$", var.alerts_topic_arn))
    error_message = "alerts_topic_arn must be null or an SNS topic ARN."
  }
}

# versions.tf — platform/operations 루트 모듈 (dev · prod 공통 코드)
# 운영 기반 루트 모듈과 계약: Terraform 과 provider 버전을 고정합니다. backend 선언은 backend.tf 에, 모듈 버전은 modules/operations/versions.tf 에 있습니다.

terraform {
  required_version = "= 1.16.0" # 예: "= 1.16.0" (등호로 정확한 버전 고정)

  required_providers {
    aws = {
      source  = "hashicorp/aws" # 예: "hashicorp/aws" (공식 레지스트리 경로)
      version = "= 6.62.0"      # 예: "= 6.62.0" (모듈과 같은 값)
    }
  }
}

terraform/environments/dev/platform/oper.modules/runtime-operations/main.tf:
# main.tf — modules/operations (dev · prod 루트 모듈이 공유하는 모듈)
# Controller 신원과 저장소: 도구 선택(identities) · 백업 버킷 이름 · ASG 탐색 태그 조합을 계산하고, 플랫폼 로그 그룹 · 시크릿 메타데이터 · ASG 탐색 태그를 선언합니다 (리소스 3종).
# 로그 그룹 주소는 원본과 같이 aws_cloudwatch_log_group.platform 입니다 (application 이 아님). 앱 컨테이너 로그는 이 그룹으로 보내지 않습니다 (관측 파이프라인 수집 경로).

locals {
  # for_each 키가 Terraform 리소스 주소가 됩니다. 키를 바꾸면 Role · 연결이 삭제 후 재생성됩니다.
  all_identities = {
    fluent_bit       = { namespace = "logging", service_account = "fluent-bit" }                # 예: 플랫폼 컨테이너 로그 수집
    autoscaler       = { namespace = "kube-system", service_account = "cluster-autoscaler" }    # 예: 노드 수 자동 조절
    external_secrets = { namespace = "external-secrets", service_account = "external-secrets" } # 예: 시크릿 동기화
    velero           = { namespace = "velero", service_account = "velero" }                     # 예: 백업 · 복구
  }

  identities = { for name, identity in local.all_identities : name => identity if contains(var.enabled_services, name) }

  # 예: "velero-contract2whale-dev-eks-111111111111-ap-northeast-2" (57자, S3 이름 한도 63자 이내 — providers.tf 계약 검사가 확인)
  backup_bucket_name = "velero-${var.cluster_contract.name}-${var.expected_account_id}-${var.region}"

  asg_discovery_tags = {
    "k8s.io/cluster-autoscaler/enabled"                      = "true"  # 예: 자동 확장 대상 그룹 표시
    "k8s.io/cluster-autoscaler/${var.cluster_contract.name}" = "owned" # 예: 이 클러스터 소유 그룹 표시
  }

  # setproduct(ASG 이름 집합, 태그 키 집합) 조합마다 "<ASG 이름>:<태그 키>" 고유 키를 만듭니다.
  asg_tags = {
    for pair in setproduct(var.node_group_autoscaling_group_names, toset(keys(local.asg_discovery_tags))) :
    "${pair[0]}:${pair[1]}" => { asg = pair[0], key = pair[1], value = local.asg_discovery_tags[pair[1]] }
  }
}

# 로그 그룹의 수명 · 보존 기간은 Terraform 이, 로그 stream · event 는 Fluent Bit 가 소유합니다.
resource "aws_cloudwatch_log_group" "platform" {
  count = contains(var.enabled_services, "fluent_bit") ? 1 : 0 # 예: fluent_bit 을 켠 경우에만 1개

  name              = "/platform/${var.cluster_contract.name}/application" # 예: "/platform/contract2whale-dev-eks/application"
  retention_in_days = var.application_log_retention_days                   # 예: 90
  skip_destroy      = false                                                # 예: false (실습 삭제 시 로그 그룹도 삭제)

  depends_on = [terraform_data.contract] # 예: 계약 검사 통과 후 생성
}



resource "aws_autoscaling_group_tag" "discovery" {
  for_each = local.asg_tags # 예: 필드 계약 ("<ASG 이름>:<태그 키>")

  autoscaling_group_name = each.value.asg # 예: "eks-contract2whale-dev-eks-system-0ac12345-..."

  tag {
    key                 = each.value.key   # 예: "k8s.io/cluster-autoscaler/enabled"
    value               = each.value.value # 예: "true"
    propagate_at_launch = false            # 예: false (새 인스턴스에 복사하지 않음)
  }

  depends_on = [terraform_data.contract] # 예: 계약 검사 통과 후 생성
}

terraform/environments/dev/platform/oper.modules/runtime-operations/outputs.tf:
# outputs.tf — modules/operations (dev · prod 루트 모듈이 공유하는 모듈)
# 계약 필드 하나(alerts_topic_arn)에만 쓰이는 입력을 같은 파일에 선언합니다 (원본 배치 유지). 경보 토픽는 알림 루트 모듈(알림 루트 모듈과 설치 검사)이 만들고 이 계약은 그 ARN 을 실어 나르기만 합니다.

variable "alerts_topic_arn" {
  description = "알림 구성이 만든 경보 토픽의 ARN 입니다. 토픽을 만들기 전에는 null 입니다."
  type        = string # 예: string (ARN 을 문자열로 받습니다)
  default     = null   # 예: null (경보 토픽를 아직 만들지 않은 상태; 루트 모듈은 검토한 공개 입력으로 전달)

  validation {
    # 예: null 통과, "arn:aws:sns:ap-northeast-2:111111111111:contract2whale-dev-alerts" 통과, "contract2whale-dev-alerts" 거부
    condition     = var.alerts_topic_arn == null ? true : can(regex("^arn:aws:sns:[a-z0-9-]+:[0-9]{12}:[A-Za-z0-9_-]+$", var.alerts_topic_arn))
    error_message = "경보 토픽 ARN 형식이 필요합니다."
  }
}

output "operations_contract" {
  description = "Account, cluster, region, log group, backup bucket and alerts topic that native platform configuration and later roots (관측 파이프라인 · 계정 통합 · 운영 환경) read; no secret values."
  value = {
    account_id              = var.expected_account_id                              # 예: "111111111111"
    cluster_name            = var.cluster_contract.name                            # 예: "contract2whale-dev-eks" (앞 클러스터 계약의 name)
    region                  = var.region                                           # 예: "ap-northeast-2"
    platform_log_group_name = try(aws_cloudwatch_log_group.platform[0].name, null) # 예: "/platform/contract2whale-dev-eks/application" (fluent_bit 을 끄면 null)
    velero_bucket_name      = try(var.retained.aws_s3_bucket__velero[0].id, null)  # 예: "velero-contract2whale-dev-eks-111111111111-ap-northeast-2" (velero 를 끄면 null)
    velero_bucket_arn       = try(var.retained.aws_s3_bucket__velero[0].arn, null) # 예: "arn:aws:s3:::velero-contract2whale-dev-eks-111111111111-ap-northeast-2"
    alerts_topic_arn        = var.alerts_topic_arn                                 # 예: "arn:aws:sns:ap-northeast-2:111111111111:contract2whale-dev-alerts" 또는 null (첫 적용)
  }
}

output "grafana_secret_name" {
  description = "Secrets Manager secret name that External Secrets syncs into monitoring/grafana-admin; null when external_secrets is disabled."
  value       = try(var.retained.aws_secretsmanager_secret__grafana[0].name, null) # 예: "contract2whale-dev-eks/platform/grafana-admin"
}

# 배포 플랫폼이 assume-role chaining 으로 쓰는 값입니다: 클러스터 전체 External Secrets controller 의 Role. delivery 의 시크릿 읽기 Role 이 이 Role 만 신뢰합니다 (SecretStore spec.provider.aws.role).
output "external_secrets_role_arn" {
  description = "IAM role of the cluster-wide External Secrets controller; downstream SecretStores chain to their own read-only roles from it (null when external_secrets is disabled)."
  value       = try(aws_iam_role.controller["external_secrets"].arn, null) # 예: "arn:aws:iam::111111111111:role/contract2whale-dev-eks-external-secrets"
}

# pod-identity.tf — modules/operations (dev · prod 루트 모듈이 공유하는 모듈)

resource "aws_iam_role" "controller" {
  for_each = local.identities                                              # 예: 필드 계약 (enabled_services 로 걸러진 controller)
  name     = "${var.cluster_contract.name}-${replace(each.key, "_", "-")}" # 예: "contract2whale-dev-eks-fluent-bit"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "pods.eks.amazonaws.com" } # 예: EKS Pod Identity 서비스 주체만 허용
      Action    = ["sts:AssumeRole", "sts:TagSession"]   # 예: 역할 사용 + 세션 태그 부착
      Condition = {
        StringEquals = {
          "aws:RequestTag/eks-cluster-arn"            = var.cluster_contract.arn   # 예: 이 클러스터에서 발급된 세션만
          "aws:RequestTag/kubernetes-namespace"       = each.value.namespace       # 예: "logging"
          "aws:RequestTag/kubernetes-service-account" = each.value.service_account # 예: "fluent-bit"
        }
      }
    }]
  })

  depends_on = [terraform_data.contract] # 예: 계약 검사 통과 후 생성
}

resource "aws_iam_role_policy" "controller" {
  for_each = local.identities                                # 예: Role 과 같은 키
  name     = "controller-permissions"                        # 예: Role 마다 같은 이름 (소속 Role 이 달라 충돌 없음)
  role     = aws_iam_role.controller[each.key].id            # 예: 같은 키의 Role
  policy   = jsonencode(local.controller_policies[each.key]) # 예: 해당 controller 의 정책만 선택
}

resource "aws_eks_pod_identity_association" "controller" {
  for_each = local.identities # 예: Role 과 같은 키

  cluster_name         = var.cluster_contract.name             # 예: "contract2whale-dev-eks"
  namespace            = each.value.namespace                  # 예: "external-secrets"
  service_account      = each.value.service_account            # 예: "external-secrets"
  role_arn             = aws_iam_role.controller[each.key].arn # 예: "arn:aws:iam::111111111111:role/contract2whale-dev-eks-external-secrets"
  disable_session_tags = false                                 # 예: false (세션 태그가 있어야 신뢰 정책 조건이 성립)

  # IAM 반영 지연까지 보장하지는 않지만, 정책 부착 이후에 연결하도록 생성 순서를 고정합니다.
  depends_on = [aws_iam_role_policy.controller]
}

locals {
  controller_policies = {
    fluent_bit = {
      Version = "2012-10-17"
      Statement = [{
        Effect   = "Allow"
        Action   = ["logs:CreateLogStream", "logs:PutLogEvents", "logs:DescribeLogStreams"] # 예: 스트림 생성 · 기록 · 조회
        Resource = "${try(aws_cloudwatch_log_group.platform[0].arn, "inactive")}:*"         # 예: 플랫폼 로그 그룹의 스트림만
      }]
    }

    autoscaler = {
      Version = "2012-10-17"
      Statement = [
        {
          Effect = "Allow"
          Action = [
            "autoscaling:SetDesiredCapacity",                  # 예: 유지하려는 노드 수 변경
            "autoscaling:TerminateInstanceInAutoScalingGroup", # 예: 그룹 안 인스턴스 종료
          ]
          Resource = "*" # 예: 아래 태그 조건으로 대상 ASG 를 좁힘
          Condition = {
            StringEquals = {
              "aws:ResourceTag/k8s.io/cluster-autoscaler/enabled"                      = "true"  # 예: 탐색 태그가 있는 ASG
              "aws:ResourceTag/k8s.io/cluster-autoscaler/${var.cluster_contract.name}" = "owned" # 예: 이 클러스터 소유 ASG
            }
          }
        },
        {
          Effect = "Allow"
          Action = [
            "autoscaling:DescribeAutoScalingGroups",
            "autoscaling:DescribeAutoScalingInstances",
            "autoscaling:DescribeLaunchConfigurations",
            "autoscaling:DescribeScalingActivities",
            "autoscaling:DescribeTags",
            "ec2:DescribeImages",
            "ec2:DescribeInstanceTypes",
            "ec2:DescribeLaunchTemplateVersions",
            "ec2:GetInstanceTypesFromInstanceRequirements",
            "eks:DescribeNodegroup",
          ]
          Resource = "*" # 예: 조회 전용 동작
        },
      ]
    }

    external_secrets = {
      Version = "2012-10-17"
      Statement = [{
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret",
          "secretsmanager:GetResourcePolicy",
          "secretsmanager:ListSecretVersionIds",
        ]
        Resource = try(var.retained.aws_secretsmanager_secret__grafana[0].arn, null) # 예: 대시보드 초기 시크릿 1개만
      }]
    }

    velero = {
      Version = "2012-10-17"
      Statement = [
        {
          # The completed course checkpoint survives Velero TTL GC after Down/Up.
          # Scope is this one lab backup; ordinary production retention needs its approved process.
          Sid      = "RetainCourseCheckpointObjects"
          Effect   = "Deny"
          Action   = ["s3:DeleteObject", "s3:DeleteObjectVersion"]
          Resource = "${try(var.retained.aws_s3_bucket__velero[0].arn, "inactive")}/backups/backups/platform-storage-probe/*"
        },
        {
          Sid      = "RetainCourseCheckpointSnapshots"
          Effect   = "Deny"
          Action   = ["ec2:DeleteSnapshot"]
          Resource = "arn:aws:ec2:${var.region}:${var.expected_account_id}:snapshot/*"
          Condition = {
            StringEquals = {
              "ec2:ResourceTag/velero.io/backup" = "platform-storage-probe"
            }
          }
        },
        {
          # Describe는 목록 조회입니다. 변경 권한과 분리하여 검토합니다.
          Effect    = "Allow"
          Action    = ["ec2:DescribeVolumes", "ec2:DescribeSnapshots"]
          Resource  = "*"
          Condition = { StringEquals = { "aws:RequestedRegion" = var.region } }
        },
        {
          # 기존 변경 권한의 검토용 기준선입니다. 모든 action이 ARN 제한 불가라는 뜻이 아닙니다.
          # 고정 AWS plugin의 생성 태그/호출 순서와 action별 지원표 검증 전 실제 배포는 중단합니다.
          # DeleteSnapshot/CreateTags/CreateVolume/CreateSnapshot 대상·태그 범위 시험 후 확정합니다.
          Effect = "Allow"
          Action = [
            "ec2:CreateTags",
            "ec2:CreateVolume",
            "ec2:CreateSnapshot",
            "ec2:DeleteSnapshot",
          ]
          Resource  = "*"
          Condition = { StringEquals = { "aws:RequestedRegion" = var.region } } # 예: "ap-northeast-2" 안에서만
        },
        {
          Effect   = "Allow"
          Action   = ["s3:ListBucket"]
          Resource = try(var.retained.aws_s3_bucket__velero[0].arn, null) # 예: 백업 버킷 자체
        },
        {
          # s3:PutObjectTagging 은 없습니다 — Velero values 의 backupStorageLocation.config.tagging 을 켜면 이 문장도 함께 바꿉니다.
          Effect = "Allow"
          Action = [
            "s3:GetObject",
            "s3:DeleteObject",
            "s3:PutObject",
            "s3:AbortMultipartUpload",
            "s3:ListMultipartUploadParts",
          ]
          Resource = "${try(var.retained.aws_s3_bucket__velero[0].arn, "inactive")}/*" # 예: 백업 버킷 안의 객체만
        },
      ]
    }
  }
}

terraform/environments/dev/platform/oper.modules/runtime-operations/providers.tf:
# providers.tf — modules/operations (dev · prod 루트 모듈이 공유하는 모듈)
# Controller 신원과 저장소: 이 모듈은 provider 블록을 선언하지 않습니다. 계정 · 리전은 운영 기반 루트 모듈과 계약 루트 모듈의 provider 가 결정합니다.
# terraform_data.contract 는 AWS 리소스를 만들지 않고, 잘못된 workspace · 계약 조합을 plan 단계에서 차단합니다 (모든 리소스가 depends_on 으로 이 검사를 기다림).

resource "terraform_data" "contract" {
  input = var.cluster_contract.arn # 예: "arn:aws:eks:ap-northeast-2:111111111111:cluster/contract2whale-dev-eks"

  lifecycle {
    precondition {
      condition     = terraform.workspace == "default" # 예: default workspace 에서만 통과
      error_message = "default workspace와 운영 기반 전용 state key를 사용하세요."
    }

    precondition {
      condition = (
        var.cluster_contract.arn == "arn:aws:eks:${var.region}:${var.expected_account_id}:cluster/${var.cluster_contract.name}" && # 예: 계약 ARN 을 리전 · 계정 · 이름으로 다시 조립해 비교
        var.cluster_contract.region == var.region &&                                                                               # 예: 계약 리전 = 입력 리전
        var.cluster_contract.kubernetes_version == "1.36" &&                                                                       # 예: 과정 고정 버전 (클러스터 업그레이드 시 함께 수정)
        (!contains(var.enabled_services, "velero") || length(local.backup_bucket_name) <= 63)                                      # 예: 백업 버킷 이름은 S3 한도 63자 이내 (과정 이름 22자 → 57자)
      )
      error_message = "앞 구성의 실제 cluster 계약의 계정/리전/이름, Kubernetes 1.36, 백업 버킷 이름 63자 이내를 확인하세요."
    }
  }
}

