# variables.tf — modules/observability-foundation (dev · prod 루트 모듈이 공유하는 모듈)

variable "expected_account_id" {
  description = "AWS account that owns the cluster and the signal buckets; 12 digits."
  type        = string # 예: string (앞자리 0 이 사라지지 않도록 문자열)
  nullable    = false

  validation {
    condition     = can(regex("^[0-9]{12}$", var.expected_account_id)) # 예: "111111111111" 통과 / "1111" 거부
    error_message = "expected_account_id must contain exactly 12 digits."
  }
}

variable "region" {
  description = "Region of the cluster and the signal buckets; only ap-northeast-2 is supported."
  type        = string
  default     = "ap-northeast-2" # 기본값: "ap-northeast-2" (서울 리전)
  nullable    = false

  validation {
    condition     = var.region == "ap-northeast-2" # 예: 단일 값 비교 (앞 챕터 모듈과 같은 고정)
    error_message = "This module supports ap-northeast-2 only."
  }
}

# 저장소 이름 · 객체 접두사 · 역할 이름에 함께 들어갑니다. workspace 로 환경을 나누지 않습니다.
variable "environment" {
  description = "Environment name used in bucket names, object prefixes and role names; dev or prod."
  type        = string # 예: "dev" (dev 루트 모듈) / "prod" (prod 루트 모듈)
  nullable    = false

  validation {
    condition     = contains(["dev", "prod"], var.environment) # 예: "dev" 통과 / "stage" 거부
    error_message = "environment must be dev or prod."
  }
}

variable "cluster_contract" {
  description = "Four fields of the upstream cluster contract: name, arn, region and kubernetes_version."
  type = object({
    name               = string # 예: "contract2whale-dev-eks"
    arn                = string # 예: "arn:aws:eks:ap-northeast-2:111111111111:cluster/contract2whale-dev-eks"
    region             = string # 예: "ap-northeast-2"
    kubernetes_version = string # 예: "1.36"
  })
  nullable = false

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{1,98}[a-z0-9]$", var.cluster_contract.name)) # 예: "contract2whale-dev-eks"(22자) 통과 (소문자 DNS 형식 3~100자 — EKS 클러스터 이름 한도)
    error_message = "cluster_contract.name must be a lowercase DNS-style name of 3-100 characters."
  }

  validation {
    condition     = can(regex("^arn:aws:eks:[a-z0-9-]+:[0-9]{12}:cluster/[A-Za-z0-9_-]+$", var.cluster_contract.arn)) # 예: EKS 클러스터 ARN 형식만 통과
    error_message = "cluster_contract.arn must be an EKS cluster ARN."
  }
}

# 사람이 저장소 역할을 맡아 점검할 때 쓰는 영구 IAM 역할 ARN 입니다 (환경별 CI 보호 입력 묶음의 DEV_OPERATOR_ROLE_ARN; 관련 구성 state-access-role 과 같은 규칙).
variable "trusted_principal_arns" {
  description = "Exact existing IAM role ARNs allowed to assume the three storage roles for inspection; never STS session ARNs."
  type        = set(string) # 예: set(string) (중복 없는 집합; 순서가 정책에 영향을 주지 않음)
  nullable    = false

  validation {
    condition = (
      length(var.trusted_principal_arns) > 0 &&  # 예: 1 이상
      length(var.trusted_principal_arns) <= 4 && # 예: 4 이하
      alltrue([
        for arn in var.trusted_principal_arns :
        can(regex("^arn:aws:iam::[0-9]{12}:role/[A-Za-z0-9_+=,.@/-]+$", arn)) # 예: "arn:aws:iam::111111111111:role/PlatformOperator" 통과 / assumed-role 거부
      ])
    )
    error_message = "Supply 1-4 exact existing IAM role ARNs; root, user, wildcard and assumed-role session ARNs are rejected."
  }
}

variable "permissions_boundary_arn" {
  description = "Optional existing customer-managed permissions boundary attached to the three storage roles."
  type        = string
  default     = null # 기본값: null (boundary 를 붙이지 않음)

  validation {
    condition = var.permissions_boundary_arn == null ? true : can(regex(
      "^arn:aws:iam::[0-9]{12}:policy/[A-Za-z0-9_+=,.@/-]+$", var.permissions_boundary_arn # 예: "arn:aws:iam::111111111111:policy/PlatformBoundary"
    ))
    error_message = "Supply an existing customer-managed IAM policy ARN or null."
  }
}

# account-baseline State 의 state_object_keys 출력입니다. 이 루트 모듈의 key 가 그 목록에 있어야 저장소를 만듭니다 (providers.tf 의 계약 검사).
variable "allowed_state_keys" {
  description = "state_object_keys output of the account-baseline root; must contain this root's own state key."
  type        = list(string) # 예: ["account-baseline/terraform.tfstate", …, "platform/observability/terraform.tfstate"]
  nullable    = false

  validation {
    condition     = alltrue([for key in var.allowed_state_keys : can(regex("/terraform[.]tfstate$", key))]) # 예: 모든 항목이 terraform.tfstate 로 끝남
    error_message = "allowed_state_keys must contain state object keys ending in /terraform.tfstate."
  }
}

# versions.tf — modules/observability-foundation (dev · prod 루트 모듈이 공유하는 모듈)

terraform {
  required_version = "= 1.16.0" # 예: "= 1.16.0" (등호로 정확한 버전 고정; 루트 모듈과 같은 값)

  required_providers {
    aws = {
      source  = "hashicorp/aws" # 예: "hashicorp/aws" (공식 레지스트리 경로)
      version = "= 6.62.0"      # 예: "= 6.62.0" (앞 챕터 모듈과 같은 값)
    }
  }
}

terraform/environments/dev/account-integ.terraform/environments/dev/account-integ:
# backend.tf — account-integrations 루트 모듈 (dev · prod 공통 코드)
# 환경 root 와 실제 적용: backend 인자는 커밋하지 않는 backend.hcl 이 제공합니다 (terraform init -backend-config=backend.hcl).
# key 는 account-integrations/terraform.tfstate 로 실행 디렉터리 경로 규칙을 따릅니다 (원본 account/integrations/dev/terraform.tfstate — P2; network/vpc · platform/operations 와 같은 버킷).

terraform {
  backend "s3" {}
}

# Protected acknowledgement is included in the immutable saved Terraform plan.
variable "lifecycle_notification_backlog_mode" {
  type    = string
  default = "preserve"
  validation {
    condition     = contains(["preserve", "discard-notifications-retain-source-objects"], var.lifecycle_notification_backlog_mode)
    error_message = "Choose preserve or explicitly approve disposal of lab notification backlog; source S3 objects stay retained."
  }
}

# locals.tf — account-integrations 루트 모듈 (dev · prod 공통 코드)
# 환경 root 와 실제 적용: State 에서 읽은 출력을 모듈 입력 두 계약의 모양으로 조립합니다. 두 값 모두 이 루트 모듈이 직접 입력받지 않습니다.

locals {
  operations_contract = {
    account_id              = data.terraform_remote_state.operations.outputs.operations_contract.account_id              # 예: "111111111111"
    cluster_name            = data.terraform_remote_state.operations.outputs.operations_contract.cluster_name            # 예: "contract2whale-dev-eks"
    region                  = data.terraform_remote_state.operations.outputs.operations_contract.region                  # 예: "ap-northeast-2"
    platform_log_group_name = data.terraform_remote_state.operations.outputs.operations_contract.platform_log_group_name # 예: "/platform/contract2whale-dev-eks/application"
    velero_bucket_name      = data.terraform_remote_state.operations.outputs.operations_contract.velero_bucket_name      # 예: "velero-contract2whale-dev-eks-111111111111-ap-northeast-2"
    velero_bucket_arn       = data.terraform_remote_state.operations.outputs.operations_contract.velero_bucket_arn       # 예: "arn:aws:s3:::velero-contract2whale-dev-eks-111111111111-ap-northeast-2"
    alerts_topic_arn        = data.terraform_remote_state.operations.outputs.operations_contract.alerts_topic_arn        # 예: "arn:aws:sns:ap-northeast-2:111111111111:contract2whale-dev-alerts" 또는 null
  }

  # modules/account-integrations 의 network_logs_contract 객체입니다. network/vpc State 의 출력 두 개를 묶습니다.
  network_logs_contract = {
    bucket_name = data.terraform_remote_state.vpc.outputs.network_logs_bucket_name # 예: "cp-dev-network-logs-111111111111-ap-northeast-2"
    bucket_arn  = data.terraform_remote_state.vpc.outputs.network_logs_bucket_arn  # 예: "arn:aws:s3:::cp-dev-network-logs-111111111111-ap-northeast-2"
  }
}

# main.tf — account-integrations 루트 모듈 (dev · prod 공통 코드)

module "component" {
  source   = "../../../../modules/runtime-account-integrations"
  retained = data.terraform_remote_state.retained.outputs.retained # 예: 이 루트 모듈에서 모듈까지의 상대 경로 (네 단계 위가 저장소 최상위)

  expected_account_id                  = var.expected_account_id                  # 예: "111111111111" (숫자 12자리 계정 번호)
  region                               = var.region                               # 예: "ap-northeast-2" (서울 리전)
  operations_contract                  = local.operations_contract                # 예: platform/operations State 출력으로 조립한 7항목 object
  network_logs_contract                = local.network_logs_contract              # 예: network/vpc State 출력으로 조립한 { bucket_name, bucket_arn }
  log_bytes_per_five_minutes_threshold = var.log_bytes_per_five_minutes_threshold # 예: 52428800 (기본값, 5분 50 MiB)
  enable_external_log_consumer         = var.enable_external_log_consumer         # 예: false (기본값)
  external_log_consumer                = var.external_log_consumer                # 예: null (기본값)
  notification_email_addresses         = var.notification_email_addresses         # 예: [] (기본값)
}

# 이 디렉터리는 dev 만 받습니다. input 은 State 에 남는 marker 이며 AWS 자원을 만들지 않습니다.
resource "terraform_data" "environment_boundary" {
  input = var.environment # 예: "dev" (input 변경은 in-place 갱신)

  lifecycle {
    precondition {
      condition     = var.environment == "dev" # 예: "dev" 통과 / "prod" 거부 (prod 는 prod/account-integrations 디렉터리 — 운영 환경)
      error_message = "This directory accepts only the dev environment."
    }

    precondition {
      condition     = terraform.workspace == "default" # 예: workspace 로 환경을 나누지 않음 (backend key 로 구분)
      error_message = "Use default workspace and a distinct backend key."
    }
  }
}

# outputs.tf — account-integrations 루트 모듈 (dev · prod 공통 코드)

output "integration_contract" {
  description = "Account, region, reports bucket, alarm topic, optional external log consumer handles and the reused backup bucket ARN."
  value       = module.component.integration_contract # 예: 8개 키를 담은 object (account_id · region · reports_bucket_name · reports_bucket_arn · alarm_topic_arn · external_log_queue_url · external_log_consumer_role_arn · backup_bucket_arn)
}

# providers.tf — account-integrations 루트 모듈 (dev · prod 공통 코드)
# 환경 root 와 실제 적용: AWS API 만 사용합니다. 리전 · 계정은 State 조회 결과가 아니라 변수로 받고, 모듈의 terraform_data.contract 가 계약(operations_contract)의 계정 · 리전과 대조합니다.

provider "aws" {
  region              = var.region                # 예: "ap-northeast-2" (서울 리전; operations_contract.region 과 같아야 함)
  allowed_account_ids = [var.expected_account_id] # 예: ["111111111111"] (다른 계정이면 실행을 거부)

  # 지원되는 AWS 리소스에 공통 분류 태그를 전달합니다. IAM 권한이 아닙니다.
  default_tags {
    tags = {
      ManagedBy   = "Terraform"            # 예: "Terraform" (수동 생성 리소스와 구분)
      Environment = var.environment        # 예: "dev" (환경 구분)
      Component   = "account-integrations" # 예: "account-integrations" (이 루트 모듈이 만든 리소스에 공통으로 붙는 값)
    }
  }
}

# remote-state.tf — account-integrations 루트 모듈 (dev · prod 공통 코드)
# 환경 root 와 실제 적용: 앞 루트 모듈 두 곳(network/vpc · platform/operations)의 root 출력을 State 에서 직접 읽습니다 (P1). upstream.auto.tfvars.json 같은 입력 파일을 만들지 않습니다.
# 읽는 쪽에는 State 객체의 s3:GetObject 권한이 필요합니다 (관련 구성 의 State 역할 key 목록과 대조: network/vpc/terraform.tfstate · platform/operations/terraform.tfstate).
# network/transit State 는 읽지 않습니다 — 이 루트 모듈은 TGW · Firewall 의 존재를 요구하지 않으며 transit 은 down.sh 로 비워질 수 있습니다.

# 관련 구성 · 관련 구성 의 네트워크 루트 모듈입니다. locals.tf 가 로그 버킷 이름 · ARN 두 출력을 network_logs_contract 로 묶습니다.
data "terraform_remote_state" "vpc" {
  backend = "s3" # 예: "s3" (앞 루트 모듈이 State 를 둔 방식)

  config = {
    bucket = var.state_bucket_name           # 예: "company-dev-tfstate-111111111111"
    key    = "network/vpc/terraform.tfstate" # 예: network/vpc 루트 모듈의 key (루트 모듈 분리와 입력 계약)
    region = var.region                      # 예: "ap-northeast-2"
  }

  lifecycle {
    # 출력 계약과 계약 테스트 의 로그 버킷 출력 두 개가 모두 있어야 합니다 (flow/ · dns/ 로그를 받는 버킷).
    postcondition {
      condition     = can(self.outputs.network_logs_bucket_name) && can(self.outputs.network_logs_bucket_arn) # 예: 두 출력 모두 존재
      error_message = "network/vpc state must expose network_logs_bucket_name and network_logs_bucket_arn (apply 출력 계약과 계약 테스트 first)."
    }
  }
}

data "terraform_remote_state" "operations" {
  backend = "s3" # 예: "s3"

  config = {
    bucket = var.state_bucket_name                   # 예: "company-dev-tfstate-111111111111" (같은 버킷)
    key    = "platform/operations/terraform.tfstate" # 예: platform/operations 루트 모듈의 key (운영 기반 루트 모듈과 계약; 원본 platform/operations/dev/terraform.tfstate — P2)
    region = var.region                              # 예: "ap-northeast-2"
  }

  lifecycle {
    postcondition {
      condition = alltrue([
        for name in ["account_id", "cluster_name", "region", "platform_log_group_name", "velero_bucket_name", "velero_bucket_arn", "alerts_topic_arn"] :
        contains(keys(try(self.outputs.operations_contract, {})), name) # 예: 7개 모두 operations_contract 에 존재
      ])
      error_message = "platform/operations state must expose operations_contract with its seven items (apply 운영 기반 루트 모듈과 계약 first)."
    }

    # 로그량 알람의 dimension 이므로 fluent_bit 을 끈 운영 기반 구성(platform_log_group_name = null)은 받지 않습니다.
    postcondition {
      condition     = try(self.outputs.operations_contract.platform_log_group_name, null) != null # 예: "/platform/contract2whale-dev-eks/application"
      error_message = "operations_contract.platform_log_group_name must not be null (enable fluent_bit in platform/operations)."
    }
  }
}

data "terraform_remote_state" "retained" {
  backend = "s3"
  config = {
    bucket  = var.state_bucket_name
    key     = "retained/account-integrations/terraform.tfstate"
    region  = var.region
    encrypt = true
  }
}

# variables.tf — account-integrations 루트 모듈 (dev · prod 공통 코드)
# 대신 state_bucket_name 과 environment 를 받습니다. 원본의 "cat modules/account-integrations/variables.tf > variables.tf" 복사는 쓰지 않습니다 (내용이 다름).

variable "expected_account_id" {
  description = "AWS account that owns the platform and receives the integration resources; 12 digits."
  type        = string # 예: string (앞자리 0 이 사라지지 않도록 문자열)
  nullable    = false

  validation {
    condition     = can(regex("^[0-9]{12}$", var.expected_account_id)) # 예: "111111111111" 통과
    error_message = "Account ID must be 12 digits."
  }
}

# 클러스터 · 로그 버킷이 서울 리전에 있으므로 리전도 고정합니다. 모듈은 operations_contract.region 이 같은 값인지 따로 검사합니다.
variable "region" {
  description = "AWS region for this root; only ap-northeast-2 is supported."
  type        = string
  default     = "ap-northeast-2" # 기본값: "ap-northeast-2"
  nullable    = false

  validation {
    condition     = var.region == "ap-northeast-2" # 예: 단일 값 비교
    error_message = "This root supports ap-northeast-2 only."
  }
}

# main.tf 의 environment_boundary 가 이 디렉터리에서는 "dev" 만 허용합니다.
variable "environment" {
  description = "Explicit environment name, 2-20 lowercase letters, digits or hyphens."
  type        = string
  nullable    = false

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{1,19}$", var.environment)) # 예: "dev" 통과 / "Dev" 거부
    error_message = "Use a 2-20 character lowercase environment name."
  }
}

# 앞 루트 모듈(network/vpc · platform/operations) 의 State 가 있는 버킷입니다. backend.hcl 의 bucket 과 같은 값입니다.
variable "state_bucket_name" {
  description = "S3 bucket holding the network/vpc and platform/operations states read by terraform_remote_state."
  type        = string # 예: "company-dev-tfstate-111111111111" (CI 보호 입력의 DEV_STATE_BUCKET)
  nullable    = false

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$", var.state_bucket_name)) # 예: S3 버킷 이름 규칙
    error_message = "state_bucket_name must be a valid S3 bucket name."
  }
}

variable "log_bytes_per_five_minutes_threshold" {
  description = "IncomingBytes sum per 5 minutes that raises the platform log volume alarm (module validation requires > 0)."
  type        = number
  default     = 52428800 # 기본값: 52428800 (50 MiB / 5분)
  nullable    = false
}

variable "enable_external_log_consumer" {
  description = "Create the SQS queue, bucket notification, cross-account role and queue-age alarm only when a real external consumer exists."
  type        = bool
  default     = false # 기본값: false (선택 기능 꺼짐 — 리소스 0개)
  nullable    = false
}

# 값은 terraform.tfvars 가 아니라 -var-file 또는 TF_VAR_external_log_consumer 로 공급합니다 (비밀 입력).
variable "external_log_consumer" {
  description = "Real IAM role ARN of the external consumer and the agreed External ID (16+ characters); null unless the consumer is enabled."
  type = object({
    principal_role_arn = string # 예: "arn:aws:iam::222222222222:role/log-consumer"
    external_id        = string # 예: "AGREED-EXTERNAL-ID-0001"
  })
  default   = null # 기본값: null (모듈 validation 이 형식을 검사)
  sensitive = true # 예: true (plan · output 화면에서 값을 가림)
}

variable "notification_email_addresses" {
  description = "Email addresses that receive the SNS confirmation mail; empty set creates no subscription."
  type        = set(string)
  default     = [] # 기본값: [] (구독 0개; 모듈 validation 이 형식을 검사)
  nullable    = false
}

# versions.tf — account-integrations 루트 모듈 (dev · prod 공통 코드)
# 환경 root 와 실제 적용: Terraform 과 provider 버전을 고정합니다. backend 선언은 backend.tf 에, 모듈 버전은 modules/account-integrations/versions.tf 에 있습니다.

terraform {
  required_version = "= 1.16.0" # 예: "= 1.16.0" (등호로 정확한 버전 고정)

  required_providers {
    aws = {
      source  = "hashicorp/aws" # 예: "hashicorp/aws" (공식 레지스트리 경로)
      version = "= 6.62.0"      # 예: "= 6.62.0" (모듈과 같은 값)
    }
  }
}

terraform/environments/dev/account-integ.modules/runtime-account-integrations/ala:
# alarms.tf — modules/account-integrations (dev · prod 루트 모듈이 공유하는 모듈)
# 주제만 만든 상태에서는 외부에 통보되지 않습니다. 구독 확인(confirmation)은 사람이 메일에서 수행하는 별도 운영 단계입니다.
# 큐 적체 알람(aws_cloudwatch_metric_alarm.log_queue_age)은 큐를 참조하므로 큐와 같은 파일(선택 외부 로그 소비자 external-log-consumer.tf)에 있습니다.

resource "aws_sns_topic" "platform" {
  name = "${var.operations_contract.cluster_name}-platform-operations" # 예: "contract2whale-dev-eks-platform-operations" (알림 루트 모듈과 설치 검사 의 contract2whale-dev-alerts 와 다른 주제)

  depends_on = [terraform_data.contract] # 예: 계약 검사를 통과한 뒤에 만듭니다
}

# 같은 계정의 지정 접두사 알람 ARN 에서 오는 CloudWatch 서비스 요청만 sns:Publish 를 허용합니다.
resource "aws_sns_topic_policy" "platform" {
  arn = aws_sns_topic.platform.arn # 예: "arn:aws:sns:ap-northeast-2:111111111111:contract2whale-dev-eks-platform-operations"
  policy = jsonencode({
    Version = "2012-10-17" # 예: "2012-10-17" (정책 문법 버전, 날짜가 아닙니다)
    Statement = [{
      Sid       = "AllowCloudWatchAlarms"                  # 예: "AllowCloudWatchAlarms" (사람이 읽는 문장 식별자)
      Effect    = "Allow"                                  # 예: "Allow" (조건에 맞는 요청을 허용합니다)
      Principal = { Service = "cloudwatch.amazonaws.com" } # 예: CloudWatch 서비스만 주체로 허용합니다
      Action    = "sns:Publish"                            # 예: "sns:Publish" (메시지를 넣는 동작만 허용)
      Resource  = aws_sns_topic.platform.arn               # 예: 이 주제 하나만 대상으로 합니다
      Condition = {
        StringEquals = { "aws:SourceAccount" = var.expected_account_id }                                                                                   # 예: "111111111111" (같은 계정의 알람만)
        ArnLike      = { "aws:SourceArn" = "arn:aws:cloudwatch:${var.region}:${var.expected_account_id}:alarm:${var.operations_contract.cluster_name}-*" } # 예: "arn:aws:cloudwatch:ap-northeast-2:111111111111:alarm:contract2whale-dev-eks-*"
      }
    }]
  })
}

# 주소를 넣고 apply 하면 SNS 가 실제 확인 메일을 보냅니다. 확인 전에는 수신이 완료되지 않습니다 (PendingConfirmation).
resource "aws_sns_topic_subscription" "email" {
  for_each  = var.notification_email_addresses # 예: [] 이면 구독 0개, 주소 1개면 구독 1개
  topic_arn = aws_sns_topic.platform.arn       # 예: 위에서 만든 주제의 ARN
  protocol  = "email"                          # 예: "email" (확인 절차가 필요한 전달 방식)
  endpoint  = each.value                       # 예: "ops-alerts@example.com" (본인이 받는 주소)
}

# 플랫폼 로그 그룹의 5분 수집 바이트가 임계값을 2구간 연속 넘으면 ALARM. 수집량 · 비용 신호이며 앱 동작이나 로그 유실 지표가 아닙니다.
resource "aws_cloudwatch_metric_alarm" "platform_log_volume" {
  alarm_name          = "${var.operations_contract.cluster_name}-platform-log-ingestion-spike"                                    # 예: "contract2whale-dev-eks-platform-log-ingestion-spike" (주제 정책의 접두사 조건과 일치)
  alarm_description   = "Platform log group IncomingBytes over 5-minute threshold; volume and cost, not app behavior or log loss" # 예: 콘솔에 표시할 설명
  namespace           = "AWS/Logs"                                                                                                # 예: "AWS/Logs" (CloudWatch Logs 의 지표 묶음)
  metric_name         = "IncomingBytes"                                                                                           # 예: "IncomingBytes" (수집된 바이트 수)
  dimensions          = { LogGroupName = var.operations_contract.platform_log_group_name }                                        # 예: { LogGroupName = "/platform/contract2whale-dev-eks/application" }
  statistic           = "Sum"                                                                                                     # 예: "Sum" (구간 안의 값을 더합니다)
  period              = 300                                                                                                       # 예: 300 (5분 구간)
  evaluation_periods  = 2                                                                                                         # 예: 2 (최근 구간 2개를 봅니다)
  datapoints_to_alarm = 2                                                                                                         # 예: 2 (그중 2개가 초과해야 ALARM)
  threshold           = var.log_bytes_per_five_minutes_threshold                                                                  # 예: 52428800 (50 MiB)
  comparison_operator = "GreaterThanThreshold"                                                                                    # 예: 임계값보다 클 때 초과로 셉니다
  treat_missing_data  = "notBreaching"                                                                                            # 예: "notBreaching" (결측 구간을 미달로 셉니다)
  alarm_actions       = [aws_sns_topic.platform.arn]                                                                              # 예: ALARM 이 될 때 이 주제로 보냅니다
  ok_actions          = [aws_sns_topic.platform.arn]                                                                              # 예: OK 로 돌아올 때도 이 주제로 보냅니다

  depends_on = [aws_sns_topic_policy.platform] # 예: 발행 정책이 붙은 뒤에 알람을 만듭니다
}

terraform/environments/dev/account-integ.modules/runtime-account-integrations/ext:
# external-log-consumer.tf — modules/account-integrations (dev · prod 루트 모듈이 공유하는 모듈)
# 실제 상대의 Role ARN 과 합의한 External ID 가 있기 전에는 켜지 않습니다. 켜면 앞 네트워크 구성이 만든 로그 버킷에 알림 설정이 붙습니다 (버킷 자체는 재선언하지 않음).

resource "aws_sqs_queue" "logs" {
  count                      = var.enable_external_log_consumer ? 1 : 0                     # 예: 기본 0개, 켜면 1개
  name                       = "${var.operations_contract.cluster_name}-network-log-events" # 예: "contract2whale-dev-eks-network-log-events"
  sqs_managed_sse_enabled    = true                                                         # 예: true (SQS 가 관리하는 키로 저장 암호화)
  message_retention_seconds  = 1209600                                                      # 예: 1209600 (14일 동안 보관)
  visibility_timeout_seconds = 300                                                          # 예: 300 (받은 메시지를 5분 동안 숨김)
  receive_wait_time_seconds  = 20                                                           # 예: 20 (최대 20초까지 기다리는 긴 폴링)

  depends_on = [terraform_data.contract] # 예: 계약 검사를 통과한 뒤에 만듭니다
}

# 로그 버킷(같은 계정)에서 오는 S3 서비스 요청만 sqs:SendMessage 를 허용합니다.
resource "aws_sqs_queue_policy" "logs" {
  count     = var.enable_external_log_consumer ? 1 : 0 # 예: 기본 0개, 켜면 1개
  queue_url = aws_sqs_queue.logs[0].url                # 예: "https://sqs.ap-northeast-2.amazonaws.com/111111111111/contract2whale-dev-eks-network-log-events"
  policy = jsonencode({
    Version = "2012-10-17" # 예: "2012-10-17" (정책 문법 버전, 날짜가 아닙니다)
    Statement = [{
      Effect    = "Allow"                          # 예: "Allow" (조건에 맞는 요청을 허용합니다)
      Principal = { Service = "s3.amazonaws.com" } # 예: S3 서비스만 주체로 허용합니다
      Action    = "sqs:SendMessage"                # 예: "sqs:SendMessage" (메시지를 넣는 동작만 허용)
      Resource  = aws_sqs_queue.logs[0].arn        # 예: "arn:aws:sqs:ap-northeast-2:111111111111:contract2whale-dev-eks-network-log-events"
      Condition = {
        ArnEquals    = { "aws:SourceArn" = var.network_logs_contract.bucket_arn } # 예: "arn:aws:s3:::cp-dev-network-logs-111111111111-ap-northeast-2"
        StringEquals = { "aws:SourceAccount" = var.expected_account_id }          # 예: "111111111111" (같은 계정의 버킷만)
      }
    }]
  })
}

# S3 한 버킷의 notification 설정 전체는 하나의 resource · State 가 소유해야 합니다.
# 앞 네트워크 구성이 만든 같은 버킷의 flow/ 와 dns/ 를 queue 블록 두 개로 한 리소스에서 관리합니다.
resource "aws_s3_bucket_notification" "network_logs" {
  count  = var.enable_external_log_consumer ? 1 : 0 # 예: 기본 0개, 켜면 1개
  bucket = var.network_logs_contract.bucket_name    # 예: "cp-dev-network-logs-111111111111-ap-northeast-2"

  queue {
    id            = "flow-logs"               # 예: "flow-logs" (알림 항목 식별자)
    queue_arn     = aws_sqs_queue.logs[0].arn # 예: 위에서 만든 큐의 ARN
    events        = ["s3:ObjectCreated:*"]    # 예: Put · Copy · Multipart 완료를 알리며 같은 키의 다시 쓰기도 포함합니다
    filter_prefix = "flow/"                   # 예: "flow/" (VPC Flow Log 저장 경로)
  }

  queue {
    id            = "dns-logs"                # 예: "dns-logs" (알림 항목 식별자)
    queue_arn     = aws_sqs_queue.logs[0].arn # 예: 같은 큐로 보냅니다
    events        = ["s3:ObjectCreated:*"]    # 예: Put · Copy · Multipart 완료
    filter_prefix = "dns/"                    # 예: "dns/" (DNS 질의 로그 저장 경로)
  }

  depends_on = [aws_sqs_queue_policy.logs] # 예: 큐 정책을 붙인 뒤에 알림을 설정합니다 (S3 가 정책을 검사)
}

# 상대 계정의 Role 만 합의된 External ID 로 이 Role 을 맡을 수 있습니다.
resource "aws_iam_role" "external_log_consumer" {
  count = var.enable_external_log_consumer ? 1 : 0                      # 예: 기본 0개, 켜면 1개
  name  = "${var.operations_contract.cluster_name}-external-log-reader" # 예: "contract2whale-dev-eks-external-log-reader"
  assume_role_policy = jsonencode({
    Version = "2012-10-17" # 예: "2012-10-17" (정책 문법 버전, 날짜가 아닙니다)
    Statement = [{
      Effect    = "Allow"                                                                                  # 예: "Allow" (조건에 맞는 요청을 허용합니다)
      Principal = { AWS = try(var.external_log_consumer.principal_role_arn, "") }                          # 예: "arn:aws:iam::222222222222:role/log-consumer" (기본 null 이면 "" — count 0 이라 평가되지 않음)
      Action    = "sts:AssumeRole"                                                                         # 예: "sts:AssumeRole" (이 Role 을 맡는 동작)
      Condition = { StringEquals = { "sts:ExternalId" = try(var.external_log_consumer.external_id, "") } } # 예: 합의한 External ID 와 같아야 허용합니다
    }]
  })

  depends_on = [terraform_data.contract] # 예: 계약 검사를 통과한 뒤에 만듭니다
}

# 큐 동작 5종과 로그 버킷의 flow/* · dns/* 객체 읽기만 허용합니다 (버킷 전체 · 목록 조회 없음).
resource "aws_iam_role_policy" "external_log_consumer" {
  count = var.enable_external_log_consumer ? 1 : 0 # 예: 기본 0개, 켜면 1개
  role  = aws_iam_role.external_log_consumer[0].id # 예: "contract2whale-dev-eks-external-log-reader"
  name  = "consume-network-logs"                   # 예: "consume-network-logs" (Role 안에서의 정책 이름)
  policy = jsonencode({
    Version = "2012-10-17" # 예: "2012-10-17" (정책 문법 버전, 날짜가 아닙니다)
    Statement = [
      {
        Effect   = "Allow"                                                                                                                 # 예: 이 큐 하나에서 메시지를 받고 지우고 상태를 조회하는 동작만 허용
        Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl", "sqs:ChangeMessageVisibility"] # 예: 큐 동작 5종
        Resource = aws_sqs_queue.logs[0].arn                                                                                               # 예: 큐 ARN
      },
      {
        Effect   = "Allow"                                                                                             # 예: 두 경로의 객체 읽기만 허용
        Action   = ["s3:GetObject"]                                                                                    # 예: 객체 읽기
        Resource = ["${var.network_logs_contract.bucket_arn}/flow/*", "${var.network_logs_contract.bucket_arn}/dns/*"] # 예: ["arn:aws:s3:::cp-dev-network-logs-…/flow/*", "…/dns/*"]
      }
    ]
  })
}

# 가장 오래된 미삭제 메시지가 15분(900초)을 넘으면 소비 지연 신호입니다. 소비 중단뿐 아니라 처리 속도·재시도·적체도 확인합니다. 큐와 같은 스위치로 켜집니다.
resource "aws_cloudwatch_metric_alarm" "log_queue_age" {
  count               = var.enable_external_log_consumer ? 1 : 0                         # 예: 기본 0개, 외부 소비자를 켜면 1개
  alarm_name          = "${var.operations_contract.cluster_name}-external-log-queue-age" # 예: "contract2whale-dev-eks-external-log-queue-age" (주제 정책의 접두사 조건과 일치)
  namespace           = "AWS/SQS"                                                        # 예: "AWS/SQS" (SQS 의 지표 묶음)
  metric_name         = "ApproximateAgeOfOldestMessage"                                  # 예: 미삭제 메시지의 근사 최대 나이(초)
  dimensions          = { QueueName = aws_sqs_queue.logs[0].name }                       # 예: { QueueName = "contract2whale-dev-eks-network-log-events" }
  statistic           = "Maximum"                                                        # 예: "Maximum" (구간 안의 최댓값을 봅니다)
  period              = 300                                                              # 예: 300 (5분 구간)
  evaluation_periods  = 2                                                                # 예: 2 (최근 구간 2개를 봅니다)
  threshold           = 900                                                              # 예: 900 (15분)
  comparison_operator = "GreaterThanThreshold"                                           # 예: 임계값보다 클 때 초과로 셉니다
  treat_missing_data  = "notBreaching"                                                   # 예: "notBreaching" (결측 구간을 미달로 셉니다)
  alarm_actions       = [aws_sns_topic.platform.arn]                                     # 예: ALARM 이 될 때 이 주제로 보냅니다

  depends_on = [aws_sns_topic_policy.platform] # 예: 발행 정책이 붙은 뒤에 이 알람을 만듭니다
}

terraform/environments/dev/account-integ.modules/runtime-account-integrations/mai:
# main.tf — modules/account-integrations (dev · prod 루트 모듈이 공유하는 모듈)
# 보고 버킷은 텍스트 · JSON 보고서용입니다. 운영 기반 구성의 Velero 백업 버킷과 네트워크 구성의 로그 버킷은 다시 선언하지 않습니다 (이름 · ARN 만 계약으로 받음).

# AWS 리소스를 만들지 않고, 잘못된 workspace · 계약 조합을 plan 단계에서 차단합니다 (모든 리소스가 depends_on 으로 이 검사를 기다림).
resource "terraform_data" "contract" {
  input = var.operations_contract.cluster_name # 예: "contract2whale-dev-eks" (값이 바뀌면 검사를 다시 실행합니다)

  lifecycle {
    precondition {
      # 예: default workspace 이고 계약의 계정 · 리전이 입력과 같아야 통과합니다
      condition     = terraform.workspace == "default" && var.operations_contract.account_id == var.expected_account_id && var.operations_contract.region == var.region
      error_message = "default workspace 및 동일 계정/리전의 운영 기반 구성 계약이 필요합니다."
    }

    precondition {
      # 예: "contract2whale-dev-eks" 는 통과하고(보고 버킷 이름 58자), 보고 버킷 이름이 63자를 넘거나 ARN 이 버킷 이름과 다르면 거부합니다
      condition     = can(regex("^[a-z][a-z0-9-]{1,98}[a-z0-9]$", var.operations_contract.cluster_name)) && length("reports-${var.operations_contract.cluster_name}-${var.expected_account_id}-${var.region}") <= 63 && var.network_logs_contract.bucket_arn == "arn:aws:s3:::${var.network_logs_contract.bucket_name}"
      error_message = "클러스터 이름(보고 버킷 이름 63자 이내)과 네트워크 로그 버킷 이름/ARN 계약을 확인하세요."
    }

    precondition {
      # 예: 기능을 끄면 항상 통과하고, 켜면 external_log_consumer 객체가 있어야 통과합니다
      condition     = !var.enable_external_log_consumer || var.external_log_consumer != null
      error_message = "외부 소비자를 켜려면 실제 principal_role_arn과 external_id가 필요합니다."
    }
  }
}











# HTTP(암호화되지 않은 전송) 요청만 거부합니다. AWS 서비스 주체의 요청은 예외입니다.

terraform/environments/dev/account-integ.modules/runtime-account-integrations/ret:
variable "retained" {
  description = "Verified outputs from the independently retained root; immutable IDs, never whole State."
  type        = any
}

terraform/environments/dev/account-integ.modules/runtime-account-integrations/var:
# variables.tf — modules/account-integrations (dev · prod 루트 모듈이 공유하는 모듈)

variable "expected_account_id" {
  description = "이 연동 리소스를 만드는 AWS 계정의 12자리 번호입니다."
  type        = string # 예: string (앞자리 0 이 사라지지 않도록 문자열)
  nullable    = false

  validation {
    condition     = can(regex("^[0-9]{12}$", var.expected_account_id)) # 예: "111111111111" 통과, "1111-1111" 거부
    error_message = "사용자 AWS 계정의 12자리 번호가 필요합니다."
  }
}

variable "region" {
  description = "연동 리소스를 만드는 리전입니다. 앞 구성 계약의 region 과 같아야 합니다 (main.tf 의 contract 가 대조)."
  type        = string
  default     = "ap-northeast-2" # 기본값: "ap-northeast-2" (서울 리전)
  nullable    = false
}

variable "operations_contract" {
  description = "운영 기반 구성(운영 기반 루트 모듈과 계약 platform/operations)의 operations_contract 출력 7항목입니다. root State 전체가 아니라 공개 계약만 받습니다."
  # 예: { account_id = "111111111111", cluster_name = "contract2whale-dev-eks", region = "ap-northeast-2", platform_log_group_name = "/platform/contract2whale-dev-eks/application", velero_bucket_name = "velero-…", velero_bucket_arn = "arn:aws:s3:::velero-…", alerts_topic_arn = "arn:aws:sns:…" }
  type = object({
    account_id              = string # 예: "111111111111" (운영 기반 구성을 적용한 계정)
    cluster_name            = string # 예: "contract2whale-dev-eks" (버킷 · 주제 · 알람 이름의 접두사)
    region                  = string # 예: "ap-northeast-2"
    platform_log_group_name = string # 예: "/platform/contract2whale-dev-eks/application" (로그량 알람의 dimension)
    velero_bucket_name      = string # 예: "velero-contract2whale-dev-eks-111111111111-ap-northeast-2" (재선언하지 않음)
    velero_bucket_arn       = string # 예: "arn:aws:s3:::velero-contract2whale-dev-eks-111111111111-ap-northeast-2" (계약 출력 backup_bucket_arn 으로 전달)
    alerts_topic_arn        = string # 예: "arn:aws:sns:ap-northeast-2:111111111111:contract2whale-dev-alerts" 또는 null (알림 루트 모듈과 설치 검사 이전)
  })
  nullable = false
}

variable "network_logs_contract" {
  description = "네트워크 구성(관련 구성 network/vpc)의 network_logs_bucket_name · network_logs_bucket_arn 출력을 묶은 계약입니다."
  # 예: { bucket_name = "cp-dev-network-logs-111111111111-ap-northeast-2", bucket_arn = "arn:aws:s3:::cp-dev-network-logs-111111111111-ap-northeast-2" }
  type = object({
    bucket_name = string # 예: "cp-dev-network-logs-111111111111-ap-northeast-2" (flow/ · dns/ 로그가 쌓이는 버킷)
    bucket_arn  = string # 예: "arn:aws:s3:::cp-dev-network-logs-111111111111-ap-northeast-2"
  })
  nullable = false
}

variable "log_bytes_per_five_minutes_threshold" {
  description = "플랫폼 로그 그룹의 5분 수집 바이트(IncomingBytes 합계) 경고 임계값입니다. 비용 예측값이나 유실 탐지 임계값이 아닙니다."
  type        = number
  default     = 52428800 # 기본값: 52428800 (50 MiB / 5분)
  nullable    = false

  validation {
    condition     = var.log_bytes_per_five_minutes_threshold > 0 # 예: 52428800 통과, 0 거부
    error_message = "임계값은 0보다 커야 합니다."
  }
}

variable "enable_external_log_consumer" {
  description = "실제 외부 소비자가 있을 때만 true 로 바꿉니다. true 면 SQS 큐 · 큐 정책 · 버킷 알림 · cross-account Role · Role 정책 · 큐 적체 알람이 생깁니다."
  type        = bool
  default     = false # 기본값: false (선택 기능을 끈 상태 — 리소스 0개)
  nullable    = false
}

variable "external_log_consumer" {
  description = "외부 소비자의 실제 IAM Role ARN 과 합의된 External ID 입니다. 예시 숫자로 켜지 않습니다."
  # 예: { principal_role_arn = "arn:aws:iam::222222222222:role/log-consumer", external_id = "AGREED-EXTERNAL-ID-0001" }
  type = object({
    principal_role_arn = string # 예: "arn:aws:iam::222222222222:role/log-consumer" (상대 계정의 Role)
    external_id        = string # 예: "AGREED-EXTERNAL-ID-0001" (16자 이상, 상대와 합의한 값)
  })
  default   = null # 기본값: null (값이 없음)
  sensitive = true # 예: true (plan · output 화면에서 값을 가림)

  validation {
    # 예: null 이면 통과, 값이 있으면 Role ARN 형식과 16자 이상의 External ID 를 요구합니다
    condition     = var.external_log_consumer == null ? true : can(regex("^arn:aws:iam::[0-9]{12}:role/.+$", var.external_log_consumer.principal_role_arn)) && length(var.external_log_consumer.external_id) >= 16
    error_message = "유효한 실제 IAM role ARN과 16자 이상의 External ID가 필요합니다."
  }
}

variable "notification_email_addresses" {
  description = "SNS 확인 메일을 실제로 받을 사용자 주소입니다. 기본 빈 집합이며 주소를 넣으면 구독 요청(확인 메일)이 만들어집니다."
  type        = set(string)
  default     = [] # 기본값: [] (구독을 만들지 않음)
  nullable    = false

  validation {
    # 예: "ops-alerts@example.com" 통과, "ops-alerts" 거부
    condition     = alltrue([for email in var.notification_email_addresses : can(regex("^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$", email))])
    error_message = "이메일 주소 형식을 확인하세요."
  }
}

terraform/environments/dev/account-integ.modules/runtime-account-integrations/ver:
# versions.tf — modules/account-integrations (dev · prod 루트 모듈이 공유하는 모듈)
# 상위 출력을 받는 입력과 보고 버킷: 플랫폼 구성(운영 도구 운영 기반) 이후에 계정 단위로 붙는 연동 리소스(보고 버킷 · 알람 · SNS · 선택 외부 로그 소비자)를 관리하는 모듈입니다.
# 과정 내부 전용 모듈이라 루트 모듈과 같은 값을 등호로 고정합니다 (P7). provider 블록은 두지 않습니다 (인증 · 리전 · default_tags 는 환경 root 와 실제 적용 루트 모듈의 providers.tf 가 담당).

terraform {
  required_version = "= 1.16.0" # 예: "= 1.16.0" (도구 저장소 tool-versions 고정값과 동일)

  required_providers {
    aws = {
      source  = "hashicorp/aws" # 예: "hashicorp/aws" (공식 레지스트리 경로)
      version = "= 6.62.0"      # 예: "= 6.62.0" (과정 전체의 provider 고정값)
    }
  }
}

terraform/environments/prod/platform/ope.terraform/environments/prod/platform/ope:
# backend.tf — platform/operations 루트 모듈 (dev · prod 공통 코드)
# 운영 기반 루트 모듈과 계약: backend 인자는 커밋하지 않는 backend.hcl 이 제공합니다 (terraform init -backend-config=backend.hcl).
# key 는 platform/operations/terraform.tfstate 로 실행 디렉터리 경로 규칙을 따릅니다 (원본 platform/operations/prod/terraform.tfstate — P2; eks · platform/core 와 같은 버킷).

terraform {
  backend "s3" {}
}

# main.tf — platform/operations 루트 모듈 (dev · prod 공통 코드)
# 운영 기반 루트 모듈과 계약: 환경별 입력은 루트 모듈, 재사용 리소스는 모듈에서 관리합니다. module "component" 로 변수 7개를 전달하고 환경 경계 1개를 둡니다.

module "component" {
  source   = "../../../../../modules/runtime-operations"
  retained = data.terraform_remote_state.retained.outputs.retained # 예: 이 루트 모듈에서 모듈까지의 상대 경로 (다섯 단계 위가 저장소 최상위)

  enabled_services                   = var.enabled_services                     # 예: 네 도구 모두 (루트 모듈 기본값)
  expected_account_id                = var.expected_account_id                  # 예: "222222222222" (Prod 계정 번호)
  region                             = var.region                               # 예: "ap-northeast-2" (서울 리전)
  cluster_contract                   = local.cluster_contract                   # 예: eks State 출력으로 조립한 {name, arn, region, kubernetes_version}
  node_group_autoscaling_group_names = local.node_group_autoscaling_group_names # 예: eks State 의 node_contract.autoscaling_group_names (실제 ASG 이름 집합)
  application_log_retention_days     = var.application_log_retention_days       # 예: 90 (허용 목록에 있는 보존 기간)
  alerts_topic_arn                   = local.alerts_topic_arn                   # 예: null (첫 적용) 또는 승인된 alerts_topic_arn 입력
}

# 이 디렉터리는 prod 만 받습니다. input 은 State 에 남는 marker 이며 AWS 자원을 만들지 않습니다.
resource "terraform_data" "environment_boundary" {
  input = var.environment # 예: "prod" (input 변경은 in-place 갱신)

  lifecycle {
    precondition {
      condition     = var.environment == "prod" # 예: "prod" 통과 / "dev" 거부 (dev 는 dev/platform/operations 디렉터리 — 운영 기반 루트 모듈과 계약)
      error_message = "This directory accepts only the prod environment."
    }

    precondition {
      condition     = terraform.workspace == "default" # 예: workspace 로 환경을 나누지 않음 (backend key 로 구분)
      error_message = "Use default workspace and a distinct backend key."
    }
  }
}

# outputs.tf — platform/operations 루트 모듈 (dev · prod 공통 코드)

output "operations_contract" {
  description = "Account, cluster, region, platform log group, backup bucket and alerts topic ARN for native platform configuration and later roots."
  value       = module.component.operations_contract # 공개 필드: (account_id · cluster_name · region · platform_log_group_name · velero_bucket_name · velero_bucket_arn · alerts_topic_arn)
}



# 배포 플랫폼 의 delivery 루트 모듈이 terraform_remote_state 로 읽습니다 (assume-role chaining 의 신뢰 주체).
output "external_secrets_role_arn" {
  description = "IAM role of the cluster-wide External Secrets controller (read by the delivery root)."
  value       = module.component.external_secrets_role_arn # 예: "arn:aws:iam::111111111111:role/contract2whale-dev-eks-external-secrets"
}

output "grafana_secret_name" {
  value       = module.component.grafana_secret_name
  description = "External secret source name only; no credential data."
}

# providers.tf — platform/operations 루트 모듈 (dev · prod 공통 코드)
# 운영 기반 루트 모듈과 계약: AWS API 만 사용합니다. Helm release(Autoscaler · External Secrets · Fluent Bit · Velero)는 승인 GitOps Application을 읽는 Argo CD가 설치하며 Kubernetes provider 는 두지 않습니다.
# 리전은 계약(cluster_contract.region)이 아니라 변수로 받습니다. provider 설정이 State 조회 결과에 의존하지 않게 하고, 모듈의 precondition 이 두 값을 대조합니다.

provider "aws" {
  region              = var.region                # 예: "ap-northeast-2" (서울 리전; cluster_contract.region 과 같아야 함)
  allowed_account_ids = [var.expected_account_id] # 예: ["111111111111"] (다른 계정이면 실행을 거부)

  # 지원되는 AWS 리소스에 공통 분류 태그를 전달합니다. IAM 권한이 아닙니다.
  default_tags {
    tags = {
      ManagedBy   = "Terraform"           # 예: "Terraform" (수동 생성 리소스와 구분)
      Environment = var.environment       # 예: "prod" (환경 구분)
      Component   = "platform-operations" # 예: "platform-operations" (이 루트 모듈이 만든 리소스에 공통으로 붙는 값)
    }
  }
}

# remote-state.tf — platform/operations 루트 모듈 (dev · prod 공통 코드)
# 운영 기반 루트 모듈과 계약: 앞 루트 모듈(eks)의 root 출력을 State 에서 직접 읽습니다 (P1). upstream.auto.tfvars.json 같은 입력 파일을 만들지 않으며, 노드 그룹이 늘면 다음 plan 에 ASG 태그가 자동으로 나타납니다 (D7).
# 경보 토픽 ARN은 기본 null인 공개 입력입니다. 아직 없는 alerting State를 읽지 않으므로 최초 적용과 재개가 순환하지 않습니다.
# 읽는 쪽에는 State 객체의 s3:GetObject 권한이 필요합니다 (관련 구성 의 State 역할 key 목록과 대조: eks/terraform.tfstate).

data "terraform_remote_state" "eks" {
  backend = "s3" # 예: "s3" (앞 루트 모듈이 State 를 둔 방식)

  config = {
    bucket = var.state_bucket_name   # 예: "company-dev-tfstate-111111111111"
    key    = "eks/terraform.tfstate" # 예: eks 루트 모듈의 key (클러스터 입력과 네트워크 계약; 노드와 Add-on 노드 구성도 같은 key)
    region = var.region              # 예: "ap-northeast-2"
  }

  lifecycle {
    # 모듈 계약에 넣을 네 항목이 모두 있어야 합니다 (환경 root 와 모듈 연결 의 cluster_contract 출력).
    postcondition {
      condition = alltrue([
        for name in ["name", "arn", "region", "kubernetes_version"] :
        contains(keys(try(self.outputs.cluster_contract, {})), name) # 예: 4개 모두 cluster_contract 에 존재
      ])
      error_message = "eks state must expose cluster_contract with name, arn, region and kubernetes_version (apply 생성 plan과 private API 검증 first)."
    }

    postcondition {
      condition     = length(try(self.outputs.node_contract.autoscaling_group_names, [])) > 0 # 예: ["eks-contract2whale-dev-eks-system-…"] (노드와 Add-on 시점 1개)
      error_message = "eks state must expose node_contract.autoscaling_group_names with at least one ASG (apply 적용과 배치 실측 first)."
    }
  }
}

data "terraform_remote_state" "retained" {
  backend = "s3"
  config = {
    bucket  = var.state_bucket_name
    key     = "retained/operations/terraform.tfstate"
    region  = var.region
    encrypt = true
  }
}

# variables.tf — platform/operations 루트 모듈 (dev · prod 공통 코드)
# 대신 state_bucket_name 을 받습니다. 원본의 "cat modules/operations/variables.tf > variables.tf" 복사는 쓰지 않습니다 (내용이 다름).

variable "expected_account_id" {
  description = "AWS account that owns the cluster and the operations resources; 12 digits."
  type        = string # 예: string (앞자리 0 이 사라지지 않도록 문자열)
  nullable    = false

  validation {
    condition     = can(regex("^[0-9]{12}$", var.expected_account_id)) # 예: "111111111111" 통과
    error_message = "Account ID must be 12 digits."
  }
}

# 클러스터가 서울 리전에 있으므로 리전도 고정합니다. 모듈은 cluster_contract.region 이 같은 값인지 따로 검사합니다.
variable "region" {
  description = "AWS region for this root; only ap-northeast-2 is supported."
  type        = string
  default     = "ap-northeast-2" # 기본값: "ap-northeast-2"
  nullable    = false

  validation {
    condition     = var.region == "ap-northeast-2" # 예: 단일 값 비교
    error_message = "This root supports ap-northeast-2 only."
  }
}

# main.tf 의 environment_boundary 가 이 디렉터리에서는 "prod" 만 허용합니다.
variable "environment" {
  description = "Explicit environment name, 2-20 lowercase letters, digits or hyphens."
  type        = string
  nullable    = false

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{1,19}$", var.environment)) # 예: "prod" 통과 / "Dev" 거부
    error_message = "Use a 2-20 character lowercase environment name."
  }
}

# 앞 루트 모듈(eks)의 State가 있는 버킷입니다. backend.hcl 의 bucket 과 같은 값입니다.
variable "state_bucket_name" {
  description = "S3 bucket holding the eks state read by terraform_remote_state."
  type        = string # 예: "company-dev-tfstate-111111111111" (work/lab.env 의 DEV_STATE_BUCKET)
  nullable    = false

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$", var.state_bucket_name)) # 예: S3 버킷 이름 규칙
    error_message = "state_bucket_name must be a valid S3 bucket name."
  }
}

# 이 환경이 운영하는 도구 목록입니다. 모듈 기본값은 autoscaler 하나이지만 dev 루트 모듈은 네 도구를 처음부터 모두 켭니다 (D5; 도구별 STEP 0 "AWS 자원 추가" 는 없음).
variable "enabled_services" {
  description = "Operations services whose AWS resources this root declares."
  type        = set(string)
  default     = ["autoscaler", "external_secrets", "fluent_bit", "velero"] # 기본값: 네 도구 모두 (모듈 validation 이 이름을 검사)
  nullable    = false
}

variable "application_log_retention_days" {
  description = "Retention in days for the platform container log group (module validation restricts the allowed values)."
  type        = number
  default     = 90 # 기본값: 90 (모듈 허용 목록 중 하나)
  nullable    = false
}

# 알림 루트의 생성보다 앞서 적용될 수 있으므로 공개 ARN을 선택 입력으로 받습니다.
variable "alerts_topic_arn" {
  description = "Reviewed public SNS topic ARN; null until the alerting root exists."
  type        = string
  default     = null
  nullable    = true
  validation {
    condition     = var.alerts_topic_arn == null ? true : can(regex("^arn:aws:sns:[a-z0-9-]+:[0-9]{12}:[A-Za-z0-9_-]+$", var.alerts_topic_arn))
    error_message = "alerts_topic_arn must be null or an SNS topic ARN."
  }
}

# versions.tf — platform/operations 루트 모듈 (dev · prod 공통 코드)
# 운영 기반 루트 모듈과 계약: Terraform 과 provider 버전을 고정합니다. backend 선언은 backend.tf 에, 모듈 버전은 modules/operations/versions.tf 에 있습니다.

terraform {
  required_version = "= 1.16.0" # 예: "= 1.16.0" (등호로 정확한 버전 고정)

  required_providers {
    aws = {
      source  = "hashicorp/aws" # 예: "hashicorp/aws" (공식 레지스트리 경로)
      version = "= 6.62.0"      # 예: "= 6.62.0" (모듈과 같은 값)
    }
  }
}

terraform/environments/prod/platform/ope.modules/runtime-operations/main.tf:
# main.tf — modules/operations (dev · prod 루트 모듈이 공유하는 모듈)
# Controller 신원과 저장소: 도구 선택(identities) · 백업 버킷 이름 · ASG 탐색 태그 조합을 계산하고, 플랫폼 로그 그룹 · 시크릿 메타데이터 · ASG 탐색 태그를 선언합니다 (리소스 3종).
# 로그 그룹 주소는 원본과 같이 aws_cloudwatch_log_group.platform 입니다 (application 이 아님). 앱 컨테이너 로그는 이 그룹으로 보내지 않습니다 (관측 파이프라인 수집 경로).

locals {
  # for_each 키가 Terraform 리소스 주소가 됩니다. 키를 바꾸면 Role · 연결이 삭제 후 재생성됩니다.
  all_identities = {
    fluent_bit       = { namespace = "logging", service_account = "fluent-bit" }                # 예: 플랫폼 컨테이너 로그 수집
    autoscaler       = { namespace = "kube-system", service_account = "cluster-autoscaler" }    # 예: 노드 수 자동 조절
    external_secrets = { namespace = "external-secrets", service_account = "external-secrets" } # 예: 시크릿 동기화
    velero           = { namespace = "velero", service_account = "velero" }                     # 예: 백업 · 복구
  }

  identities = { for name, identity in local.all_identities : name => identity if contains(var.enabled_services, name) }

  # 예: "velero-contract2whale-dev-eks-111111111111-ap-northeast-2" (57자, S3 이름 한도 63자 이내 — providers.tf 계약 검사가 확인)
  backup_bucket_name = "velero-${var.cluster_contract.name}-${var.expected_account_id}-${var.region}"

  asg_discovery_tags = {
    "k8s.io/cluster-autoscaler/enabled"                      = "true"  # 예: 자동 확장 대상 그룹 표시
    "k8s.io/cluster-autoscaler/${var.cluster_contract.name}" = "owned" # 예: 이 클러스터 소유 그룹 표시
  }

  # setproduct(ASG 이름 집합, 태그 키 집합) 조합마다 "<ASG 이름>:<태그 키>" 고유 키를 만듭니다.
  asg_tags = {
    for pair in setproduct(var.node_group_autoscaling_group_names, toset(keys(local.asg_discovery_tags))) :
    "${pair[0]}:${pair[1]}" => { asg = pair[0], key = pair[1], value = local.asg_discovery_tags[pair[1]] }
  }
}

# 로그 그룹의 수명 · 보존 기간은 Terraform 이, 로그 stream · event 는 Fluent Bit 가 소유합니다.
resource "aws_cloudwatch_log_group" "platform" {
  count = contains(var.enabled_services, "fluent_bit") ? 1 : 0 # 예: fluent_bit 을 켠 경우에만 1개

  name              = "/platform/${var.cluster_contract.name}/application" # 예: "/platform/contract2whale-dev-eks/application"
  retention_in_days = var.application_log_retention_days                   # 예: 90
  skip_destroy      = false                                                # 예: false (실습 삭제 시 로그 그룹도 삭제)

  depends_on = [terraform_data.contract] # 예: 계약 검사 통과 후 생성
}



resource "aws_autoscaling_group_tag" "discovery" {
  for_each = local.asg_tags # 예: 필드 계약 ("<ASG 이름>:<태그 키>")

  autoscaling_group_name = each.value.asg # 예: "eks-contract2whale-dev-eks-system-0ac12345-..."

  tag {
    key                 = each.value.key   # 예: "k8s.io/cluster-autoscaler/enabled"
    value               = each.value.value # 예: "true"
    propagate_at_launch = false            # 예: false (새 인스턴스에 복사하지 않음)
  }

  depends_on = [terraform_data.contract] # 예: 계약 검사 통과 후 생성
}

terraform/environments/prod/platform/ope.modules/runtime-operations/outputs.tf:
# outputs.tf — modules/operations (dev · prod 루트 모듈이 공유하는 모듈)
# 계약 필드 하나(alerts_topic_arn)에만 쓰이는 입력을 같은 파일에 선언합니다 (원본 배치 유지). 경보 토픽는 알림 루트 모듈(알림 루트 모듈과 설치 검사)이 만들고 이 계약은 그 ARN 을 실어 나르기만 합니다.

variable "alerts_topic_arn" {
  description = "알림 구성이 만든 경보 토픽의 ARN 입니다. 토픽을 만들기 전에는 null 입니다."
  type        = string # 예: string (ARN 을 문자열로 받습니다)
  default     = null   # 예: null (경보 토픽를 아직 만들지 않은 상태; 루트 모듈은 검토한 공개 입력으로 전달)

  validation {
    # 예: null 통과, "arn:aws:sns:ap-northeast-2:111111111111:contract2whale-dev-alerts" 통과, "contract2whale-dev-alerts" 거부
    condition     = var.alerts_topic_arn == null ? true : can(regex("^arn:aws:sns:[a-z0-9-]+:[0-9]{12}:[A-Za-z0-9_-]+$", var.alerts_topic_arn))
    error_message = "경보 토픽 ARN 형식이 필요합니다."
  }
}

output "operations_contract" {
  description = "Account, cluster, region, log group, backup bucket and alerts topic that native platform configuration and later roots (관측 파이프라인 · 계정 통합 · 운영 환경) read; no secret values."
  value = {
    account_id              = var.expected_account_id                              # 예: "111111111111"
    cluster_name            = var.cluster_contract.name                            # 예: "contract2whale-dev-eks" (앞 클러스터 계약의 name)
    region                  = var.region                                           # 예: "ap-northeast-2"
    platform_log_group_name = try(aws_cloudwatch_log_group.platform[0].name, null) # 예: "/platform/contract2whale-dev-eks/application" (fluent_bit 을 끄면 null)
    velero_bucket_name      = try(var.retained.aws_s3_bucket__velero[0].id, null)  # 예: "velero-contract2whale-dev-eks-111111111111-ap-northeast-2" (velero 를 끄면 null)
    velero_bucket_arn       = try(var.retained.aws_s3_bucket__velero[0].arn, null) # 예: "arn:aws:s3:::velero-contract2whale-dev-eks-111111111111-ap-northeast-2"
    alerts_topic_arn        = var.alerts_topic_arn                                 # 예: "arn:aws:sns:ap-northeast-2:111111111111:contract2whale-dev-alerts" 또는 null (첫 적용)
  }
}

output "grafana_secret_name" {
  description = "Secrets Manager secret name that External Secrets syncs into monitoring/grafana-admin; null when external_secrets is disabled."
  value       = try(var.retained.aws_secretsmanager_secret__grafana[0].name, null) # 예: "contract2whale-dev-eks/platform/grafana-admin"
}

# 배포 플랫폼이 assume-role chaining 으로 쓰는 값입니다: 클러스터 전체 External Secrets controller 의 Role. delivery 의 시크릿 읽기 Role 이 이 Role 만 신뢰합니다 (SecretStore spec.provider.aws.role).
output "external_secrets_role_arn" {
  description = "IAM role of the cluster-wide External Secrets controller; downstream SecretStores chain to their own read-only roles from it (null when external_secrets is disabled)."
  value       = try(aws_iam_role.controller["external_secrets"].arn, null) # 예: "arn:aws:iam::111111111111:role/contract2whale-dev-eks-external-secrets"
}

# pod-identity.tf — modules/operations (dev · prod 루트 모듈이 공유하는 모듈)

resource "aws_iam_role" "controller" {
  for_each = local.identities                                              # 예: 필드 계약 (enabled_services 로 걸러진 controller)
  name     = "${var.cluster_contract.name}-${replace(each.key, "_", "-")}" # 예: "contract2whale-dev-eks-fluent-bit"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "pods.eks.amazonaws.com" } # 예: EKS Pod Identity 서비스 주체만 허용
      Action    = ["sts:AssumeRole", "sts:TagSession"]   # 예: 역할 사용 + 세션 태그 부착
      Condition = {
        StringEquals = {
          "aws:RequestTag/eks-cluster-arn"            = var.cluster_contract.arn   # 예: 이 클러스터에서 발급된 세션만
          "aws:RequestTag/kubernetes-namespace"       = each.value.namespace       # 예: "logging"
          "aws:RequestTag/kubernetes-service-account" = each.value.service_account # 예: "fluent-bit"
        }
      }
    }]
  })

  depends_on = [terraform_data.contract] # 예: 계약 검사 통과 후 생성
}

resource "aws_iam_role_policy" "controller" {
  for_each = local.identities                                # 예: Role 과 같은 키
  name     = "controller-permissions"                        # 예: Role 마다 같은 이름 (소속 Role 이 달라 충돌 없음)
  role     = aws_iam_role.controller[each.key].id            # 예: 같은 키의 Role
  policy   = jsonencode(local.controller_policies[each.key]) # 예: 해당 controller 의 정책만 선택
}

resource "aws_eks_pod_identity_association" "controller" {
  for_each = local.identities # 예: Role 과 같은 키

  cluster_name         = var.cluster_contract.name             # 예: "contract2whale-dev-eks"
  namespace            = each.value.namespace                  # 예: "external-secrets"
  service_account      = each.value.service_account            # 예: "external-secrets"
  role_arn             = aws_iam_role.controller[each.key].arn # 예: "arn:aws:iam::111111111111:role/contract2whale-dev-eks-external-secrets"
  disable_session_tags = false                                 # 예: false (세션 태그가 있어야 신뢰 정책 조건이 성립)

  # IAM 반영 지연까지 보장하지는 않지만, 정책 부착 이후에 연결하도록 생성 순서를 고정합니다.
  depends_on = [aws_iam_role_policy.controller]
}

locals {
  controller_policies = {
    fluent_bit = {
      Version = "2012-10-17"
      Statement = [{
        Effect   = "Allow"
        Action   = ["logs:CreateLogStream", "logs:PutLogEvents", "logs:DescribeLogStreams"] # 예: 스트림 생성 · 기록 · 조회
        Resource = "${try(aws_cloudwatch_log_group.platform[0].arn, "inactive")}:*"         # 예: 플랫폼 로그 그룹의 스트림만
      }]
    }

    autoscaler = {
      Version = "2012-10-17"
      Statement = [
        {
          Effect = "Allow"
          Action = [
            "autoscaling:SetDesiredCapacity",                  # 예: 유지하려는 노드 수 변경
            "autoscaling:TerminateInstanceInAutoScalingGroup", # 예: 그룹 안 인스턴스 종료
          ]
          Resource = "*" # 예: 아래 태그 조건으로 대상 ASG 를 좁힘
          Condition = {
            StringEquals = {
              "aws:ResourceTag/k8s.io/cluster-autoscaler/enabled"                      = "true"  # 예: 탐색 태그가 있는 ASG
              "aws:ResourceTag/k8s.io/cluster-autoscaler/${var.cluster_contract.name}" = "owned" # 예: 이 클러스터 소유 ASG
            }
          }
        },
        {
          Effect = "Allow"
          Action = [
            "autoscaling:DescribeAutoScalingGroups",
            "autoscaling:DescribeAutoScalingInstances",
            "autoscaling:DescribeLaunchConfigurations",
            "autoscaling:DescribeScalingActivities",
            "autoscaling:DescribeTags",
            "ec2:DescribeImages",
            "ec2:DescribeInstanceTypes",
            "ec2:DescribeLaunchTemplateVersions",
            "ec2:GetInstanceTypesFromInstanceRequirements",
            "eks:DescribeNodegroup",
          ]
          Resource = "*" # 예: 조회 전용 동작
        },
      ]
    }

    external_secrets = {
      Version = "2012-10-17"
      Statement = [{
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret",
          "secretsmanager:GetResourcePolicy",
          "secretsmanager:ListSecretVersionIds",
        ]
        Resource = try(var.retained.aws_secretsmanager_secret__grafana[0].arn, null) # 예: 대시보드 초기 시크릿 1개만
      }]
    }

    velero = {
      Version = "2012-10-17"
      Statement = [
        {
          # The completed course checkpoint survives Velero TTL GC after Down/Up.
          # Scope is this one lab backup; ordinary production retention needs its approved process.
          Sid      = "RetainCourseCheckpointObjects"
          Effect   = "Deny"
          Action   = ["s3:DeleteObject", "s3:DeleteObjectVersion"]
          Resource = "${try(var.retained.aws_s3_bucket__velero[0].arn, "inactive")}/backups/backups/platform-storage-probe/*"
        },
        {
          Sid      = "RetainCourseCheckpointSnapshots"
          Effect   = "Deny"
          Action   = ["ec2:DeleteSnapshot"]
          Resource = "arn:aws:ec2:${var.region}:${var.expected_account_id}:snapshot/*"
          Condition = {
            StringEquals = {
              "ec2:ResourceTag/velero.io/backup" = "platform-storage-probe"
            }
          }
        },
        {
          # Describe는 목록 조회입니다. 변경 권한과 분리하여 검토합니다.
          Effect    = "Allow"
          Action    = ["ec2:DescribeVolumes", "ec2:DescribeSnapshots"]
          Resource  = "*"
          Condition = { StringEquals = { "aws:RequestedRegion" = var.region } }
        },
        {
          # 기존 변경 권한의 검토용 기준선입니다. 모든 action이 ARN 제한 불가라는 뜻이 아닙니다.
          # 고정 AWS plugin의 생성 태그/호출 순서와 action별 지원표 검증 전 실제 배포는 중단합니다.
          # DeleteSnapshot/CreateTags/CreateVolume/CreateSnapshot 대상·태그 범위 시험 후 확정합니다.
          Effect = "Allow"
          Action = [
            "ec2:CreateTags",
            "ec2:CreateVolume",
            "ec2:CreateSnapshot",
            "ec2:DeleteSnapshot",
          ]
          Resource  = "*"
          Condition = { StringEquals = { "aws:RequestedRegion" = var.region } } # 예: "ap-northeast-2" 안에서만
        },
        {
          Effect   = "Allow"
          Action   = ["s3:ListBucket"]
          Resource = try(var.retained.aws_s3_bucket__velero[0].arn, null) # 예: 백업 버킷 자체
        },
        {
          # s3:PutObjectTagging 은 없습니다 — Velero values 의 backupStorageLocation.config.tagging 을 켜면 이 문장도 함께 바꿉니다.
          Effect = "Allow"
          Action = [
            "s3:GetObject",
            "s3:DeleteObject",
            "s3:PutObject",
            "s3:AbortMultipartUpload",
            "s3:ListMultipartUploadParts",
          ]
          Resource = "${try(var.retained.aws_s3_bucket__velero[0].arn, "inactive")}/*" # 예: 백업 버킷 안의 객체만
        },
      ]
    }
  }
}

terraform/environments/prod/platform/ope.modules/runtime-operations/providers.tf:
# providers.tf — modules/operations (dev · prod 루트 모듈이 공유하는 모듈)
# Controller 신원과 저장소: 이 모듈은 provider 블록을 선언하지 않습니다. 계정 · 리전은 운영 기반 루트 모듈과 계약 루트 모듈의 provider 가 결정합니다.
# terraform_data.contract 는 AWS 리소스를 만들지 않고, 잘못된 workspace · 계약 조합을 plan 단계에서 차단합니다 (모든 리소스가 depends_on 으로 이 검사를 기다림).

resource "terraform_data" "contract" {
  input = var.cluster_contract.arn # 예: "arn:aws:eks:ap-northeast-2:111111111111:cluster/contract2whale-dev-eks"

  lifecycle {
    precondition {
      condition     = terraform.workspace == "default" # 예: default workspace 에서만 통과
      error_message = "default workspace와 운영 기반 전용 state key를 사용하세요."
    }

    precondition {
      condition = (
        var.cluster_contract.arn == "arn:aws:eks:${var.region}:${var.expected_account_id}:cluster/${var.cluster_contract.name}" && # 예: 계약 ARN 을 리전 · 계정 · 이름으로 다시 조립해 비교
        var.cluster_contract.region == var.region &&                                                                               # 예: 계약 리전 = 입력 리전
        var.cluster_contract.kubernetes_version == "1.36" &&                                                                       # 예: 과정 고정 버전 (클러스터 업그레이드 시 함께 수정)
        (!contains(var.enabled_services, "velero") || length(local.backup_bucket_name) <= 63)                                      # 예: 백업 버킷 이름은 S3 한도 63자 이내 (과정 이름 22자 → 57자)
      )
      error_message = "앞 구성의 실제 cluster 계약의 계정/리전/이름, Kubernetes 1.36, 백업 버킷 이름 63자 이내를 확인하세요."
    }
  }
}

terraform/environments/prod/platform/ope.modules/runtime-operations/retained-inpu:
variable "retained" {
  description = "Verified outputs from the independently retained root; immutable IDs, never whole State."
  type        = any
}

terraform/environments/prod/platform/ope.modules/runtime-operations/variables.tf:
# variables.tf — modules/operations (dev · prod 루트 모듈이 공유하는 모듈)

variable "enabled_services" {
  description = "AWS 리소스를 선언할 운영 도구 목록입니다."
  type        = set(string)
  default     = ["autoscaler"] # 기본값: autoscaler 하나 (운영 기반 루트 모듈과 계약 루트 모듈은 네 도구를 모두 전달)

  validation {
    condition     = alltrue([for name in var.enabled_services : contains(["autoscaler", "external_secrets", "fluent_bit", "velero"], name)]) # 예: "karpenter" 거부
    error_message = "Select only the operations services built in this root."
  }
}

variable "expected_account_id" {
  description = "실습 리소스를 관리할 실제 AWS 계정 ID입니다."
  type        = string # 예: "111111111111"

  validation {
    condition     = can(regex("^[0-9]{12}$", var.expected_account_id)) # 예: 숫자 12자리만 통과
    error_message = "12자리 AWS 계정 번호가 필요합니다."
  }
}

variable "region" {
  description = "운영 리소스를 만들 리전입니다. cluster_contract.region 과 같아야 합니다."
  type        = string
  default     = "ap-northeast-2" # 기본값: 서울 리전
}

variable "cluster_contract" {
  description = "EKS 루트 모듈의 cluster_contract 출력입니다. 아래 네 필드만 받고 나머지 필드는 타입 변환에서 제외됩니다."
  type = object({
    name               = string # 예: "contract2whale-dev-eks"
    arn                = string # 예: "arn:aws:eks:ap-northeast-2:111111111111:cluster/contract2whale-dev-eks"
    region             = string # 예: "ap-northeast-2"
    kubernetes_version = string # 예: "1.36"
  })

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{1,98}[a-z0-9]$", var.cluster_contract.name)) # 예: 소문자 DNS 형식 3~100자 (EKS 클러스터 이름 한도; 백업 버킷 이름 길이는 providers.tf 계약 검사)
    error_message = "클러스터 이름은 소문자 DNS 형식 3~100자여야 합니다."
  }
}

variable "node_group_autoscaling_group_names" {
  description = "EKS 루트 모듈이 출력한 관리형 노드 그룹의 ASG 이름 집합입니다. AWS 가 정한 이름이므로 추측해 입력하지 않습니다."
  type        = set(string) # 예: ["eks-contract2whale-dev-eks-system-0ac12345-..."] (운영 기반 루트 모듈과 계약 루트 모듈이 eks State 의 node_contract.autoscaling_group_names 를 전달)

  validation {
    condition     = length(var.node_group_autoscaling_group_names) > 0 && alltrue([for n in var.node_group_autoscaling_group_names : length(n) > 0]) # 예: [] 거부
    error_message = "최소 하나의 실제 ASG 이름이 필요합니다."
  }
}

variable "application_log_retention_days" {
  description = "플랫폼 컨테이너 로그 그룹의 보존 일수입니다. 앱 로그의 보존 일수가 아닙니다."
  type        = number
  default     = 90 # 기본값: 90일

  validation {
    condition     = contains([7, 14, 30, 60, 90, 120, 150, 180, 365], var.application_log_retention_days) # 예: 90 통과 / 45 거부
    error_message = "문서에서 지원하는 CloudWatch 보존 일수 중 하나를 선택하세요."
  }
}

terraform/environments/prod/platform/ope.modules/runtime-operations/versions.tf:
# versions.tf — modules/operations (dev · prod 루트 모듈이 공유하는 모듈)
# Controller 신원과 저장소: 운영 도구 4종(Cluster Autoscaler · External Secrets · Fluent Bit · Velero)의 AWS 리소스만 Terraform 으로 관리합니다. Helm · Kubernetes provider 는 사용하지 않습니다.
# 과정 내부 전용 모듈이라 루트 모듈과 같은 값을 등호로 고정합니다 (P7). provider 블록은 두지 않습니다 (인증 · 리전 · default_tags 는 루트 모듈의 providers.tf 가 담당).

terraform {
  required_version = "= 1.16.0" # 예: "= 1.16.0" (도구 저장소 tool-versions 고정값과 동일)

  required_providers {
    aws = {
      source  = "hashicorp/aws" # 예: "hashicorp/aws" (공식 레지스트리 경로)
      version = "= 6.62.0"      # 예: "= 6.62.0" (과정 전체의 provider 고정값)
    }
  }
}

terraform/environments/prod/platform/obs.terraform/environments/prod/platform/obs:
# backend.tf — platform/observability 루트 모듈 (dev · prod 공통 코드)
# 관측 루트 모듈과 계약: backend 인자는 커밋하지 않는 backend.hcl 이 제공합니다 (terraform init -input=false -backend-config=backend.hcl). key 는 platform/observability/terraform.tfstate (P2).

terraform {
  backend "s3" {}
}

# locals.tf — platform/observability 루트 모듈 (dev · prod 공통 코드)
# 관측 루트 모듈과 계약: State 에서 읽은 출력을 모듈 입력 모양으로 조립합니다. 다섯 값 모두 이 루트 모듈이 직접 입력받지 않습니다.

locals {
  # modules/observability-foundation 의 cluster_contract 객체입니다. eks State 의 12개 항목 중 네 항목만 골라 계약 모양을 명시합니다.
  cluster_contract = {
    name               = data.terraform_remote_state.eks.outputs.cluster_contract.name               # 예: "contract2whale-prod-eks"
    arn                = data.terraform_remote_state.eks.outputs.cluster_contract.arn                # 예: "arn:aws:eks:ap-northeast-2:222222222222:cluster/contract2whale-prod-eks"
    region             = data.terraform_remote_state.eks.outputs.cluster_contract.region             # 예: "ap-northeast-2"
    kubernetes_version = data.terraform_remote_state.eks.outputs.cluster_contract.kubernetes_version # 예: "1.36"
  }

  # platform/operations State 의 operations_contract 7항목을 그대로 넘깁니다 (모듈이 계정 · 리전 · 클러스터 · 로그 그룹을 대조).
  operations_contract = data.terraform_remote_state.operations.outputs.operations_contract # 예: { account_id = "222222222222", cluster_name = "contract2whale-prod-eks", … }

  vpc_id                   = data.terraform_remote_state.vpc.outputs.vpc_id                         # 예: "vpc-0123456789abcdef0" (vpc 출력)
  network_logs_bucket_name = data.terraform_remote_state.vpc.outputs.network_logs_bucket_name       # 예: "cp-prod-network-logs-222222222222-ap-northeast-2" (네트워크 로그 수집 출력)
  allowed_state_keys       = data.terraform_remote_state.account_baseline.outputs.state_object_keys # 예: ["account-baseline/terraform.tfstate", …, "platform/observability/terraform.tfstate"] (account-baseline 출력)
}

# main.tf — platform/observability 루트 모듈 (dev · prod 공통 코드)
# 관측 루트 모듈과 계약: 환경별 입력은 루트 모듈, 재사용 리소스는 모듈에서 관리합니다. module "component" 로 변수 15개를 전달하고(pod_identities 는 모듈 기본값) 환경 경계 1개를 둡니다.
# 적용 결과(prod): 역할 3 · 정책 3 · 연결 3 · 저장소 3 · 보호 18 · Pod Identity 9 · 엔드포인트 정책 1 · 계약 검사 2 = 42 리소스 (mock plan 실측은 사양 참고).

module "component" {
  source   = "../../../../../modules/runtime-observability-foundation"
  retained = data.terraform_remote_state.retained.outputs.retained # 예: 이 루트 모듈에서 모듈까지의 상대 경로 (다섯 단계 위가 저장소 최상위)

  expected_account_id      = var.expected_account_id        # 예: "222222222222"
  region                   = var.region                     # 예: "ap-northeast-2"
  environment              = var.environment                # 예: "prod"
  cluster_contract         = local.cluster_contract         # 예: eks State 출력으로 조립한 {name, arn, region, kubernetes_version}
  trusted_principal_arns   = var.trusted_principal_arns     # 예: ["arn:aws:iam::222222222222:role/…"] (Account Baseline 역할의 점검용 신뢰 주체)
  permissions_boundary_arn = var.permissions_boundary_arn   # 예: null
  allowed_state_keys       = local.allowed_state_keys       # 예: account-baseline State 의 state_object_keys (계정 보안 기반)
  operations_contract      = local.operations_contract      # 예: platform/operations State 의 계약 7항목
  signal_retention_days    = var.signal_retention_days      # 예: { metrics = 400, logs = 90, traces = 40 }
  vpc_id                   = local.vpc_id                   # 예: "vpc-0123456789abcdef0" (VPC 엔드포인트 조회)
  network_logs_bucket_name = local.network_logs_bucket_name # 예: "cp-prod-network-logs-…" (S3 엔드포인트 허용 목록)
  active_trace_backend     = var.active_trace_backend       # 예: "managed"
  storage_epoch            = var.storage_epoch              # 예: 1
  policy_version           = var.policy_version             # 예: 1
  additional_bucket_names  = var.additional_bucket_names    # 예: [] (data · production 가 미디어 버킷을 더함)
  # pod_identities 는 모듈 기본값 9개를 그대로 씁니다 (Prod Core 와 Gateway 기반~Prod 운영 도구 · 후반부 해당 운영 주제 의 ServiceAccount 이름).
}

# 이 디렉터리는 prod 만 받습니다. input 은 State 에 남는 marker 이며 AWS 자원을 만들지 않습니다.
resource "terraform_data" "environment_boundary" {
  input = var.environment # 예: "prod"

  lifecycle {
    precondition {
      condition     = var.environment == "prod" # 예: "prod" 통과 / "dev" 거부 (dev 는 dev/platform/observability 디렉터리 — 관측 루트 모듈과 계약)
      error_message = "This directory accepts only the prod environment."
    }

    precondition {
      condition     = terraform.workspace == "default" # 예: workspace 로 환경을 나누지 않음 (backend key 로 구분)
      error_message = "Use default workspace and a distinct backend key."
    }
  }
}

# outputs.tf — platform/observability 루트 모듈 (dev · prod 공통 코드)

output "observability_contract" {
  description = "Account, region, cluster, namespaces, service accounts, roles, buckets, retention, query endpoints, trace backend state and policy hash (17 keys)."
  value       = module.component.observability_contract
}

output "observability_network_contract" {
  description = "S3 gateway endpoint id, allowed bucket names and endpoint policy mode (private storage endpoint)."
  value       = module.component.observability_network_contract # 예: { s3_endpoint_id = "vpce-…", allowed_bucket_prefixes = [5개], endpoint_policy_mode = "restricted" }
}

output "signal_bucket_names" {
  description = "Bucket name per signal."
  value       = module.component.signal_bucket_names # 예: { metrics = "cp-dev-observability-metrics-…", logs = "…", traces = "…" }
}

output "storage_role_arns" {
  description = "Writer, reader and maintenance role ARNs."
  value       = module.component.storage_role_arns # 예: { writer = "…", reader = "…", maintenance = "…" }
}

output "pod_identity_association_ids" {
  description = "Association ID per pod identity key."
  value       = module.component.pod_identity_association_ids # 예: 신원 9개의 연결 식별자
}



output "platform_input_values" {
  description = "Typed noncredential storage settings for native platform inputs; never credentials."
  value = {
    metrics_bucket      = module.component.observability_contract.metrics_bucket
    logs_bucket         = module.component.observability_contract.logs_bucket
    traces_bucket       = module.component.observability_contract.traces_bucket
    region              = var.region
    s3_endpoint         = "s3.${var.region}.amazonaws.com"
    metrics_prefix      = "${module.component.signal_object_prefixes.metrics}metrics"
    trace_prefix        = "${module.component.signal_object_prefixes.traces}traces"
    trace_epoch2_prefix = "${module.component.signal_object_prefixes.traces}traces-epoch-2"
    trace_epoch3_prefix = "${module.component.signal_object_prefixes.traces}traces-epoch-3"
    cluster_name        = module.component.observability_contract.cluster
    prometheus_endpoint = module.component.observability_contract.prometheus_endpoint
    loki_endpoint       = module.component.observability_contract.loki_endpoint
    tempo_endpoint      = module.component.observability_contract.tempo_endpoint
  }
}

output "signal_object_prefixes" {
  value = module.component.signal_object_prefixes
}

# providers.tf — platform/observability 루트 모듈 (dev · prod 공통 코드)
# 관측 루트 모듈과 계약: AWS API 만 사용합니다. Prometheus·Thanos·Loki·정책은 승인된 Git source를 Argo CD가 동기화하며 Kubernetes provider는 두지 않습니다.
# 리전은 계약(cluster_contract.region)이 아니라 변수로 받습니다. provider 설정이 State 조회 결과에 의존하지 않게 하고, 변수 validation 과 모듈 validation 이 둘 다 ap-northeast-2 로 고정합니다.

provider "aws" {
  region              = var.region                # 예: "ap-northeast-2" (서울 리전; cluster_contract.region 과 같아야 함)
  allowed_account_ids = [var.expected_account_id] # 예: ["222222222222"] (다른 계정이면 실행을 거부)

  # 지원되는 AWS 리소스에 공통 분류 태그를 전달합니다. IAM 권한이 아닙니다.
  default_tags {
    tags = {
      ManagedBy   = "Terraform"              # 예: "Terraform" (수동 생성 리소스와 구분)
      Environment = var.environment          # 예: "prod" (환경 구분)
      Component   = "platform-observability" # 예: "platform-observability" (이 루트 모듈이 만든 리소스에 공통으로 붙는 값)
    }
  }
}

# remote-state.tf — platform/observability 루트 모듈 (dev · prod 공통 코드)
# 관측 루트 모듈과 계약: 앞 루트 모듈 4곳(eks · platform/operations · network/vpc · account-baseline)의 root 출력을 State 에서 직접 읽습니다. upstream.auto.tfvars.json 같은 입력 파일을 만들지 않습니다 (P1).
# 읽는 쪽에는 State 객체 전체의 s3:GetObject 권한이 필요합니다 (account-baseline 의 State 역할 key 목록과 대조).

# eks-control-plane · eks-nodes 의 EKS 루트 모듈입니다. locals.tf 가 cluster_contract 12개 항목 중 name · arn · region · kubernetes_version 만 모듈 입력으로 넘깁니다.
data "terraform_remote_state" "eks" {
  backend = "s3" # 예: "s3" (앞 루트 모듈이 State 를 둔 방식)

  config = {
    bucket = var.state_bucket_name   # 예: "company-prod-tfstate-222222222222"
    key    = "eks/terraform.tfstate" # 예: eks 루트 모듈의 key (클러스터 입력과 네트워크 계약; eks-nodes 노드 구성 · 관측 노드 그룹과 taint 관측 노드 그룹도 같은 key)
    region = var.region              # 예: "ap-northeast-2"
  }

  lifecycle {
    postcondition {
      condition = alltrue([
        for name in ["name", "arn", "region", "kubernetes_version"] :
        contains(keys(try(self.outputs.cluster_contract, {})), name) # 예: 4개 모두 cluster_contract 에 존재
      ])
      error_message = "eks state must expose cluster_contract with name, arn, region and kubernetes_version (apply 생성 plan과 private API 검증 first)."
    }
  }
}

# 운영 기반 루트 모듈과 계약 의 운영 기반 루트 모듈입니다. operations_contract 7항목을 모듈이 대조하고, velero 버킷 이름을 엔드포인트 허용 목록에 넣습니다.
data "terraform_remote_state" "operations" {
  backend = "s3" # 예: "s3"

  config = {
    bucket = var.state_bucket_name                   # 예: "company-prod-tfstate-222222222222" (같은 버킷)
    key    = "platform/operations/terraform.tfstate" # 예: platform/operations 루트 모듈의 key (운영 기반 루트 모듈과 계약)
    region = var.region                              # 예: "ap-northeast-2"
  }

  lifecycle {
    postcondition {
      condition = alltrue([
        for name in ["account_id", "cluster_name", "region", "platform_log_group_name", "velero_bucket_name", "velero_bucket_arn", "alerts_topic_arn"] :
        contains(keys(try(self.outputs.operations_contract, {})), name) # 예: 7개 모두 operations_contract 에 존재
      ])
      error_message = "platform/operations state must expose operations_contract with its seven fields (apply 운영 기반 루트 모듈과 계약 first)."
    }
  }
}

# vpc · eks-network 워크로드 VPC 루트 모듈입니다. S3 Gateway 엔드포인트 조회에 vpc_id 를, 엔드포인트 허용 목록에 네트워크 로그 버킷 이름을 씁니다 (해당 운영 주제).
data "terraform_remote_state" "vpc" {
  backend = "s3" # 예: "s3"

  config = {
    bucket = var.state_bucket_name           # 예: "company-prod-tfstate-222222222222"
    key    = "network/vpc/terraform.tfstate" # 예: network/vpc 루트 모듈의 key
    region = var.region                      # 예: "ap-northeast-2"
  }

  lifecycle {
    postcondition {
      condition     = try(self.outputs.vpc_id != null && self.outputs.network_logs_bucket_name != null, false) # 예: "vpc-…" · "cp-prod-network-logs-…"
      error_message = "network/vpc state must expose vpc_id and network_logs_bucket_name (apply 네트워크 로그 수집 first)."
    }
  }
}

# 두 계정의 State 역할과 최소 객체 권한 의 계정 기준 루트 모듈입니다. State 역할의 허용 key 목록(state_object_keys)에 이 루트 모듈의 key 가 있는지 모듈이 대조합니다 (해당 운영 주제).
data "terraform_remote_state" "account_baseline" {
  backend = "s3" # 예: "s3"

  config = {
    bucket = var.state_bucket_name                # 예: "company-prod-tfstate-222222222222"
    key    = "account-baseline/terraform.tfstate" # 예: account-baseline 루트 모듈의 key (account-baseline)
    region = var.region                           # 예: "ap-northeast-2"
  }

  lifecycle {
    postcondition {
      condition     = try(length(self.outputs.state_object_keys) >= 3, false) # 예: 기본 key 3개 이상 (account-baseline locals.state_object_keys)
      error_message = "account-baseline state must expose state_object_keys (apply 두 계정의 State 역할과 최소 객체 권한 first)."
    }
  }
}

data "terraform_remote_state" "retained" {
  backend = "s3"
  config = {
    bucket  = var.state_bucket_name
    key     = "retained/observability-foundation/terraform.tfstate"
    region  = var.region
    encrypt = true
  }
}

# variables.tf — platform/observability 루트 모듈 (dev · prod 공통 코드)
# 관측 루트 모듈과 계약: 루트 모듈 입력 11개입니다. 모듈 변수 16개 중 cluster_contract · operations_contract · allowed_state_keys · vpc_id · network_logs_bucket_name 은 remote-state.tf 가 State 4곳에서 읽으므로 받지 않고,
# 대신 state_bucket_name 을 받습니다. 나머지(계정 · 리전 · 환경 · 신뢰 주체 · boundary · 보존일 · 계약 값 3개 · 엔드포인트 추가 저장소)는 모듈과 같은 검사식으로 그대로 전달합니다. 값은 terraform.tfvars(비커밋; terraform.tfvars.example 복사)로 받습니다.

variable "expected_account_id" {
  description = "AWS account that owns the cluster and the signal buckets; 12 digits."
  type        = string # 예: string (앞자리 0 이 사라지지 않도록 문자열)
  nullable    = false

  validation {
    condition     = can(regex("^[0-9]{12}$", var.expected_account_id)) # 예: "222222222222" 통과
    error_message = "Account ID must be 12 digits."
  }
}

variable "region" {
  description = "AWS region for this root; only ap-northeast-2 is supported."
  type        = string
  default     = "ap-northeast-2" # 기본값: "ap-northeast-2"
  nullable    = false

  validation {
    condition     = var.region == "ap-northeast-2" # 예: 단일 값 비교
    error_message = "This root supports ap-northeast-2 only."
  }
}

# main.tf 의 environment_boundary 가 이 디렉터리에서는 "prod" 만 허용합니다.
variable "environment" {
  description = "Explicit environment name; this directory accepts prod only."
  type        = string
  nullable    = false

  validation {
    condition     = contains(["dev", "prod"], var.environment) # 예: "dev" 통과 / "stage" 거부 (모듈과 같은 검사)
    error_message = "environment must be dev or prod."
  }
}

# 앞 루트 모듈 4곳(eks · platform/operations · network/vpc · account-baseline)의 State 가 있는 버킷입니다. backend.hcl 의 bucket 과 같은 값입니다.
variable "state_bucket_name" {
  description = "S3 bucket holding the eks, platform/operations, network/vpc and account-baseline states read by terraform_remote_state."
  type        = string # 예: "company-prod-tfstate-222222222222" (work/lab.env 의 PROD_STATE_BUCKET)
  nullable    = false

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$", var.state_bucket_name)) # 예: S3 버킷 이름 규칙
    error_message = "state_bucket_name must be a valid S3 bucket name."
  }
}

# 저장소 역할 3개를 점검용으로 맡을 수 있는 영구 IAM 역할 ARN 입니다 (work/lab.env 의 PROD_OPERATOR_ROLE_ARN; account-baseline 와 같은 값).
variable "trusted_principal_arns" {
  description = "Exact existing IAM role ARNs allowed to assume the three storage roles for inspection; never STS session ARNs."
  type        = set(string) # 예: set(string)
  nullable    = false

  validation {
    condition = (
      length(var.trusted_principal_arns) > 0 &&  # 예: 1 이상
      length(var.trusted_principal_arns) <= 4 && # 예: 4 이하
      alltrue([
        for arn in var.trusted_principal_arns :
        can(regex("^arn:aws:iam::[0-9]{12}:role/[A-Za-z0-9_+=,.@/-]+$", arn)) # 예: IAM 역할 ARN 만 통과
      ])
    )
    error_message = "Supply 1-4 exact existing IAM role ARNs; root, user, wildcard and assumed-role session ARNs are rejected."
  }
}

variable "permissions_boundary_arn" {
  description = "Optional existing customer-managed permissions boundary attached to the three storage roles."
  type        = string
  default     = null # 기본값: null (boundary 를 붙이지 않음)

  validation {
    condition     = var.permissions_boundary_arn == null ? true : can(regex("^arn:aws:iam::[0-9]{12}:policy/[A-Za-z0-9_+=,.@/-]+$", var.permissions_boundary_arn)) # 예: 고객 관리형 정책 ARN
    error_message = "Supply an existing customer-managed IAM policy ARN or null."
  }
}

# 저장소 수명 주기의 기준일입니다. dev 는 traces 를 40 으로 둡니다 (후반부 Tempo 보존 30일보다 길게).
variable "signal_retention_days" {
  description = "Metrics/traces S3 backstop and reserved logs budget; logs current object expiry stays disabled."
  type        = map(number)
  default     = { metrics = 400, logs = 90, traces = 40 } # 기본값: 지표 400 · 로그 90 · 트레이스 40 (공용 모듈·Dev·Prod 기본값을 40으로 일치)
  nullable    = false

  validation {
    condition     = toset(keys(var.signal_retention_days)) == toset(["metrics", "logs", "traces"]) && alltrue([for days in values(var.signal_retention_days) : days >= 1 && floor(days) == days]) && try(var.signal_retention_days.metrics > 367 && var.signal_retention_days.logs > 31 && var.signal_retention_days.traces > 31, false) # 고정 프로그램 보존+삭제 지연보다 김
    error_message = "signal_retention_days needs exact keys and budgets greater than metrics=367, logs=31, traces=31; logs current expiration remains disabled."
  }
}

# 아래 세 값은 계약 필드에만 쓰입니다. 관리형 큐 전환 구성(queue)이 앞의 둘을 바꿉니다.
variable "active_trace_backend" {
  description = "Which message queue the trace pipeline uses now: self-managed or managed."
  type        = string
  default     = "self-managed" # 기본값: "self-managed" (클러스터 안에 직접 세운 브로커)
  nullable    = false

  validation {
    condition     = contains(["self-managed", "managed"], var.active_trace_backend) # 예: 두 값만
    error_message = "active_trace_backend must be self-managed or managed."
  }
}

variable "storage_epoch" {
  description = "Trace backend transition generation."
  type        = number
  default     = 1 # 기본값: 1 (전환 전의 초기 세대 번호)
  nullable    = false

  validation {
    condition     = var.storage_epoch >= 1 && floor(var.storage_epoch) == var.storage_epoch # 예: 1 이상의 정수
    error_message = "storage_epoch must be a whole number of 1 or more."
  }
}

variable "policy_version" {
  description = "Contract rule version."
  type        = number
  default     = 1 # 기본값: 1 (첫 버전)
  nullable    = false

  validation {
    condition     = var.policy_version >= 1 && floor(var.policy_version) == var.policy_version # 예: 1 이상의 정수
    error_message = "policy_version must be a whole number of 1 or more."
  }
}

# 뒤 챕터(data · production)가 만드는 이 계정의 저장소를 S3 사설 경로(엔드포인트 정책) 허용 목록에 더합니다. 기본값이면 소유 저장소 5개만 통과합니다.
variable "additional_bucket_names" {
  description = "Other buckets of this account that must stay reachable through the S3 gateway endpoint (for example the application media bucket)."
  type        = list(string) # 예: ["cp-prod-app-exports-222222222222-ap-northeast-2"]
  default     = []           # 기본값: []
  nullable    = false

  validation {
    condition     = alltrue([for name in var.additional_bucket_names : can(regex("^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$", name))]) # 예: S3 버킷 이름 규칙
    error_message = "additional_bucket_names must contain valid S3 bucket names."
  }
}

# versions.tf — platform/observability 루트 모듈 (dev · prod 공통 코드)
# 관측 루트 모듈과 계약: Terraform 과 provider 버전을 고정합니다. backend 선언은 backend.tf 에, 모듈 버전은 modules/observability-foundation/versions.tf 에 있습니다.

terraform {
  required_version = "= 1.16.0" # 예: "= 1.16.0" (등호로 정확한 버전 고정)

  required_providers {
    aws = {
      source  = "hashicorp/aws" # 예: "hashicorp/aws" (공식 레지스트리 경로)
      version = "= 6.62.0"      # 예: "= 6.62.0" (모듈과 같은 값)
    }
  }
}

terraform/environments/prod/platform/obs.modules/runtime-observability-foundation:
# contract.tf — modules/observability-foundation (dev · prod 루트 모듈이 공유하는 모듈)

variable "active_trace_backend" {
  description = "Which message queue the trace pipeline uses now; the managed-queue transition root (메시지 큐 전환) changes it."
  type        = string # 예: string (두 값 중 하나)
  default     = "self-managed"
  nullable    = false

  validation {
    condition     = contains(["self-managed", "managed"], var.active_trace_backend) # 예: "managed" 통과 / "msk" 거부
    error_message = "active_trace_backend must be self-managed or managed."
  }
}

variable "storage_epoch" {
  description = "Trace backend transition generation; the transition root raises it when storage rules change."
  type        = number # 예: number (1 이상의 정수)
  default     = 1      # 기본값: 1 (전환 전의 초기 세대 번호)
  nullable    = false

  validation {
    condition     = var.storage_epoch >= 1 && floor(var.storage_epoch) == var.storage_epoch # 예: 1 통과 / 0 · 1.5 거부
    error_message = "storage_epoch must be a whole number of 1 or more."
  }
}

variable "policy_version" {
  description = "Contract rule version; raise only when readers must change how they interpret the contract."
  type        = number # 예: number (1 이상의 정수)
  default     = 1      # 기본값: 1 (첫 버전)
  nullable    = false

  validation {
    condition     = var.policy_version >= 1 && floor(var.policy_version) == var.policy_version # 예: 2 통과 / 0 거부
    error_message = "policy_version must be a whole number of 1 or more."
  }
}

locals {
  # 신호별 네임스페이스은 쓰는 쪽 신원에서 끌어옵니다. 같은 값을 두 번 적지 않습니다.
  signal_namespaces = {
    for signal in ["metrics", "logs", "traces"] : signal => var.pod_identities["${signal}_writer"].namespace # 예: { metrics = "monitoring", logs = "logging", traces = "monitoring" }
  }

  query_endpoints = {
    prometheus = "http://platform-thanos-query.${local.signal_namespaces["metrics"]}.svc.cluster.local:9090"
    loki       = "http://platform-loki-gateway.${local.signal_namespaces["logs"]}.svc.cluster.local"
    tempo      = "http://platform-tempo-active-query.${local.signal_namespaces["traces"]}.svc.cluster.local:3200"
  }

  # 해시 재료입니다. 이 값이 하나라도 바뀌면 policy_hash 가 바뀝니다.
  policy_material = {
    buckets       = local.signal_bucket_names    # 예: 저장소 이름 3개
    prefixes      = local.signal_object_prefixes # 예: 접두사 3개
    roles         = local.storage_role_arns      # 예: 역할 ARN 3개
    identities    = var.pod_identities           # 예: 신원 9개
    retention     = var.signal_retention_days    # 예: 보존일 3개
    trace_backend = var.active_trace_backend     # 예: "self-managed"
    epoch         = var.storage_epoch            # 예: 1
    version       = var.policy_version           # 예: 1
  }

  policy_hash = sha256(jsonencode(local.policy_material)) # 예: 64자리 16진수 (재료가 하나만 달라져도 값이 완전히 달라짐)
}

output "observability_contract" {
  description = "Account, region, cluster, namespaces, service accounts, roles, buckets, retention, in-cluster query endpoints, trace backend state and policy hash."
  value = {
    account              = var.expected_account_id                                           # 예: "111111111111"
    region               = var.region                                                        # 예: "ap-northeast-2"
    cluster              = var.cluster_contract.name                                         # 예: "contract2whale-dev-eks"
    namespace            = local.signal_namespaces                                           # 예: { metrics = "monitoring", logs = "logging", traces = "monitoring" }
    service_account      = { for key, id in var.pod_identities : key => id.service_account } # 예: { metrics_writer = "platform-monitoring-prometheus", … } (9개)
    role                 = local.storage_role_arns                                           # 예: { writer = "…", reader = "…", maintenance = "…" }
    metrics_bucket       = var.retained.aws_s3_bucket__signal["metrics"].id                  # 예: "cp-dev-observability-metrics-111111111111-ap-northeast-2"
    logs_bucket          = var.retained.aws_s3_bucket__signal["logs"].id                     # 예: "cp-dev-observability-logs-111111111111-ap-northeast-2"
    traces_bucket        = var.retained.aws_s3_bucket__signal["traces"].id                   # 예: "cp-dev-observability-traces-111111111111-ap-northeast-2"
    retention            = var.signal_retention_days                                         # 예: { metrics = 400, logs = 90, traces = 40 }
    prometheus_endpoint  = local.query_endpoints["prometheus"]                               # 예: "http://platform-thanos-query.monitoring.svc.cluster.local:9090"
    loki_endpoint        = local.query_endpoints["loki"]                                     # 예: "http://platform-loki-gateway.logging.svc.cluster.local"
    tempo_endpoint       = local.query_endpoints["tempo"]                                    # 예: "http://platform-tempo-active-query.monitoring.svc.cluster.local:3200"
    active_trace_backend = var.active_trace_backend                                          # 예: "self-managed" (전환 구성이 바꾸는 값 1)
    storage_epoch        = var.storage_epoch                                                 # 예: 1 (전환 구성이 바꾸는 값 2)
    policy_version       = var.policy_version                                                # 예: 1 (계약의 규칙 버전)
    policy_hash          = local.policy_hash                                                 # 예: 재료로 계산한 64자리 16진수 문자열
  }
}

# identities.tf — modules/observability-foundation (dev · prod 루트 모듈이 공유하는 모듈)

locals {
  storage_role_arns = {
    writer      = aws_iam_role.observability_writer.arn      # 예: "arn:aws:iam::111111111111:role/platform/cp-dev-observability-writer"
    reader      = aws_iam_role.observability_reader.arn      # 예: "arn:aws:iam::111111111111:role/platform/cp-dev-observability-reader"
    maintenance = aws_iam_role.observability_maintenance.arn # 예: "arn:aws:iam::111111111111:role/platform/cp-dev-observability-maintenance"
  }
}

resource "aws_eks_pod_identity_association" "signal" {
  for_each = var.pod_identities # 예: 신원 9개

  cluster_name         = var.cluster_contract.name                # 예: "contract2whale-dev-eks"
  namespace            = each.value.namespace                     # 예: "monitoring" (이 시점에 없어도 연결은 만들어집니다)
  service_account      = each.value.service_account               # 예: "platform-thanos-store" (뒤따르는 주제가 만듭니다)
  role_arn             = local.storage_role_arns[each.value.role] # 예: 읽기 역할의 ARN
  disable_session_tags = false                                    # 예: false (세션 태그를 붙여 신뢰 정책의 eks-cluster-arn 조건이 성립하게 합니다)

  depends_on = [aws_iam_role_policy_attachment.observability_writer, aws_iam_role_policy_attachment.observability_reader, aws_iam_role_policy_attachment.observability_maintenance]
}

# outputs.tf — modules/observability-foundation (dev · prod 루트 모듈이 공유하는 모듈)

output "signal_bucket_names" {
  description = "Bucket name per signal."
  value       = { for key, bucket in var.retained.aws_s3_bucket__signal : key => bucket.id } # 예: { metrics = "cp-dev-observability-metrics-…", logs = "…", traces = "…" }
}

output "signal_bucket_arns" {
  description = "Bucket ARN per signal."
  value       = { for key, bucket in var.retained.aws_s3_bucket__signal : key => bucket.arn } # 예: { logs = "arn:aws:s3:::cp-dev-observability-logs-…", … }
}

output "object_prefix" {
  description = "Environment prefix used by prefixed buckets (metrics, traces)."
  value       = local.object_prefix # 예: "dev/" (metrics · traces 객체 key 앞에 붙는 환경 접두사)
}

output "signal_object_prefixes" {
  description = "Object key prefix per signal; empty for buckets used without a prefix (logs)."
  value       = local.signal_object_prefixes # 예: { metrics = "dev/", logs = "", traces = "dev/" }
}

output "storage_role_arns" {
  description = "Writer, reader and maintenance role ARNs."
  value       = local.storage_role_arns # 예: { writer = "…", reader = "…", maintenance = "…" }
}

output "pod_identity_association_ids" {
  description = "Association ID per pod identity key."
  value       = { for key, association in aws_eks_pod_identity_association.signal : key => association.association_id } # 예: { metrics_writer = "a-abcdefghijklmnop1", … }
}

output "signal_retention_days" {
  description = "Backstop expiration days per signal."
  value       = var.signal_retention_days # 예: { metrics = 400, logs = 90, traces = 40 }
}

# providers.tf — modules/observability-foundation (dev · prod 루트 모듈이 공유하는 모듈)
# 관측 저장소와 Pod Identity 연결: 자격 증명은 루트 모듈의 provider 가 받습니다 (이 모듈은 provider 블록을 두지 않음). 다른 환경의 계약이 섞여 들어오면 저장소를 만들기 전에 멈춥니다.

resource "terraform_data" "contract" {
  input = var.cluster_contract.arn # 예: "arn:aws:eks:ap-northeast-2:111111111111:cluster/contract2whale-dev-eks" (State 에 남는 marker)

  lifecycle {
    precondition {
      condition     = terraform.workspace == "default" # 예: 작업 공간을 나누지 않음 (backend key 로 환경 구분)
      error_message = "Use the default workspace and a distinct backend key for this root."
    }

    precondition {
      # 예: 계약의 ARN 이 계정 · 리전 · 이름으로 조립한 값과 같고, 리전과 Kubernetes 버전이 입력과 같아야 통과
      condition     = var.cluster_contract.arn == "arn:aws:eks:${var.region}:${var.expected_account_id}:cluster/${var.cluster_contract.name}" && var.cluster_contract.region == var.region && var.cluster_contract.kubernetes_version == "1.36"
      error_message = "cluster_contract must describe an EKS 1.36 cluster in this account and region."
    }

    precondition {
      # 예: 운영 기반 계약이 같은 계정 · 리전 · 클러스터의 것이어야 통과
      condition     = var.operations_contract.account_id == var.expected_account_id && var.operations_contract.region == var.region && var.operations_contract.cluster_name == var.cluster_contract.name
      error_message = "operations_contract belongs to a different account, region or cluster."
    }

    precondition {
      # 예: 노드 시스템 로그 그룹 이름이 이 클러스터 이름으로 조립한 값과 같아야 통과 (운영 도구 fluent_bit 을 켠 상태)
      condition     = var.operations_contract.platform_log_group_name == "/platform/${var.cluster_contract.name}/application"
      error_message = "operations_contract.platform_log_group_name must be /platform/<cluster>/application (enable fluent_bit in 운영 도구)."
    }

    precondition {
      condition     = contains(var.allowed_state_keys, local.state_key)
      error_message = "Add platform/observability/terraform.tfstate to additional_state_object_keys of the account-baseline root first (관측 State key 와 저장소 역할)."
    }
  }
}

locals {
  state_key = "platform/observability/terraform.tfstate" # 예: 이 루트 모듈의 backend key (P2: 실행 디렉터리 경로 규칙; dev · prod 가 각자 버킷에서 같은 key 사용)
}

variable "retained" {
  description = "Verified outputs from the independently retained root; immutable IDs, never whole State."
  type        = any
}

# signal-variables.tf — modules/observability-foundation (dev · prod 루트 모듈이 공유하는 모듈)

variable "operations_contract" {
  description = "Seven fields of the upstream operations contract; verified against this root's account, region and cluster."
  type = object({
    account_id              = string # 예: "111111111111"
    cluster_name            = string # 예: "contract2whale-dev-eks"
    region                  = string # 예: "ap-northeast-2"
    platform_log_group_name = string # 예: "/platform/contract2whale-dev-eks/application" (fluent_bit 을 끄면 null)
    velero_bucket_name      = string
    velero_bucket_arn       = string # 예: "arn:aws:s3:::velero-contract2whale-dev-eks-111111111111-ap-northeast-2"
    alerts_topic_arn        = string # 예: "arn:aws:sns:ap-northeast-2:111111111111:contract2whale-dev-alerts" 또는 null
  })
  nullable = false
}

# 저장소 수명 주기가 객체를 지우는 기준일입니다. 구성 요소의 보존 설정(Thanos 367일 · Loki 30일 · Tempo 30일)보다 길게 둡니다.
variable "signal_retention_days" {
  description = "Retention budgets; current-object S3 expiration applies only to metrics and traces, not Loki logs."
  type        = map(number) # 예: map(number) (신호 이름을 키로 하는 숫자 map)
  default = {
    metrics = 400 # 기본값: 400 (압축과 다운샘플을 거친 지표 블록까지 남기는 기간; Thanos 1h 요약 365일 + 삭제 지연 2일 보다 김)
    logs    = 90  # 호환 계약의 예산 기준값. logs 현재 객체 만료는 만들지 않고 Loki Compactor가 정리
    traces  = 40  # 기본값: 40 (Tempo 30일 + 압축 블록 정리 지연보다 김; Dev/Prod 공통 기본)
  }
  nullable = false

  validation {
    condition     = toset(keys(var.signal_retention_days)) == toset(["metrics", "logs", "traces"]) # 예: 키가 정확히 세 개
    error_message = "signal_retention_days must have exactly the keys metrics, logs and traces."
  }

  validation {
    condition     = alltrue([for days in values(var.signal_retention_days) : days >= 1 && floor(days) == days]) # 예: 1 이상의 정수 (Expiration Days 는 0 이 아닌 양의 정수)
    error_message = "Every retention value must be a positive whole number of days."
  }
  validation {
    # 이 교안의 고정 구성: Thanos 365일+삭제 지연 2일, Tempo 30일+압축 블록 1시간.
    # logs는 미사용 backstop 예산만 검증합니다. 빈 prefix 만료를 켜는 허가가 아닙니다.
    condition     = try(var.signal_retention_days.metrics > 367 && var.signal_retention_days.logs > 31 && var.signal_retention_days.traces > 31, false)
    error_message = "Retention budgets must exceed the pinned component retention plus deletion delay; logs current-object expiration remains disabled."
  }

}

variable "pod_identities" {
  description = "Service accounts that receive a storage role; the key becomes the association address."
  type = map(object({
    namespace       = string # 예: "monitoring" (서비스 메시 메시 편입 제외 목록에 있는 이름)
    service_account = string # 예: "platform-monitoring-prometheus" (뒤따르는 주제가 만들 ServiceAccount)
    role            = string # 예: "writer" (writer · reader · maintenance 중 하나)
  }))

  default = {
    metrics_writer     = { namespace = "monitoring", service_account = "platform-monitoring-prometheus", role = "writer" }
    metrics_reader     = { namespace = "monitoring", service_account = "platform-thanos-store", role = "reader" }
    metrics_maintainer = { namespace = "monitoring", service_account = "platform-thanos-compact", role = "maintenance" }
    logs_writer        = { namespace = "logging", service_account = "platform-loki-write", role = "writer" }
    logs_reader        = { namespace = "logging", service_account = "platform-loki-read", role = "reader" }
    logs_maintainer    = { namespace = "logging", service_account = "platform-loki-backend", role = "maintenance" }
    traces_writer      = { namespace = "monitoring", service_account = "platform-tempo-block-builder", role = "writer" }
    traces_reader      = { namespace = "monitoring", service_account = "platform-tempo-querier", role = "reader" }
    traces_maintainer  = { namespace = "monitoring", service_account = "platform-tempo-backend-worker", role = "maintenance" }
  }
  nullable = false

  validation {
    condition     = alltrue([for id in values(var.pod_identities) : contains(["writer", "reader", "maintenance"], id.role)]) # 예: 모든 항목의 role 이 세 값 중 하나
    error_message = "Every pod identity role must be writer, reader or maintenance."
  }

  validation {
    condition     = alltrue([for id in values(var.pod_identities) : contains(["monitoring", "logging"], id.namespace)]) # 예: 메시 편입 제외 네임스페이스 두 개만
    error_message = "Pod identity namespaces are limited to monitoring and logging (mesh enrollment exclusions)."
  }

  validation {
    condition     = length(distinct([for id in values(var.pod_identities) : "${id.namespace}/${id.service_account}"])) == length(var.pod_identities) # 예: (namespace, SA) 짝이 겹치지 않음
    error_message = "A service account can be associated with only one storage role."
  }

  validation {
    condition     = alltrue([for signal in ["metrics", "logs", "traces"] : contains(keys(var.pod_identities), "${signal}_writer")]) # 예: 계약의 신호별 namespace 를 *_writer 에서 끌어오므로 세 키가 필수
    error_message = "pod_identities must keep the keys metrics_writer, logs_writer and traces_writer."
  }
}

# storage-private-path.tf — modules/observability-foundation (dev · prod 루트 모듈이 공유하는 모듈)
# 뒤 챕터가 만드는 이 계정의 저장소(애플리케이션 데이터 · 운영 환경 의 앱 미디어 버킷)는 additional_bucket_names 로 허용 목록에 더합니다 — 더하지 않으면 그 버킷 요청은 이 정책의 거부 문장에 걸립니다.
# network/vpc State가 소유한 endpoint를 VPC ID와 서비스 이름으로 조회하고 이 저장소 State가 정책만 관리합니다.
# 이 정책 리소스의 destroy는 provider가 endpoint 정책을 기본 전체 허용으로 되돌릴 수 있습니다. 정상 검증 중 reset-policy를 실행하지 않습니다. 장애 복구는 BU10B05에서 이전 정책 백업·대상 계정/endpoint·확대 영향·복원 승인을 검토합니다.

# 아래 세 입력은 이 파일에서만 쓰입니다 (network/vpc State 의 vpc_id · network_logs_bucket_name, 루트 모듈 입력 additional_bucket_names).
variable "vpc_id" {
  description = "Workload VPC that owns the S3 gateway endpoint."
  type        = string # 예: "vpc-0123456789abcdef0" (network/vpc State 출력)
  nullable    = false

  validation {
    condition     = can(regex("^vpc-[0-9a-f]{8,17}$", var.vpc_id)) # "vpc-0123456789abcdef0" 통과
    error_message = "vpc_id must look like vpc-…"
  }
}

variable "network_logs_bucket_name" {
  description = "Network log bucket created by the network/vpc root; kept reachable through the endpoint."
  type        = string # 예: "cp-dev-network-logs-111111111111-ap-northeast-2" (network/vpc State 출력)
  nullable    = false

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$", var.network_logs_bucket_name)) # S3 버킷 이름 규칙
    error_message = "network_logs_bucket_name must be a valid S3 bucket name."
  }
}

variable "additional_bucket_names" {
  description = "Other buckets of this account that must stay reachable through the endpoint (for example the application media bucket created later)."
  type        = list(string) # 예: ["cp-dev-app-exports-111111111111-ap-northeast-2"] (애플리케이션 데이터 미디어 버킷)
  default     = []           # 추가 소유 버킷 없음
  nullable    = false

  validation {
    condition     = alltrue([for name in var.additional_bucket_names : can(regex("^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$", name))]) # S3 버킷 이름 규칙
    error_message = "additional_bucket_names must contain valid S3 bucket names."
  }
}

# network/vpc의 기존 S3 Gateway endpoint를 조회합니다.
data "aws_vpc_endpoint" "s3" {
  vpc_id       = var.vpc_id                       # "vpc-0123456789abcdef0"
  service_name = "com.amazonaws.${var.region}.s3" # "com.amazonaws.ap-northeast-2.s3"

  filter {
    name   = "vpc-endpoint-type" # 엔드포인트 종류로 거름
    values = ["Gateway"]
  }

  lifecycle {
    postcondition {
      condition     = self.state == "available" # endpoint가 사용 가능한 상태; 노드의 실제 route는 별도 조회
      error_message = "The S3 gateway endpoint must be available before its policy is restricted."
    }
  }
}

locals {
  # Velero null 값은 compact로 제외됩니다. 고정 개수 대신 성공 output의 실제 이름·owner 목록을 대조합니다.
  owned_bucket_names = sort(distinct(compact(concat(
    [var.network_logs_bucket_name, var.operations_contract.velero_bucket_name], # 관련 구성 로그 버킷 · 운영 도구 백업 버킷 (null 이면 compact 가 뺌)
    values(local.signal_bucket_names),                                          # 모니터링 저장소 3개
    var.additional_bucket_names                                                 # 애플리케이션 데이터 미디어 버킷 (기본값 [])
  ))))

  owned_bucket_arns = [for name in local.owned_bucket_names : "arn:aws:s3:::${name}"]   # 목록 계열 동작의 대상
  owned_object_arns = [for name in local.owned_bucket_names : "arn:aws:s3:::${name}/*"] # 객체 계열 동작의 대상

  # 컨테이너 이미지 계층이 실제로 내려오는 AWS 소유 저장소입니다 (private ECR의 starport layer 저장소). 이 endpoint 경로에서 새 layer를 받는 private ECR pull에 필요하며, ECR Public 전체 경로를 보장하지 않습니다.
  aws_owned_object_arns = [
    "arn:aws:s3:::prod-${var.region}-starport-layer-bucket/*", # 예: "arn:aws:s3:::prod-ap-northeast-2-starport-layer-bucket/*"
  ]
}

# 현재 정책의 Principal은 *이며 호출자 IAM 역할·bucket policy는 각각 평가됩니다.
# 엔드포인트 정책은 이 엔드포인트를 통과할 수 있는 요청의 범위만 정합니다. 새 권한을 주지 않으며 호출자 역할 권한과 버킷 정책은 따로 평가됩니다.
data "aws_iam_policy_document" "s3_endpoint" {
  statement {
    sid    = "AllowOwnedObservabilityBuckets"
    effect = "Allow"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = [
      "s3:GetObject",                  # 저장된 블록 읽기
      "s3:PutObject",                  # 새 블록 쓰기
      "s3:DeleteObject",               # 보존 기간이 지난 블록 정리
      "s3:AbortMultipartUpload",       # 중단된 대용량 업로드 정리
      "s3:ListMultipartUploadParts",   # 특정 멀티파트 업로드의 조각 조회
      "s3:ListBucket",                 # 접두사 단위 목록 조회
      "s3:ListBucketMultipartUploads", # 진행 중인 대용량 업로드 조회
      "s3:GetBucketLocation",          # 버킷 리전 확인 (SDK 가 먼저 호출함)
    ]

    resources = concat(local.owned_bucket_arns, local.owned_object_arns)

    condition {
      test     = "StringEquals"
      variable = "s3:ResourceAccount"      # 대상 버킷을 소유한 계정
      values   = [var.expected_account_id] # 예: ["111111111111"] (다른 계정 저장소를 배제)
    }
  }

  # (2) 컨테이너 이미지 계층이 오는 AWS 소유 저장소를 읽기만 허용합니다.
  statement {
    sid    = "AllowAwsOwnedImageAndBootstrap"
    effect = "Allow"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions   = ["s3:GetObject"]            # 계층 바이너리 내려받기 한 가지만
    resources = local.aws_owned_object_arns # ["arn:aws:s3:::prod-ap-northeast-2-starport-layer-bucket/*"]
  }

  # (3) 위 두 문장이 지정하지 않은 대상은 모두 거부합니다 (여집합으로 적어 허용 목록만 관리).
  statement {
    sid    = "DenyEverythingElse"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions       = ["s3:*"]                                                                              # 거부 문장이므로 동작을 넓게 적음
    not_resources = concat(local.owned_bucket_arns, local.owned_object_arns, local.aws_owned_object_arns) # 허용 목록만 거부 대상에서 제외
  }
}

resource "aws_vpc_endpoint_policy" "s3" {
  vpc_endpoint_id = data.aws_vpc_endpoint.s3.id                   # 예: "vpce-0123456789abcdef0"
  policy          = data.aws_iam_policy_document.s3_endpoint.json # 위 세 문장을 합친 JSON 문자열

  depends_on = [] # 모니터링 저장소가 먼저 있은 뒤 통과 범위를 좁힙니다
}

# 후반부 · 메시지 큐 전환 가 같은 이름 규칙으로 저장소를 더할 때 대조하는 계약입니다.
output "observability_network_contract" {
  description = "S3 gateway endpoint id, allowed bucket names and endpoint policy mode."
  value = {
    s3_endpoint_id          = data.aws_vpc_endpoint.s3.id # 예: "vpce-0123456789abcdef0"
    allowed_bucket_prefixes = local.owned_bucket_names    # null을 제외한 실제 소유 버킷 이름 목록
    endpoint_policy_mode    = "restricted"
  }
}

# storage-roles.tf — modules/observability-foundation (dev · prod 루트 모듈이 공유하는 모듈)
# 쓰기에 삭제 없음, 읽기에 쓰기 · 삭제 없음, 정리에만 삭제 있음. 세 역할 모두 metrics·traces의 환경 접두사(dev/) 밖 목록 조회를 거부합니다. Loki logs는 환경별 전용 버킷 전체를 쓰므로 prefix 거부의 대상이 아닙니다.

locals {
  # 앞 챕터(관련 구성 네트워크 로그 버킷)와 같은 이름 규칙 cp-<환경>-<용도>-<계정>-<리전> 입니다. 값을 직접 적지 않고 규칙으로 계산합니다.
  signal_bucket_names = {
    metrics = "cp-${var.environment}-observability-metrics-${var.expected_account_id}-${var.region}" # 예: "cp-dev-observability-metrics-111111111111-ap-northeast-2"
    logs    = "cp-${var.environment}-observability-logs-${var.expected_account_id}-${var.region}"    # 예: "cp-dev-observability-logs-111111111111-ap-northeast-2"
    traces  = "cp-${var.environment}-observability-traces-${var.expected_account_id}-${var.region}"  # 예: "cp-dev-observability-traces-111111111111-ap-northeast-2"
  }

  # 객체 key 앞에 붙는 환경 접두사입니다. Resource 와 s3:prefix 조건이 같은 값을 씁니다.
  object_prefix = "${var.environment}/" # 예: "dev/" (prod 루트 모듈은 "prod/")

  # 신호별 접두사입니다. metrics(Thanos) · traces(Tempo) 는 prefix 설정이 있어 "dev/" 아래에 쓰고, logs(Loki) 는 접두사 없이 버킷 전체를 씁니다.
  signal_object_prefixes = {
    metrics = local.object_prefix # 예: "dev/" (Thanos objstore.yml 의 prefix: dev/metrics)
    logs    = ""                  # 예: "" (Loki 는 <tenant>/… · index/… 를 버킷 최상위에 둠)
    traces  = local.object_prefix # 예: "dev/" (Tempo 의 prefix: dev/traces; 후반부)
  }

  signal_bucket_arns = { for key, name in local.signal_bucket_names : key => "arn:aws:s3:::${name}" } # 예: { metrics = "arn:aws:s3:::cp-dev-observability-metrics-…", … }

  signal_object_arns = [
    for key, arn in local.signal_bucket_arns : "${arn}/${local.signal_object_prefixes[key]}*" # 예: "arn:aws:s3:::cp-dev-observability-logs-…/*" · "…-metrics-…/dev/*"
  ]

  # 목록 조회(s3:ListBucket)는 버킷 ARN 이 대상이고 s3:prefix 조건으로 좁힙니다. 접두사 유무로 두 묶음을 나눕니다.
  prefixed_bucket_arns   = [for key, arn in local.signal_bucket_arns : arn if local.signal_object_prefixes[key] != ""] # 예: metrics · traces 버킷 ARN 2개
  unprefixed_bucket_arns = [for key, arn in local.signal_bucket_arns : arn if local.signal_object_prefixes[key] == ""] # 예: logs 버킷 ARN 1개
}

# 신뢰 정책: 세 역할을 누가 맡을 수 있는가? (1) 점검용 영구 역할 (2) 이 클러스터의 Pod Identity.
data "aws_iam_policy_document" "observability_access_trust" {
  statement {
    sid     = "TrustObservabilityOperators"
    effect  = "Allow"
    actions = ["sts:AssumeRole"] # 예: 신뢰 정책에서 의미를 갖는 유일한 액션

    principals {
      type        = "AWS"                                    # 예: "AWS" (IAM 주체)
      identifiers = sort(tolist(var.trusted_principal_arns)) # 예: ["arn:aws:iam::111111111111:role/PlatformOperator"] (정렬해 JSON 순서 고정)
    }
  }

  statement {
    sid     = "TrustObservabilityPodIdentity"
    effect  = "Allow"
    actions = ["sts:AssumeRole", "sts:TagSession"] # 예: 세션 태그를 붙이려면 두 동작이 함께 필요

    principals {
      type        = "Service"                  # 예: "Service" (AWS 서비스 주체)
      identifiers = ["pods.eks.amazonaws.com"] # 예: Pod Identity 가 쓰는 서비스 주체
    }

    condition {
      test     = "StringEquals"
      variable = "aws:RequestTag/eks-cluster-arn" # 예: 세션에 붙는 클러스터 태그
      values   = [var.cluster_contract.arn]       # 예: ["arn:aws:eks:ap-northeast-2:111111111111:cluster/contract2whale-dev-eks"]
    }
  }
}

# 쓰는 역할의 권한: 객체 넣기와 멀티파트 관련 동작만 허용합니다. 삭제는 없습니다.
data "aws_iam_policy_document" "observability_writer" {
  statement {
    sid       = "PutObservabilitySignalObjects"
    effect    = "Allow"
    actions   = ["s3:GetObject", "s3:PutObject", "s3:AbortMultipartUpload", "s3:ListMultipartUploadParts"] # 예: 존재 확인과 업로드에 필요한 4개; DeleteObject 없음
    resources = local.signal_object_arns                                                                   # 예: [".../metrics-.../dev/*", ".../logs-.../*", ".../traces-.../dev/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceAccount"     # 예: 대상 버킷의 소유 계정
      values   = [var.expected_account_id] # 예: ["111111111111"] (다른 계정 소유 버킷이면 허용되지 않음)
    }
  }

  statement {
    sid       = "ListWriteTargetsInEnvironmentPrefix"
    effect    = "Allow"
    actions   = ["s3:ListBucket"]          # 예: 환경 접두사 아래 객체 목록
    resources = local.prefixed_bucket_arns # 예: metrics · traces 버킷 ARN (객체 경로 /* 를 붙이지 않음)

    condition {
      test     = "StringLike"
      variable = "s3:prefix"                 # 예: 목록 요청의 접두사 인자
      values   = ["${local.object_prefix}*"] # 예: ["dev/*"] (prefix 를 생략하면 허용되지 않음)
    }
  }

  dynamic "statement" {
    for_each = length(local.unprefixed_bucket_arns) > 0 ? [1] : [] # 예: logs 버킷이 접두사 없이 쓰이므로 1개 문장
    content {
      sid       = "ListWriteTargetsInUnprefixedBuckets"
      effect    = "Allow"
      actions   = ["s3:ListBucket"]            # 예: 버킷 전체 목록 (Loki 는 index/ · <tenant>/ 를 최상위에서 나열)
      resources = local.unprefixed_bucket_arns # 예: logs 버킷 ARN 1개

      condition {
        test     = "StringEquals"
        variable = "aws:ResourceAccount"     # 예: 대상 버킷의 소유 계정
        values   = [var.expected_account_id] # 예: ["111111111111"]
      }
    }
  }

  statement {
    sid       = "ListMultipartUploadsInEnvironmentBuckets"
    effect    = "Allow"
    actions   = ["s3:ListBucketMultipartUploads"] # 예: 버킷의 진행 중 멀티파트 업로드 목록
    resources = values(local.signal_bucket_arns)  # 예: 이 환경의 버킷 ARN 3개

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceAccount"     # 예: 대상 버킷의 소유 계정
      values   = [var.expected_account_id] # 예: ["111111111111"]
    }
  }

  statement {
    sid       = "DenyListingOutsideEnvironmentPrefix"
    effect    = "Deny"
    actions   = ["s3:ListBucket"]          # 예: 객체 목록 동작만 거부 대상
    resources = local.prefixed_bucket_arns # 예: 접두사가 있는 버킷 ARN 2개로 한정

    condition {
      test     = "StringNotLike"
      variable = "s3:prefix"
      values   = ["${local.object_prefix}*"] # 예: ["dev/*"] (prod/ 목록 조회와 접두사 없는 조회를 거부)
    }
  }
}

# 읽는 역할의 권한: 객체 가져오기와 목록만 허용합니다.
data "aws_iam_policy_document" "observability_reader" {
  statement {
    sid       = "GetObservabilitySignalObjects"
    effect    = "Allow"
    actions   = ["s3:GetObject"]         # 예: 넣기와 지우기를 주지 않음
    resources = local.signal_object_arns # 예: 객체 ARN 패턴 3개

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceAccount"
      values   = [var.expected_account_id] # 예: ["111111111111"]
    }
  }

  statement {
    sid       = "ListReadTargetsInEnvironmentPrefix"
    effect    = "Allow"
    actions   = ["s3:ListBucket"]          # 예: 멀티파트 목록은 조회 쪽에 필요 없음
    resources = local.prefixed_bucket_arns # 예: metrics · traces 버킷 ARN

    condition {
      test     = "StringLike"
      variable = "s3:prefix"
      values   = ["${local.object_prefix}*"] # 예: ["dev/*"]
    }
  }

  dynamic "statement" {
    for_each = length(local.unprefixed_bucket_arns) > 0 ? [1] : [] # 예: logs 버킷 1개
    content {
      sid       = "ListReadTargetsInUnprefixedBuckets"
      effect    = "Allow"
      actions   = ["s3:ListBucket"]            # 예: 버킷 전체 목록
      resources = local.unprefixed_bucket_arns # 예: logs 버킷 ARN 1개

      condition {
        test     = "StringEquals"
        variable = "aws:ResourceAccount"
        values   = [var.expected_account_id] # 예: ["111111111111"]
      }
    }
  }

  statement {
    sid       = "DenyListingOutsideEnvironmentPrefix"
    effect    = "Deny"
    actions   = ["s3:ListBucket"]
    resources = local.prefixed_bucket_arns # 예: 접두사가 있는 버킷 ARN 2개

    condition {
      test     = "StringNotLike"
      variable = "s3:prefix"
      values   = ["${local.object_prefix}*"] # 예: ["dev/*"]
    }
  }
}

# 정리 역할의 권한: 기존 블록 읽기, 병합 결과 업로드, 오래된 블록 삭제를 허용합니다.
data "aws_iam_policy_document" "observability_maintenance" {
  statement {
    sid       = "CompactAndRetainObservabilityObjects"
    effect    = "Allow"
    actions   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:AbortMultipartUpload", "s3:ListMultipartUploadParts"] # 예: 블록 병합과 보존 기간 정리
    resources = local.signal_object_arns                                                                                      # 예: 객체 ARN 패턴 3개

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceAccount"
      values   = [var.expected_account_id] # 예: ["111111111111"]
    }
  }

  statement {
    sid       = "ListMaintenanceTargetsInEnvironmentPrefix"
    effect    = "Allow"
    actions   = ["s3:ListBucket"]
    resources = local.prefixed_bucket_arns # 예: metrics · traces 버킷 ARN

    condition {
      test     = "StringLike"
      variable = "s3:prefix"
      values   = ["${local.object_prefix}*"] # 예: ["dev/*"]
    }
  }

  dynamic "statement" {
    for_each = length(local.unprefixed_bucket_arns) > 0 ? [1] : [] # 예: logs 버킷 1개
    content {
      sid       = "ListMaintenanceTargetsInUnprefixedBuckets"
      effect    = "Allow"
      actions   = ["s3:ListBucket"]            # 예: 버킷 전체 목록
      resources = local.unprefixed_bucket_arns # 예: logs 버킷 ARN 1개

      condition {
        test     = "StringEquals"
        variable = "aws:ResourceAccount"
        values   = [var.expected_account_id] # 예: ["111111111111"]
      }
    }
  }

  statement {
    sid       = "ListMaintenanceMultipartUploads"
    effect    = "Allow"
    actions   = ["s3:ListBucketMultipartUploads"]
    resources = values(local.signal_bucket_arns) # 예: 버킷 ARN 3개

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceAccount"
      values   = [var.expected_account_id] # 예: ["111111111111"]
    }
  }

  statement {
    sid       = "DenyListingOutsideEnvironmentPrefix"
    effect    = "Deny"
    actions   = ["s3:ListBucket"]
    resources = local.prefixed_bucket_arns # 예: 접두사가 있는 버킷 ARN 2개

    condition {
      test     = "StringNotLike"
      variable = "s3:prefix"
      values   = ["${local.object_prefix}*"] # 예: ["dev/*"]
    }
  }
}

resource "aws_iam_policy" "observability_writer" {
  name        = "cp-${var.environment}-observability-writer" # 예: "cp-dev-observability-writer" (변경 시 정책 교체 발생)
  path        = "/platform/"
  description = "Object checks and uploads in this environment's observability prefixes." # 예: 콘솔에 표시되는 용도 설명
  policy      = data.aws_iam_policy_document.observability_writer.json                    # 예: 문장 5개를 포함한 JSON 문자열
