# variables.tf — modules/observability-foundation (dev · prod 루트 모듈이 공유하는 모듈)

variable "expected_account_id" {
  description = "AWS account that owns the cluster and the signal buckets; 12 digits."
  type        = string # 예: string (앞자리 0 이 사라지지 않도록 문자열)
  nullable    = false

  validation {
    condition     = can(regex("^[0-9]{12}$", var.expected_account_id)) # 예: "111111111111" 통과 / "1111" 거부
    error_message = "expected_account_id must contain exactly 12 digits."
  }
}

variable "region" {
  description = "Region of the cluster and the signal buckets; only ap-northeast-2 is supported."
  type        = string
  default     = "ap-northeast-2" # 기본값: "ap-northeast-2" (서울 리전)
  nullable    = false

  validation {
    condition     = var.region == "ap-northeast-2" # 예: 단일 값 비교 (앞 챕터 모듈과 같은 고정)
    error_message = "This module supports ap-northeast-2 only."
  }
}

# 저장소 이름 · 객체 접두사 · 역할 이름에 함께 들어갑니다. workspace 로 환경을 나누지 않습니다.
variable "environment" {
  description = "Environment name used in bucket names, object prefixes and role names; dev or prod."
  type        = string # 예: "dev" (dev 루트 모듈) / "prod" (prod 루트 모듈)
  nullable    = false

  validation {
    condition     = contains(["dev", "prod"], var.environment) # 예: "dev" 통과 / "stage" 거부
    error_message = "environment must be dev or prod."
  }
}

variable "cluster_contract" {
  description = "Four fields of the upstream cluster contract: name, arn, region and kubernetes_version."
  type = object({
    name               = string # 예: "contract2whale-dev-eks"
    arn                = string # 예: "arn:aws:eks:ap-northeast-2:111111111111:cluster/contract2whale-dev-eks"
    region             = string # 예: "ap-northeast-2"
    kubernetes_version = string # 예: "1.36"
  })
  nullable = false

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{1,98}[a-z0-9]$", var.cluster_contract.name)) # 예: "contract2whale-dev-eks"(22자) 통과 (소문자 DNS 형식 3~100자 — EKS 클러스터 이름 한도)
    error_message = "cluster_contract.name must be a lowercase DNS-style name of 3-100 characters."
  }

  validation {
    condition     = can(regex("^arn:aws:eks:[a-z0-9-]+:[0-9]{12}:cluster/[A-Za-z0-9_-]+$", var.cluster_contract.arn)) # 예: EKS 클러스터 ARN 형식만 통과
    error_message = "cluster_contract.arn must be an EKS cluster ARN."
  }
}

# 사람이 저장소 역할을 맡아 점검할 때 쓰는 영구 IAM 역할 ARN 입니다 (환경별 CI 보호 입력 묶음의 DEV_OPERATOR_ROLE_ARN; 관련 구성 state-access-role 과 같은 규칙).
variable "trusted_principal_arns" {
  description = "Exact existing IAM role ARNs allowed to assume the three storage roles for inspection; never STS session ARNs."
  type        = set(string) # 예: set(string) (중복 없는 집합; 순서가 정책에 영향을 주지 않음)
  nullable    = false

  validation {
    condition = (
      length(var.trusted_principal_arns) > 0 &&  # 예: 1 이상
      length(var.trusted_principal_arns) <= 4 && # 예: 4 이하
      alltrue([
        for arn in var.trusted_principal_arns :
        can(regex("^arn:aws:iam::[0-9]{12}:role/[A-Za-z0-9_+=,.@/-]+$", arn)) # 예: "arn:aws:iam::111111111111:role/PlatformOperator" 통과 / assumed-role 거부
      ])
    )
    error_message = "Supply 1-4 exact existing IAM role ARNs; root, user, wildcard and assumed-role session ARNs are rejected."
  }
}

variable "permissions_boundary_arn" {
  description = "Optional existing customer-managed permissions boundary attached to the three storage roles."
  type        = string
  default     = null # 기본값: null (boundary 를 붙이지 않음)

  validation {
    condition = var.permissions_boundary_arn == null ? true : can(regex(
      "^arn:aws:iam::[0-9]{12}:policy/[A-Za-z0-9_+=,.@/-]+$", var.permissions_boundary_arn # 예: "arn:aws:iam::111111111111:policy/PlatformBoundary"
    ))
    error_message = "Supply an existing customer-managed IAM policy ARN or null."
  }
}

# account-baseline State 의 state_object_keys 출력입니다. 이 루트 모듈의 key 가 그 목록에 있어야 저장소를 만듭니다 (providers.tf 의 계약 검사).
variable "allowed_state_keys" {
  description = "state_object_keys output of the account-baseline root; must contain this root's own state key."
  type        = list(string) # 예: ["account-baseline/terraform.tfstate", …, "platform/observability/terraform.tfstate"]
  nullable    = false

  validation {
    condition     = alltrue([for key in var.allowed_state_keys : can(regex("/terraform[.]tfstate$", key))]) # 예: 모든 항목이 terraform.tfstate 로 끝남
    error_message = "allowed_state_keys must contain state object keys ending in /terraform.tfstate."
  }
}

# versions.tf — modules/observability-foundation (dev · prod 루트 모듈이 공유하는 모듈)

terraform {
  required_version = "= 1.16.0" # 예: "= 1.16.0" (등호로 정확한 버전 고정; 루트 모듈과 같은 값)

  required_providers {
    aws = {
      source  = "hashicorp/aws" # 예: "hashicorp/aws" (공식 레지스트리 경로)
      version = "= 6.62.0"      # 예: "= 6.62.0" (앞 챕터 모듈과 같은 값)
    }
  }
}

terraform/environments/prod/account-inte.terraform/environments/prod/account-inte:
# backend.tf — account-integrations 루트 모듈 (dev · prod 공통 코드)
# 환경 root 와 실제 적용: backend 인자는 커밋하지 않는 backend.hcl 이 제공합니다 (terraform init -backend-config=backend.hcl).
# key 는 account-integrations/terraform.tfstate 로 실행 디렉터리 경로 규칙을 따릅니다 (원본 account/integrations/prod/terraform.tfstate — P2; network/vpc · platform/operations 와 같은 버킷).

terraform {
  backend "s3" {}
}

# Protected acknowledgement is included in the immutable saved Terraform plan.
variable "lifecycle_notification_backlog_mode" {
  type    = string
  default = "preserve"
  validation {
    condition     = contains(["preserve", "discard-notifications-retain-source-objects"], var.lifecycle_notification_backlog_mode)
    error_message = "Choose preserve or explicitly approve disposal of lab notification backlog; source S3 objects stay retained."
  }
}

# locals.tf — account-integrations 루트 모듈 (dev · prod 공통 코드)
# 환경 root 와 실제 적용: State 에서 읽은 출력을 모듈 입력 두 계약의 모양으로 조립합니다. 두 값 모두 이 루트 모듈이 직접 입력받지 않습니다.

locals {
  operations_contract = {
    account_id              = data.terraform_remote_state.operations.outputs.operations_contract.account_id              # 예: "111111111111"
    cluster_name            = data.terraform_remote_state.operations.outputs.operations_contract.cluster_name            # 예: "contract2whale-dev-eks"
    region                  = data.terraform_remote_state.operations.outputs.operations_contract.region                  # 예: "ap-northeast-2"
    platform_log_group_name = data.terraform_remote_state.operations.outputs.operations_contract.platform_log_group_name # 예: "/platform/contract2whale-dev-eks/application"
    velero_bucket_name      = data.terraform_remote_state.operations.outputs.operations_contract.velero_bucket_name      # 예: "velero-contract2whale-dev-eks-111111111111-ap-northeast-2"
    velero_bucket_arn       = data.terraform_remote_state.operations.outputs.operations_contract.velero_bucket_arn       # 예: "arn:aws:s3:::velero-contract2whale-dev-eks-111111111111-ap-northeast-2"
    alerts_topic_arn        = data.terraform_remote_state.operations.outputs.operations_contract.alerts_topic_arn        # 예: "arn:aws:sns:ap-northeast-2:111111111111:contract2whale-dev-alerts" 또는 null
  }

  # modules/account-integrations 의 network_logs_contract 객체입니다. network/vpc State 의 출력 두 개를 묶습니다.
  network_logs_contract = {
    bucket_name = data.terraform_remote_state.vpc.outputs.network_logs_bucket_name # 예: "cp-dev-network-logs-111111111111-ap-northeast-2"
    bucket_arn  = data.terraform_remote_state.vpc.outputs.network_logs_bucket_arn  # 예: "arn:aws:s3:::cp-dev-network-logs-111111111111-ap-northeast-2"
  }
}

# main.tf — account-integrations 루트 모듈 (dev · prod 공통 코드)

module "component" {
  source   = "../../../../modules/runtime-account-integrations"
  retained = data.terraform_remote_state.retained.outputs.retained # 예: 이 루트 모듈에서 모듈까지의 상대 경로 (네 단계 위가 저장소 최상위)

  expected_account_id                  = var.expected_account_id                  # 예: "111111111111" (숫자 12자리 계정 번호)
  region                               = var.region                               # 예: "ap-northeast-2" (서울 리전)
  operations_contract                  = local.operations_contract                # 예: platform/operations State 출력으로 조립한 7항목 object
  network_logs_contract                = local.network_logs_contract              # 예: network/vpc State 출력으로 조립한 { bucket_name, bucket_arn }
  log_bytes_per_five_minutes_threshold = var.log_bytes_per_five_minutes_threshold # 예: 52428800 (기본값, 5분 50 MiB)
  enable_external_log_consumer         = var.enable_external_log_consumer         # 예: false (기본값)
  external_log_consumer                = var.external_log_consumer                # 예: null (기본값)
  notification_email_addresses         = var.notification_email_addresses         # 예: [] (기본값)
}

# 이 디렉터리는 dev 만 받습니다. input 은 State 에 남는 marker 이며 AWS 자원을 만들지 않습니다.
resource "terraform_data" "environment_boundary" {
  input = var.environment # 예: "prod" (input 변경은 in-place 갱신)

  lifecycle {
    precondition {
      condition     = var.environment == "prod" # 예: "prod" 통과 / "prod" 거부 (prod 는 prod/account-integrations 디렉터리 — 운영 환경)
      error_message = "This directory accepts only the dev environment."
    }

    precondition {
      condition     = terraform.workspace == "default" # 예: workspace 로 환경을 나누지 않음 (backend key 로 구분)
      error_message = "Use default workspace and a distinct backend key."
    }
  }
}

# outputs.tf — account-integrations 루트 모듈 (dev · prod 공통 코드)

output "integration_contract" {
  description = "Account, region, reports bucket, alarm topic, optional external log consumer handles and the reused backup bucket ARN."
  value       = module.component.integration_contract # 예: 8개 키를 담은 object (account_id · region · reports_bucket_name · reports_bucket_arn · alarm_topic_arn · external_log_queue_url · external_log_consumer_role_arn · backup_bucket_arn)
}

# providers.tf — account-integrations 루트 모듈 (dev · prod 공통 코드)
# 환경 root 와 실제 적용: AWS API 만 사용합니다. 리전 · 계정은 State 조회 결과가 아니라 변수로 받고, 모듈의 terraform_data.contract 가 계약(operations_contract)의 계정 · 리전과 대조합니다.

provider "aws" {
  region              = var.region                # 예: "ap-northeast-2" (서울 리전; operations_contract.region 과 같아야 함)
  allowed_account_ids = [var.expected_account_id] # 예: ["111111111111"] (다른 계정이면 실행을 거부)

  # 지원되는 AWS 리소스에 공통 분류 태그를 전달합니다. IAM 권한이 아닙니다.
  default_tags {
    tags = {
      ManagedBy   = "Terraform"            # 예: "Terraform" (수동 생성 리소스와 구분)
      Environment = var.environment        # 예: "prod" (환경 구분)
      Component   = "account-integrations" # 예: "account-integrations" (이 루트 모듈이 만든 리소스에 공통으로 붙는 값)
    }
  }
}

# remote-state.tf — account-integrations 루트 모듈 (dev · prod 공통 코드)
# 환경 root 와 실제 적용: 앞 루트 모듈 두 곳(network/vpc · platform/operations)의 root 출력을 State 에서 직접 읽습니다 (P1). upstream.auto.tfvars.json 같은 입력 파일을 만들지 않습니다.
# 읽는 쪽에는 State 객체의 s3:GetObject 권한이 필요합니다 (관련 구성 의 State 역할 key 목록과 대조: network/vpc/terraform.tfstate · platform/operations/terraform.tfstate).
# network/transit State 는 읽지 않습니다 — 이 루트 모듈은 TGW · Firewall 의 존재를 요구하지 않으며 transit 은 down.sh 로 비워질 수 있습니다.

# 관련 구성 · 관련 구성 의 네트워크 루트 모듈입니다. locals.tf 가 로그 버킷 이름 · ARN 두 출력을 network_logs_contract 로 묶습니다.
data "terraform_remote_state" "vpc" {
  backend = "s3" # 예: "s3" (앞 루트 모듈이 State 를 둔 방식)

  config = {
    bucket = var.state_bucket_name           # 예: "company-dev-tfstate-111111111111"
    key    = "network/vpc/terraform.tfstate" # 예: network/vpc 루트 모듈의 key (루트 모듈 분리와 입력 계약)
    region = var.region                      # 예: "ap-northeast-2"
  }

  lifecycle {
    # 출력 계약과 계약 테스트 의 로그 버킷 출력 두 개가 모두 있어야 합니다 (flow/ · dns/ 로그를 받는 버킷).
    postcondition {
      condition     = can(self.outputs.network_logs_bucket_name) && can(self.outputs.network_logs_bucket_arn) # 예: 두 출력 모두 존재
      error_message = "network/vpc state must expose network_logs_bucket_name and network_logs_bucket_arn (apply 출력 계약과 계약 테스트 first)."
    }
  }
}

data "terraform_remote_state" "operations" {
  backend = "s3" # 예: "s3"

  config = {
    bucket = var.state_bucket_name                   # 예: "company-dev-tfstate-111111111111" (같은 버킷)
    key    = "platform/operations/terraform.tfstate" # 예: platform/operations 루트 모듈의 key (운영 기반 루트 모듈과 계약; 원본 platform/operations/prod/terraform.tfstate — P2)
    region = var.region                              # 예: "ap-northeast-2"
  }

  lifecycle {
    postcondition {
      condition = alltrue([
        for name in ["account_id", "cluster_name", "region", "platform_log_group_name", "velero_bucket_name", "velero_bucket_arn", "alerts_topic_arn"] :
        contains(keys(try(self.outputs.operations_contract, {})), name) # 예: 7개 모두 operations_contract 에 존재
      ])
      error_message = "platform/operations state must expose operations_contract with its seven items (apply 운영 기반 루트 모듈과 계약 first)."
    }

    # 로그량 알람의 dimension 이므로 fluent_bit 을 끈 운영 기반 구성(platform_log_group_name = null)은 받지 않습니다.
    postcondition {
      condition     = try(self.outputs.operations_contract.platform_log_group_name, null) != null # 예: "/platform/contract2whale-dev-eks/application"
      error_message = "operations_contract.platform_log_group_name must not be null (enable fluent_bit in platform/operations)."
    }
  }
}

data "terraform_remote_state" "retained" {
  backend = "s3"
  config = {
    bucket  = var.state_bucket_name
    key     = "retained/account-integrations/terraform.tfstate"
    region  = var.region
    encrypt = true
  }
}

# variables.tf — account-integrations 루트 모듈 (dev · prod 공통 코드)
# 대신 state_bucket_name 과 environment 를 받습니다. 원본의 "cat modules/account-integrations/variables.tf > variables.tf" 복사는 쓰지 않습니다 (내용이 다름).

variable "expected_account_id" {
  description = "AWS account that owns the platform and receives the integration resources; 12 digits."
  type        = string # 예: string (앞자리 0 이 사라지지 않도록 문자열)
  nullable    = false

  validation {
    condition     = can(regex("^[0-9]{12}$", var.expected_account_id)) # 예: "111111111111" 통과
    error_message = "Account ID must be 12 digits."
  }
}

# 클러스터 · 로그 버킷이 서울 리전에 있으므로 리전도 고정합니다. 모듈은 operations_contract.region 이 같은 값인지 따로 검사합니다.
variable "region" {
  description = "AWS region for this root; only ap-northeast-2 is supported."
  type        = string
  default     = "ap-northeast-2" # 기본값: "ap-northeast-2"
  nullable    = false

  validation {
    condition     = var.region == "ap-northeast-2" # 예: 단일 값 비교
    error_message = "This root supports ap-northeast-2 only."
  }
}

# main.tf 의 environment_boundary 가 이 디렉터리에서는 "prod" 만 허용합니다.
variable "environment" {
  description = "Explicit environment name, 2-20 lowercase letters, digits or hyphens."
  type        = string
  nullable    = false

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{1,19}$", var.environment)) # 예: "prod" 통과 / "Dev" 거부
    error_message = "Use a 2-20 character lowercase environment name."
  }
}

# 앞 루트 모듈(network/vpc · platform/operations) 의 State 가 있는 버킷입니다. backend.hcl 의 bucket 과 같은 값입니다.
variable "state_bucket_name" {
  description = "S3 bucket holding the network/vpc and platform/operations states read by terraform_remote_state."
  type        = string # 예: "company-dev-tfstate-111111111111" (CI 보호 입력의 DEV_STATE_BUCKET)
  nullable    = false

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$", var.state_bucket_name)) # 예: S3 버킷 이름 규칙
    error_message = "state_bucket_name must be a valid S3 bucket name."
  }
}

variable "log_bytes_per_five_minutes_threshold" {
  description = "IncomingBytes sum per 5 minutes that raises the platform log volume alarm (module validation requires > 0)."
  type        = number
  default     = 52428800 # 기본값: 52428800 (50 MiB / 5분)
  nullable    = false
}

variable "enable_external_log_consumer" {
  description = "Create the SQS queue, bucket notification, cross-account role and queue-age alarm only when a real external consumer exists."
  type        = bool
  default     = false # 기본값: false (선택 기능 꺼짐 — 리소스 0개)
  nullable    = false
}

# 값은 terraform.tfvars 가 아니라 -var-file 또는 TF_VAR_external_log_consumer 로 공급합니다 (비밀 입력).
variable "external_log_consumer" {
  description = "Real IAM role ARN of the external consumer and the agreed External ID (16+ characters); null unless the consumer is enabled."
  type = object({
    principal_role_arn = string # 예: "arn:aws:iam::222222222222:role/log-consumer"
    external_id        = string # 예: "AGREED-EXTERNAL-ID-0001"
  })
  default   = null # 기본값: null (모듈 validation 이 형식을 검사)
  sensitive = true # 예: true (plan · output 화면에서 값을 가림)
}

variable "notification_email_addresses" {
  description = "Email addresses that receive the SNS confirmation mail; empty set creates no subscription."
  type        = set(string)
  default     = [] # 기본값: [] (구독 0개; 모듈 validation 이 형식을 검사)
  nullable    = false
}

# versions.tf — account-integrations 루트 모듈 (dev · prod 공통 코드)
# 환경 root 와 실제 적용: Terraform 과 provider 버전을 고정합니다. backend 선언은 backend.tf 에, 모듈 버전은 modules/account-integrations/versions.tf 에 있습니다.

terraform {
  required_version = "= 1.16.0" # 예: "= 1.16.0" (등호로 정확한 버전 고정)

  required_providers {
    aws = {
      source  = "hashicorp/aws" # 예: "hashicorp/aws" (공식 레지스트리 경로)
      version = "= 6.62.0"      # 예: "= 6.62.0" (모듈과 같은 값)
    }
  }
}

terraform/environments/prod/account-inte.modules/runtime-account-integrations/ala:
# alarms.tf — modules/account-integrations (dev · prod 루트 모듈이 공유하는 모듈)
# 주제만 만든 상태에서는 외부에 통보되지 않습니다. 구독 확인(confirmation)은 사람이 메일에서 수행하는 별도 운영 단계입니다.
# 큐 적체 알람(aws_cloudwatch_metric_alarm.log_queue_age)은 큐를 참조하므로 큐와 같은 파일(선택 외부 로그 소비자 external-log-consumer.tf)에 있습니다.

resource "aws_sns_topic" "platform" {
  name = "${var.operations_contract.cluster_name}-platform-operations" # 예: "contract2whale-dev-eks-platform-operations" (알림 루트 모듈과 설치 검사 의 contract2whale-dev-alerts 와 다른 주제)

  depends_on = [terraform_data.contract] # 예: 계약 검사를 통과한 뒤에 만듭니다
}

# 같은 계정의 지정 접두사 알람 ARN 에서 오는 CloudWatch 서비스 요청만 sns:Publish 를 허용합니다.
resource "aws_sns_topic_policy" "platform" {
  arn = aws_sns_topic.platform.arn # 예: "arn:aws:sns:ap-northeast-2:111111111111:contract2whale-dev-eks-platform-operations"
  policy = jsonencode({
    Version = "2012-10-17" # 예: "2012-10-17" (정책 문법 버전, 날짜가 아닙니다)
    Statement = [{
      Sid       = "AllowCloudWatchAlarms"                  # 예: "AllowCloudWatchAlarms" (사람이 읽는 문장 식별자)
      Effect    = "Allow"                                  # 예: "Allow" (조건에 맞는 요청을 허용합니다)
      Principal = { Service = "cloudwatch.amazonaws.com" } # 예: CloudWatch 서비스만 주체로 허용합니다
      Action    = "sns:Publish"                            # 예: "sns:Publish" (메시지를 넣는 동작만 허용)
      Resource  = aws_sns_topic.platform.arn               # 예: 이 주제 하나만 대상으로 합니다
      Condition = {
        StringEquals = { "aws:SourceAccount" = var.expected_account_id }                                                                                   # 예: "111111111111" (같은 계정의 알람만)
        ArnLike      = { "aws:SourceArn" = "arn:aws:cloudwatch:${var.region}:${var.expected_account_id}:alarm:${var.operations_contract.cluster_name}-*" } # 예: "arn:aws:cloudwatch:ap-northeast-2:111111111111:alarm:contract2whale-dev-eks-*"
      }
    }]
  })
}

# 주소를 넣고 apply 하면 SNS 가 실제 확인 메일을 보냅니다. 확인 전에는 수신이 완료되지 않습니다 (PendingConfirmation).
resource "aws_sns_topic_subscription" "email" {
  for_each  = var.notification_email_addresses # 예: [] 이면 구독 0개, 주소 1개면 구독 1개
  topic_arn = aws_sns_topic.platform.arn       # 예: 위에서 만든 주제의 ARN
  protocol  = "email"                          # 예: "email" (확인 절차가 필요한 전달 방식)
  endpoint  = each.value                       # 예: "ops-alerts@example.com" (본인이 받는 주소)
}

# 플랫폼 로그 그룹의 5분 수집 바이트가 임계값을 2구간 연속 넘으면 ALARM. 수집량 · 비용 신호이며 앱 동작이나 로그 유실 지표가 아닙니다.
resource "aws_cloudwatch_metric_alarm" "platform_log_volume" {
  alarm_name          = "${var.operations_contract.cluster_name}-platform-log-ingestion-spike"                                    # 예: "contract2whale-dev-eks-platform-log-ingestion-spike" (주제 정책의 접두사 조건과 일치)
  alarm_description   = "Platform log group IncomingBytes over 5-minute threshold; volume and cost, not app behavior or log loss" # 예: 콘솔에 표시할 설명
  namespace           = "AWS/Logs"                                                                                                # 예: "AWS/Logs" (CloudWatch Logs 의 지표 묶음)
  metric_name         = "IncomingBytes"                                                                                           # 예: "IncomingBytes" (수집된 바이트 수)
  dimensions          = { LogGroupName = var.operations_contract.platform_log_group_name }                                        # 예: { LogGroupName = "/platform/contract2whale-dev-eks/application" }
  statistic           = "Sum"                                                                                                     # 예: "Sum" (구간 안의 값을 더합니다)
  period              = 300                                                                                                       # 예: 300 (5분 구간)
  evaluation_periods  = 2                                                                                                         # 예: 2 (최근 구간 2개를 봅니다)
  datapoints_to_alarm = 2                                                                                                         # 예: 2 (그중 2개가 초과해야 ALARM)
  threshold           = var.log_bytes_per_five_minutes_threshold                                                                  # 예: 52428800 (50 MiB)
  comparison_operator = "GreaterThanThreshold"                                                                                    # 예: 임계값보다 클 때 초과로 셉니다
  treat_missing_data  = "notBreaching"                                                                                            # 예: "notBreaching" (결측 구간을 미달로 셉니다)
  alarm_actions       = [aws_sns_topic.platform.arn]                                                                              # 예: ALARM 이 될 때 이 주제로 보냅니다
  ok_actions          = [aws_sns_topic.platform.arn]                                                                              # 예: OK 로 돌아올 때도 이 주제로 보냅니다

  depends_on = [aws_sns_topic_policy.platform] # 예: 발행 정책이 붙은 뒤에 알람을 만듭니다
}

terraform/environments/prod/account-inte.modules/runtime-account-integrations/ext:
# external-log-consumer.tf — modules/account-integrations (dev · prod 루트 모듈이 공유하는 모듈)
# 실제 상대의 Role ARN 과 합의한 External ID 가 있기 전에는 켜지 않습니다. 켜면 앞 네트워크 구성이 만든 로그 버킷에 알림 설정이 붙습니다 (버킷 자체는 재선언하지 않음).

resource "aws_sqs_queue" "logs" {
  count                      = var.enable_external_log_consumer ? 1 : 0                     # 예: 기본 0개, 켜면 1개
  name                       = "${var.operations_contract.cluster_name}-network-log-events" # 예: "contract2whale-dev-eks-network-log-events"
  sqs_managed_sse_enabled    = true                                                         # 예: true (SQS 가 관리하는 키로 저장 암호화)
  message_retention_seconds  = 1209600                                                      # 예: 1209600 (14일 동안 보관)
  visibility_timeout_seconds = 300                                                          # 예: 300 (받은 메시지를 5분 동안 숨김)
  receive_wait_time_seconds  = 20                                                           # 예: 20 (최대 20초까지 기다리는 긴 폴링)

  depends_on = [terraform_data.contract] # 예: 계약 검사를 통과한 뒤에 만듭니다
}

# 로그 버킷(같은 계정)에서 오는 S3 서비스 요청만 sqs:SendMessage 를 허용합니다.
resource "aws_sqs_queue_policy" "logs" {
  count     = var.enable_external_log_consumer ? 1 : 0 # 예: 기본 0개, 켜면 1개
  queue_url = aws_sqs_queue.logs[0].url                # 예: "https://sqs.ap-northeast-2.amazonaws.com/111111111111/contract2whale-dev-eks-network-log-events"
  policy = jsonencode({
    Version = "2012-10-17" # 예: "2012-10-17" (정책 문법 버전, 날짜가 아닙니다)
    Statement = [{
      Effect    = "Allow"                          # 예: "Allow" (조건에 맞는 요청을 허용합니다)
      Principal = { Service = "s3.amazonaws.com" } # 예: S3 서비스만 주체로 허용합니다
      Action    = "sqs:SendMessage"                # 예: "sqs:SendMessage" (메시지를 넣는 동작만 허용)
      Resource  = aws_sqs_queue.logs[0].arn        # 예: "arn:aws:sqs:ap-northeast-2:111111111111:contract2whale-dev-eks-network-log-events"
      Condition = {
        ArnEquals    = { "aws:SourceArn" = var.network_logs_contract.bucket_arn } # 예: "arn:aws:s3:::cp-dev-network-logs-111111111111-ap-northeast-2"
        StringEquals = { "aws:SourceAccount" = var.expected_account_id }          # 예: "111111111111" (같은 계정의 버킷만)
      }
    }]
  })
}

# S3 한 버킷의 notification 설정 전체는 하나의 resource · State 가 소유해야 합니다.
# 앞 네트워크 구성이 만든 같은 버킷의 flow/ 와 dns/ 를 queue 블록 두 개로 한 리소스에서 관리합니다.
resource "aws_s3_bucket_notification" "network_logs" {
  count  = var.enable_external_log_consumer ? 1 : 0 # 예: 기본 0개, 켜면 1개
  bucket = var.network_logs_contract.bucket_name    # 예: "cp-dev-network-logs-111111111111-ap-northeast-2"

  queue {
    id            = "flow-logs"               # 예: "flow-logs" (알림 항목 식별자)
    queue_arn     = aws_sqs_queue.logs[0].arn # 예: 위에서 만든 큐의 ARN
    events        = ["s3:ObjectCreated:*"]    # 예: Put · Copy · Multipart 완료를 알리며 같은 키의 다시 쓰기도 포함합니다
    filter_prefix = "flow/"                   # 예: "flow/" (VPC Flow Log 저장 경로)
  }

  queue {
    id            = "dns-logs"                # 예: "dns-logs" (알림 항목 식별자)
    queue_arn     = aws_sqs_queue.logs[0].arn # 예: 같은 큐로 보냅니다
    events        = ["s3:ObjectCreated:*"]    # 예: Put · Copy · Multipart 완료
    filter_prefix = "dns/"                    # 예: "dns/" (DNS 질의 로그 저장 경로)
  }

  depends_on = [aws_sqs_queue_policy.logs] # 예: 큐 정책을 붙인 뒤에 알림을 설정합니다 (S3 가 정책을 검사)
}

# 상대 계정의 Role 만 합의된 External ID 로 이 Role 을 맡을 수 있습니다.
resource "aws_iam_role" "external_log_consumer" {
  count = var.enable_external_log_consumer ? 1 : 0                      # 예: 기본 0개, 켜면 1개
  name  = "${var.operations_contract.cluster_name}-external-log-reader" # 예: "contract2whale-dev-eks-external-log-reader"
  assume_role_policy = jsonencode({
    Version = "2012-10-17" # 예: "2012-10-17" (정책 문법 버전, 날짜가 아닙니다)
    Statement = [{
      Effect    = "Allow"                                                                                  # 예: "Allow" (조건에 맞는 요청을 허용합니다)
      Principal = { AWS = try(var.external_log_consumer.principal_role_arn, "") }                          # 예: "arn:aws:iam::222222222222:role/log-consumer" (기본 null 이면 "" — count 0 이라 평가되지 않음)
      Action    = "sts:AssumeRole"                                                                         # 예: "sts:AssumeRole" (이 Role 을 맡는 동작)
      Condition = { StringEquals = { "sts:ExternalId" = try(var.external_log_consumer.external_id, "") } } # 예: 합의한 External ID 와 같아야 허용합니다
    }]
  })

  depends_on = [terraform_data.contract] # 예: 계약 검사를 통과한 뒤에 만듭니다
}

# 큐 동작 5종과 로그 버킷의 flow/* · dns/* 객체 읽기만 허용합니다 (버킷 전체 · 목록 조회 없음).
resource "aws_iam_role_policy" "external_log_consumer" {
  count = var.enable_external_log_consumer ? 1 : 0 # 예: 기본 0개, 켜면 1개
  role  = aws_iam_role.external_log_consumer[0].id # 예: "contract2whale-dev-eks-external-log-reader"
  name  = "consume-network-logs"                   # 예: "consume-network-logs" (Role 안에서의 정책 이름)
  policy = jsonencode({
    Version = "2012-10-17" # 예: "2012-10-17" (정책 문법 버전, 날짜가 아닙니다)
    Statement = [
      {
        Effect   = "Allow"                                                                                                                 # 예: 이 큐 하나에서 메시지를 받고 지우고 상태를 조회하는 동작만 허용
        Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl", "sqs:ChangeMessageVisibility"] # 예: 큐 동작 5종
        Resource = aws_sqs_queue.logs[0].arn                                                                                               # 예: 큐 ARN
      },
      {
        Effect   = "Allow"                                                                                             # 예: 두 경로의 객체 읽기만 허용
        Action   = ["s3:GetObject"]                                                                                    # 예: 객체 읽기
        Resource = ["${var.network_logs_contract.bucket_arn}/flow/*", "${var.network_logs_contract.bucket_arn}/dns/*"] # 예: ["arn:aws:s3:::cp-dev-network-logs-…/flow/*", "…/dns/*"]
      }
    ]
  })
}

# 가장 오래된 미삭제 메시지가 15분(900초)을 넘으면 소비 지연 신호입니다. 소비 중단뿐 아니라 처리 속도·재시도·적체도 확인합니다. 큐와 같은 스위치로 켜집니다.
resource "aws_cloudwatch_metric_alarm" "log_queue_age" {
  count               = var.enable_external_log_consumer ? 1 : 0                         # 예: 기본 0개, 외부 소비자를 켜면 1개
  alarm_name          = "${var.operations_contract.cluster_name}-external-log-queue-age" # 예: "contract2whale-dev-eks-external-log-queue-age" (주제 정책의 접두사 조건과 일치)
  namespace           = "AWS/SQS"                                                        # 예: "AWS/SQS" (SQS 의 지표 묶음)
  metric_name         = "ApproximateAgeOfOldestMessage"                                  # 예: 미삭제 메시지의 근사 최대 나이(초)
  dimensions          = { QueueName = aws_sqs_queue.logs[0].name }                       # 예: { QueueName = "contract2whale-dev-eks-network-log-events" }
  statistic           = "Maximum"                                                        # 예: "Maximum" (구간 안의 최댓값을 봅니다)
  period              = 300                                                              # 예: 300 (5분 구간)
  evaluation_periods  = 2                                                                # 예: 2 (최근 구간 2개를 봅니다)
  threshold           = 900                                                              # 예: 900 (15분)
  comparison_operator = "GreaterThanThreshold"                                           # 예: 임계값보다 클 때 초과로 셉니다
  treat_missing_data  = "notBreaching"                                                   # 예: "notBreaching" (결측 구간을 미달로 셉니다)
  alarm_actions       = [aws_sns_topic.platform.arn]                                     # 예: ALARM 이 될 때 이 주제로 보냅니다

  depends_on = [aws_sns_topic_policy.platform] # 예: 발행 정책이 붙은 뒤에 이 알람을 만듭니다
}

terraform/environments/prod/account-inte.modules/runtime-account-integrations/mai:
# main.tf — modules/account-integrations (dev · prod 루트 모듈이 공유하는 모듈)
# 보고 버킷은 텍스트 · JSON 보고서용입니다. 운영 기반 구성의 Velero 백업 버킷과 네트워크 구성의 로그 버킷은 다시 선언하지 않습니다 (이름 · ARN 만 계약으로 받음).

# AWS 리소스를 만들지 않고, 잘못된 workspace · 계약 조합을 plan 단계에서 차단합니다 (모든 리소스가 depends_on 으로 이 검사를 기다림).
resource "terraform_data" "contract" {
  input = var.operations_contract.cluster_name # 예: "contract2whale-dev-eks" (값이 바뀌면 검사를 다시 실행합니다)

  lifecycle {
    precondition {
      # 예: default workspace 이고 계약의 계정 · 리전이 입력과 같아야 통과합니다
      condition     = terraform.workspace == "default" && var.operations_contract.account_id == var.expected_account_id && var.operations_contract.region == var.region
      error_message = "default workspace 및 동일 계정/리전의 운영 기반 구성 계약이 필요합니다."
    }

    precondition {
      # 예: "contract2whale-dev-eks" 는 통과하고(보고 버킷 이름 58자), 보고 버킷 이름이 63자를 넘거나 ARN 이 버킷 이름과 다르면 거부합니다
      condition     = can(regex("^[a-z][a-z0-9-]{1,98}[a-z0-9]$", var.operations_contract.cluster_name)) && length("reports-${var.operations_contract.cluster_name}-${var.expected_account_id}-${var.region}") <= 63 && var.network_logs_contract.bucket_arn == "arn:aws:s3:::${var.network_logs_contract.bucket_name}"
      error_message = "클러스터 이름(보고 버킷 이름 63자 이내)과 네트워크 로그 버킷 이름/ARN 계약을 확인하세요."
    }

    precondition {
      # 예: 기능을 끄면 항상 통과하고, 켜면 external_log_consumer 객체가 있어야 통과합니다
      condition     = !var.enable_external_log_consumer || var.external_log_consumer != null
      error_message = "외부 소비자를 켜려면 실제 principal_role_arn과 external_id가 필요합니다."
    }
  }
}











# HTTP(암호화되지 않은 전송) 요청만 거부합니다. AWS 서비스 주체의 요청은 예외입니다.

